const QSet<QString>& system_spell_dictionary() {
  static const QSet<QString> words = []() {
    QSet<QString> loaded{
        QStringLiteral("carousel"), QStringLiteral("looksy"), QStringLiteral("instagram"),
        QStringLiteral("tiktok"), QStringLiteral("cta"), QStringLiteral("url"),
    };
    QFile dictionary(QStringLiteral("/usr/share/dict/words"));
    if (!dictionary.open(QIODevice::ReadOnly)) {
      return loaded;
    }
    const auto lines = dictionary.readAll().split('\n');
    loaded.reserve(lines.size());
    for (const auto& line : lines) {
      const auto word = QString::fromUtf8(line).trimmed().toLower();
      if (!word.isEmpty()) {
        loaded.insert(word);
      }
    }
    return loaded;
  }();
  return words;
}

double linear_color_component(double component) {
  component /= 255.0;
  return component <= 0.04045 ? component / 12.92
                              : qPow((component + 0.055) / 1.055, 2.4);
}

double relative_luminance(const QColor& color) {
  return 0.2126 * linear_color_component(color.red()) +
         0.7152 * linear_color_component(color.green()) +
         0.0722 * linear_color_component(color.blue());
}

double contrast_ratio(const QColor& first, const QColor& second) {
  const auto first_luminance = relative_luminance(first);
  const auto second_luminance = relative_luminance(second);
  const auto lighter = qMax(first_luminance, second_luminance);
  const auto darker = qMin(first_luminance, second_luminance);
  return (lighter + 0.05) / (darker + 0.05);
}

QColor average_opaque_image_color(const QString& file_path) {
  QImage image(file_path);
  if (image.isNull()) {
    return {};
  }
  image = image.scaled(64, 64, Qt::KeepAspectRatio, Qt::SmoothTransformation)
              .convertToFormat(QImage::Format_ARGB32);
  double red = 0.0;
  double green = 0.0;
  double blue = 0.0;
  double weight = 0.0;
  for (int y = 0; y < image.height(); ++y) {
    for (int x = 0; x < image.width(); ++x) {
      const auto color = image.pixelColor(x, y);
      const auto alpha = color.alphaF();
      if (alpha <= 0.02) {
        continue;
      }
      red += color.redF() * alpha;
      green += color.greenF() * alpha;
      blue += color.blueF() * alpha;
      weight += alpha;
    }
  }
  if (weight <= 0.0) {
    return {};
  }
  return QColor::fromRgbF(
      static_cast<float>(red / weight),
      static_cast<float>(green / weight),
      static_cast<float>(blue / weight), 1.0F);
}

QString json_sha256(const QJsonObject& object) {
  return QString::fromLatin1(
      QCryptographicHash::hash(
          QJsonDocument(object).toJson(QJsonDocument::Compact),
          QCryptographicHash::Sha256)
          .toHex());
}

QString file_sha256(const QString& file_path) {
  QFile file(file_path);
  if (!file.open(QIODevice::ReadOnly)) {
    return {};
  }
  QCryptographicHash hash(QCryptographicHash::Sha256);
  while (!file.atEnd()) {
    hash.addData(file.read(1024 * 1024));
  }
  return QString::fromLatin1(hash.result().toHex());
}

