QVariant normalized_layout_setting(const QString& key, const QVariant& value) {
  if (key == QStringLiteral("snappingEnabled") || key == QStringLiteral("guidesEnabled") ||
      key == QStringLiteral("rulersEnabled") || key == QStringLiteral("gridEnabled") ||
      key == QStringLiteral("thirdsEnabled") || key == QStringLiteral("safeEnabled") ||
      key == QStringLiteral("bleedEnabled") || key == QStringLiteral("snapToGrid") ||
      key == QStringLiteral("aspectLocked")) {
    return value.toBool();
  }
  if (key == QStringLiteral("columns") || key == QStringLiteral("rows")) {
    return qBound(1, value.toInt(), 12);
  }
  if (key == QStringLiteral("marginX") || key == QStringLiteral("marginY")) {
    return qBound(0.0, value.toDouble(), 480.0);
  }
  if (key == QStringLiteral("gutterX") || key == QStringLiteral("gutterY")) {
    return qBound(0.0, value.toDouble(), 240.0);
  }
  if (key == QStringLiteral("safeInset")) {
    return qBound(0.01, value.toDouble(), 0.25);
  }
  if (key == QStringLiteral("bleed")) {
    return qBound(0.0, value.toDouble(), 240.0);
  }
  if (key == QStringLiteral("snapThreshold")) {
    return qBound(2.0, value.toDouble(), 40.0);
  }
  if (key == QStringLiteral("nudgeStep")) {
    return qBound(0.5, value.toDouble(), 20.0);
  }
  if (key == QStringLiteral("largeNudgeStep")) {
    return qBound(2.0, value.toDouble(), 200.0);
  }
  if (key == QStringLiteral("guideOpacity")) {
    return qBound(0.1, value.toDouble(), 1.0);
  }
  if (key == QStringLiteral("guideColor")) {
    const QColor color(value.toString());
    return color.isValid() ? color.name(QColor::HexRgb) : QStringLiteral("#5fc2d8");
  }
  if (key == QStringLiteral("safePreset")) {
    const auto preset = value.toString().trimmed().toLower();
    if (preset == QStringLiteral("instagram-feed") ||
        preset == QStringLiteral("reels-stories") ||
        preset == QStringLiteral("tiktok") || preset == QStringLiteral("device-ui") ||
        preset == QStringLiteral("custom")) {
      return preset;
    }
    return QStringLiteral("custom");
  }
  return {};
}

QVariantMap normalized_layout_settings(const QVariantMap& source) {
  auto settings = default_layout_settings();
  for (auto iterator = settings.begin(); iterator != settings.end(); ++iterator) {
    if (iterator.key() == QStringLiteral("customGuides") || !source.contains(iterator.key())) {
      continue;
    }
    const auto normalized = normalized_layout_setting(iterator.key(), source.value(iterator.key()));
    if (normalized.isValid()) {
      iterator.value() = normalized;
    }
  }

  QVariantList guides;
  const auto source_guides = source.value(QStringLiteral("customGuides")).toList();
  guides.reserve(qMin(source_guides.size(), 128));
  for (const auto& value : source_guides) {
    const auto guide = value.toMap();
    const auto orientation = guide.value(QStringLiteral("orientation")).toString();
    const auto guide_id = guide.value(QStringLiteral("guideId")).toInt();
    if ((orientation != QStringLiteral("vertical") && orientation != QStringLiteral("horizontal")) ||
        guide_id <= 0) {
      continue;
    }
    guides.push_back(QVariantMap{
        {QStringLiteral("guideId"), guide_id},
        {QStringLiteral("orientation"), orientation},
        {QStringLiteral("position"), qBound(-10000.0, guide.value(QStringLiteral("position")).toDouble(), 50000.0)},
    });
    if (guides.size() >= 128) {
      break;
    }
  }
  settings.insert(QStringLiteral("customGuides"), guides);
  return settings;
}

