QString transformed_text(const QString& text, const QString& text_case) {
  if (text_case == QStringLiteral("uppercase")) {
    return text.toUpper();
  }
  if (text_case == QStringLiteral("lowercase")) {
    return text.toLower();
  }
  if (text_case == QStringLiteral("title")) {
    auto words = text.toLower().split(' ');
    for (auto& word : words) {
      if (!word.isEmpty()) {
        word[0] = word[0].toUpper();
      }
    }
    return words.join(' ');
  }
  return text;
}

