QVariantMap generate_bounded_subject_cutout(QImage source_image) {
  QVariantMap result_map;
  if (source_image.isNull()) {
    result_map.insert(QStringLiteral("error"), QStringLiteral("Unable to decode the selected photo."));
    return result_map;
  }
  const auto result = generate_subject_mask(source_image);
  if (!result.success || result.mask_data.size() != result.width * result.height ||
      result.width <= 0 || result.height <= 0) {
    result_map.insert(
        QStringLiteral("error"),
        result.error_message.isEmpty() ? QStringLiteral("Subject masking did not return a usable matte.")
                                       : result.error_message);
    return result_map;
  }
  QImage mask(
      reinterpret_cast<const uchar*>(result.mask_data.constData()),
      result.width,
      result.height,
      result.width,
      QImage::Format_Grayscale8);
  mask = mask.copy();
  if (qMax(mask.width(), mask.height()) > 512) {
    mask = mask.scaled(512, 512, Qt::KeepAspectRatio, Qt::SmoothTransformation);
  }
  QByteArray bounded_data(mask.width() * mask.height(), '\0');
  for (int y = 0; y < mask.height(); ++y) {
    std::memcpy(
        bounded_data.data() + y * mask.width(),
        mask.constScanLine(y),
        static_cast<std::size_t>(mask.width()));
  }
  result_map.insert(QStringLiteral("success"), true);
  result_map.insert(QStringLiteral("maskData"), bounded_data);
  result_map.insert(QStringLiteral("maskWidth"), mask.width());
  result_map.insert(QStringLiteral("maskHeight"), mask.height());
  return result_map;
}

QByteArray box_filter_mask(
    const QByteArray& source,
    int width,
    int height,
    int radius,
    bool use_maximum,
    bool use_minimum) {
  if (radius <= 0 || source.size() != width * height) {
    return source;
  }
  QByteArray horizontal(source.size(), '\0');
  QByteArray output(source.size(), '\0');
  const auto sample = [](const QByteArray& data, int index) {
    return static_cast<int>(static_cast<unsigned char>(data.at(index)));
  };
  for (int y = 0; y < height; ++y) {
    for (int x = 0; x < width; ++x) {
      int value = use_minimum ? 255 : 0;
      int sum = 0;
      int count = 0;
      for (int offset = -radius; offset <= radius; ++offset) {
        const auto current = sample(source, y * width + qBound(0, x + offset, width - 1));
        if (use_maximum) {
          value = qMax(value, current);
        } else if (use_minimum) {
          value = qMin(value, current);
        } else {
          sum += current;
          ++count;
        }
      }
      horizontal[y * width + x] = static_cast<char>(
          use_maximum || use_minimum ? value : qRound(static_cast<double>(sum) / qMax(1, count)));
    }
  }
  for (int y = 0; y < height; ++y) {
    for (int x = 0; x < width; ++x) {
      int value = use_minimum ? 255 : 0;
      int sum = 0;
      int count = 0;
      for (int offset = -radius; offset <= radius; ++offset) {
        const auto current = sample(horizontal, qBound(0, y + offset, height - 1) * width + x);
        if (use_maximum) {
          value = qMax(value, current);
        } else if (use_minimum) {
          value = qMin(value, current);
        } else {
          sum += current;
          ++count;
        }
      }
      output[y * width + x] = static_cast<char>(
          use_maximum || use_minimum ? value : qRound(static_cast<double>(sum) / qMax(1, count)));
    }
  }
  return output;
}

QImage apply_subject_cutout(
    QImage source_image,
    const QByteArray& stored_mask,
    int mask_width,
    int mask_height,
    double feather,
    double expand,
    double edge_contrast,
    const QString& preview_mode) {
  if (source_image.isNull() || mask_width <= 0 || mask_height <= 0 ||
      stored_mask.size() != mask_width * mask_height) {
    return source_image;
  }
  auto refined_mask = stored_mask;
  const auto expand_radius = qBound(0, qRound(qAbs(expand)), 16);
  if (expand_radius > 0) {
    refined_mask = box_filter_mask(
        refined_mask, mask_width, mask_height, expand_radius, expand > 0.0, expand < 0.0);
  }
  const auto feather_radius = qBound(0, qRound(feather), 16);
  if (feather_radius > 0) {
    refined_mask = box_filter_mask(
        refined_mask, mask_width, mask_height, feather_radius, false, false);
  }
  if (!qFuzzyIsNull(edge_contrast)) {
    const auto slope = qBound(0.1, 1.0 + edge_contrast / 50.0, 3.0);
    for (qsizetype index = 0; index < refined_mask.size(); ++index) {
      const auto value = static_cast<double>(
                             static_cast<unsigned char>(refined_mask.at(index))) /
                         255.0;
      const auto adjusted = qBound(0.0, 0.5 + (value - 0.5) * slope, 1.0);
      refined_mask[index] = static_cast<char>(qRound(adjusted * 255.0));
    }
  }
  QImage mask_image(
      reinterpret_cast<const uchar*>(refined_mask.constData()),
      mask_width,
      mask_height,
      mask_width,
      QImage::Format_Grayscale8);
  mask_image = mask_image.copy().scaled(
      source_image.size(), Qt::IgnoreAspectRatio, Qt::SmoothTransformation);
  if (preview_mode == QStringLiteral("matte")) {
    auto matte = mask_image.convertToFormat(QImage::Format_ARGB32);
    matte.setColorSpace(source_image.colorSpace());
    return matte;
  }
  source_image = source_image.convertToFormat(QImage::Format_ARGB32);
  for (int y = 0; y < source_image.height(); ++y) {
    auto* pixels = reinterpret_cast<QRgb*>(source_image.scanLine(y));
    const auto* mask_line = mask_image.constScanLine(y);
    for (int x = 0; x < source_image.width(); ++x) {
      const auto matte = static_cast<int>(mask_line[x]);
      const auto source_alpha = qAlpha(pixels[x]);
      const auto alpha = qRound(static_cast<double>(source_alpha * matte) / 255.0);
      if (preview_mode == QStringLiteral("edges") && matte > 16 && matte < 239) {
        pixels[x] = qRgba(255, 53, 164, 255);
      } else {
        pixels[x] = qRgba(qRed(pixels[x]), qGreen(pixels[x]), qBlue(pixels[x]), alpha);
      }
    }
  }
  return source_image;
}

QString normalized_color_value(const QString& value, const QString& fallback) {
  const QColor color(value.trimmed());
  return color.isValid() ? color.name(QColor::HexRgb) : fallback;
}

QString normalized_background_kind(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("transparent")) {
    return normalized;
  }
  if (normalized == QStringLiteral("linear-horizontal") ||
      normalized == QStringLiteral("linear-vertical")) {
    return normalized;
  }
  return QStringLiteral("solid");
}

QString normalized_text_horizontal_alignment(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("left") || normalized == QStringLiteral("right")) {
    return normalized;
  }
  return QStringLiteral("center");
}

QString normalized_text_vertical_alignment(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("top") || normalized == QStringLiteral("bottom")) {
    return normalized;
  }
  return QStringLiteral("middle");
}

QString normalized_text_font_family(const QString& value) {
  const auto requested = value.simplified();
  const auto normalized = requested.toLower();
  if (normalized == QStringLiteral("serif") || normalized == QStringLiteral("mono") ||
      normalized == QStringLiteral("system") || normalized == QStringLiteral("display")) {
    return normalized;
  }
  return requested.isEmpty() ? QStringLiteral("display") : requested;
}

QString font_family_for_text_family(const QString& value) {
  const auto normalized = normalized_text_font_family(value);
  if (normalized == QStringLiteral("serif")) {
    return QStringLiteral("Georgia");
  }
  if (normalized == QStringLiteral("mono")) {
    return QStringLiteral("Menlo");
  }
  if (normalized == QStringLiteral("system")) {
    return QStringLiteral("Helvetica Neue");
  }
  if (normalized != QStringLiteral("display")) {
    return value.simplified();
  }
  return QString::fromLatin1(kTextFontFamily);
}

bool text_font_family_available(const QString& value, const QStringList& installed_fonts) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("display") || normalized == QStringLiteral("serif") ||
      normalized == QStringLiteral("mono") || normalized == QStringLiteral("system")) {
    return true;
  }
  for (const auto& family : installed_fonts) {
    if (family.compare(value.simplified(), Qt::CaseInsensitive) == 0) {
      return true;
    }
  }
  return false;
}

QString normalized_text_weight(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("normal") || normalized == QStringLiteral("bold") ||
      normalized == QStringLiteral("black")) {
    return normalized;
  }
  return QStringLiteral("demibold");
}

QFont::Weight font_weight_for_text_weight(const QString& value) {
  const auto normalized = normalized_text_weight(value);
  if (normalized == QStringLiteral("normal")) {
    return QFont::Normal;
  }
  if (normalized == QStringLiteral("bold")) {
    return QFont::Bold;
  }
  if (normalized == QStringLiteral("black")) {
    return QFont::Black;
  }
  return QFont::DemiBold;
}

struct CarouselRichTextStyle final {
  bool emphasis = false;
  QString link;
  QString color;
  QString weight;
  bool has_italic = false;
  bool italic = false;
  bool superscript = false;

  bool operator==(const CarouselRichTextStyle& other) const = default;
};

bool rich_text_style_is_empty(const CarouselRichTextStyle& style) {
  return !style.emphasis && style.link.isEmpty() && style.color.isEmpty() &&
         style.weight.isEmpty() && !style.has_italic && !style.superscript;
}

QVector<CarouselRichTextStyle> rich_text_styles_for_text(
    const QString& text,
    const QJsonArray& spans) {
  QVector<CarouselRichTextStyle> styles(text.size());
  for (const auto& value : spans) {
    if (!value.isObject()) {
      continue;
    }
    const auto object = value.toObject();
    const auto text_size = static_cast<int>(text.size());
    const auto start = qBound(0, object.value(QStringLiteral("start")).toInt(), text_size);
    const auto length = qBound(
        0, object.value(QStringLiteral("length")).toInt(), text_size - start);
    if (length <= 0) {
      continue;
    }
    for (int index = start; index < start + length; ++index) {
      auto& style = styles[index];
      if (object.contains(QStringLiteral("emphasis"))) {
        style.emphasis = object.value(QStringLiteral("emphasis")).toBool();
      }
      if (object.contains(QStringLiteral("link"))) {
        style.link = object.value(QStringLiteral("link")).toString().trimmed().left(2048);
      }
      if (object.contains(QStringLiteral("color"))) {
        const QColor color(object.value(QStringLiteral("color")).toString());
        style.color = color.isValid() ? color.name(QColor::HexRgb) : QString{};
      }
      if (object.contains(QStringLiteral("weight"))) {
        const auto weight = object.value(QStringLiteral("weight")).toString().trimmed();
        style.weight = weight.isEmpty() ? QString{} : normalized_text_weight(weight);
      }
      if (object.contains(QStringLiteral("italic"))) {
        style.has_italic = true;
        style.italic = object.value(QStringLiteral("italic")).toBool();
      }
      if (object.contains(QStringLiteral("superscript"))) {
        style.superscript = object.value(QStringLiteral("superscript")).toBool();
      }
    }
  }
  return styles;
}

QJsonArray compact_rich_text_spans(const QVector<CarouselRichTextStyle>& styles) {
  QJsonArray spans;
  int start = 0;
  while (start < styles.size()) {
    const auto style = styles.at(start);
    int end = start + 1;
    while (end < styles.size() && styles.at(end) == style) {
      ++end;
    }
    if (!rich_text_style_is_empty(style)) {
      QJsonObject span{
          {QStringLiteral("start"), start},
          {QStringLiteral("length"), end - start},
      };
      if (style.emphasis) {
        span.insert(QStringLiteral("emphasis"), true);
      }
      if (!style.link.isEmpty()) {
        span.insert(QStringLiteral("link"), style.link);
      }
      if (!style.color.isEmpty()) {
        span.insert(QStringLiteral("color"), style.color);
      }
      if (!style.weight.isEmpty()) {
        span.insert(QStringLiteral("weight"), style.weight);
      }
      if (style.has_italic) {
        span.insert(QStringLiteral("italic"), style.italic);
      }
      if (style.superscript) {
        span.insert(QStringLiteral("superscript"), true);
      }
      spans.push_back(span);
    }
    start = end;
  }
  return spans;
}

QJsonArray normalized_rich_text_spans(const QString& text, const QJsonArray& spans) {
  return compact_rich_text_spans(rich_text_styles_for_text(text, spans));
}

QJsonArray remap_rich_text_spans(
    const QString& old_text,
    const QString& new_text,
    const QJsonArray& spans) {
  if (spans.isEmpty() || old_text == new_text) {
    return normalized_rich_text_spans(new_text, spans);
  }
  const auto old_styles = rich_text_styles_for_text(old_text, spans);
  QVector<CarouselRichTextStyle> new_styles(new_text.size());
  int prefix = 0;
  while (prefix < old_text.size() && prefix < new_text.size() &&
         old_text.at(prefix) == new_text.at(prefix)) {
    new_styles[prefix] = old_styles.at(prefix);
    ++prefix;
  }
  int suffix = 0;
  while (suffix < old_text.size() - prefix && suffix < new_text.size() - prefix &&
         old_text.at(old_text.size() - suffix - 1) ==
             new_text.at(new_text.size() - suffix - 1)) {
    new_styles[new_text.size() - suffix - 1] =
        old_styles.at(old_text.size() - suffix - 1);
    ++suffix;
  }
  const auto inserted_end = new_text.size() - suffix;
  if (prefix > 0 && prefix < inserted_end && prefix < old_styles.size() &&
      old_styles.at(prefix - 1) == old_styles.at(prefix)) {
    const auto inherited = old_styles.at(prefix);
    if (!rich_text_style_is_empty(inherited)) {
      for (int index = prefix; index < inserted_end; ++index) {
        new_styles[index] = inherited;
      }
    }
  }
  return compact_rich_text_spans(new_styles);
}

QString effective_rich_text_weight(
    const CarouselRichTextStyle& style,
    const CarouselDocumentController::CanvasItem& item) {
  if (!style.weight.isEmpty()) {
    return style.weight;
  }
  if (style.emphasis && font_weight_for_text_weight(item.text_weight) < QFont::DemiBold) {
    return QStringLiteral("demibold");
  }
  return item.text_weight;
}

bool effective_rich_text_italic(
    const CarouselRichTextStyle& style,
    const CarouselDocumentController::CanvasItem& item) {
  return style.has_italic ? style.italic : style.emphasis || item.text_italic;
}

QList<QTextLayout::FormatRange> rich_text_format_ranges(
    const CarouselDocumentController::CanvasItem& item,
    const QString& display_text,
    double font_scale) {
  const auto display_spans = remap_rich_text_spans(item.text, display_text, item.text_spans);
  const auto styles = rich_text_styles_for_text(display_text, display_spans);
  QList<QTextLayout::FormatRange> ranges;
  int start = 0;
  while (start < styles.size()) {
    const auto style = styles.at(start);
    int end = start + 1;
    while (end < styles.size() && styles.at(end) == style) {
      ++end;
    }
    if (!rich_text_style_is_empty(style)) {
      QTextCharFormat format;
      format.setFontWeight(font_weight_for_text_weight(effective_rich_text_weight(style, item)));
      format.setFontItalic(effective_rich_text_italic(style, item));
      format.setFontUnderline(item.text_underline || !style.link.isEmpty());
      format.setFontStrikeOut(item.text_strikethrough);
      if (!style.color.isEmpty()) {
        format.setForeground(QColor(style.color));
      }
      if (style.superscript) {
        format.setVerticalAlignment(QTextCharFormat::AlignSuperScript);
        format.setFontPointSize(
            qMax(kMinTextPointSize, item.text_point_size) * font_scale * 0.72);
      }
      QTextLayout::FormatRange range;
      range.start = start;
      range.length = end - start;
      range.format = format;
      ranges.push_back(range);
    }
    start = end;
  }
  return ranges;
}

int text_alignment_flags(const QString& horizontal_alignment, const QString& vertical_alignment) {
  int flags = Qt::TextWordWrap;
  const auto horizontal = normalized_text_horizontal_alignment(horizontal_alignment);
  if (horizontal == QStringLiteral("left")) {
    flags |= Qt::AlignLeft;
  } else if (horizontal == QStringLiteral("right")) {
    flags |= Qt::AlignRight;
  } else {
    flags |= Qt::AlignHCenter;
  }

  const auto vertical = normalized_text_vertical_alignment(vertical_alignment);
  if (vertical == QStringLiteral("top")) {
    flags |= Qt::AlignTop;
  } else if (vertical == QStringLiteral("bottom")) {
    flags |= Qt::AlignBottom;
  } else {
    flags |= Qt::AlignVCenter;
  }
  return flags;
}

struct CarouselTextLayoutLine final {
  QString text;
  int text_start = 0;
  int text_length = 0;
  QVector<CarouselRichTextStyle> segment_styles;
  QVector<QString> segment_texts;
  QVector<double> segment_x;
  QVector<double> segment_width;
  double x = 0.0;
  double y = 0.0;
  double height = 0.0;
};

struct CarouselTextLayout final {
  QVector<CarouselTextLayoutLine> visible_lines;
  double full_height = 0.0;
  double visible_height = 0.0;
  bool maximum_line_overflow = false;
};

CarouselTextLayout layout_carousel_text(
    const CarouselDocumentController::CanvasItem& item,
    double frame_width,
    double font_scale = 1.0) {
  QFont font(font_family_for_text_family(item.text_font_family));
  font.setPointSizeF(qMax(kMinTextPointSize, item.text_point_size) * font_scale);
  font.setWeight(font_weight_for_text_weight(item.text_weight));
  font.setItalic(item.text_italic);
  font.setUnderline(item.text_underline);
  font.setStrikeOut(item.text_strikethrough);
  font.setLetterSpacing(
      QFont::AbsoluteSpacing,
      clamp_text_letter_spacing(item.text_letter_spacing) * font_scale);
  const QFontMetricsF metrics(font);
  const auto line_height = qMax(metrics.height(), metrics.height() * qBound(0.7, item.text_line_height, 3.0));
  const auto paragraph_spacing = qBound(0.0, item.text_paragraph_spacing, 320.0) * font_scale;
  const auto total_inset =
      (qMax(0.0, item.text_padding) + qMax(0.0, item.text_inset)) * font_scale;
  const auto available_width = qMax(kMinItemSize * font_scale, frame_width - total_inset * 2.0);
  auto display_text = transformed_text(item.text, item.text_case);
  if (display_text.isEmpty()) {
    display_text = QStringLiteral(" ");
  }

  QTextLayout layout(display_text, font);
  layout.setFormats(rich_text_format_ranges(item, display_text, font_scale));
  QTextOption option;
  option.setWrapMode(QTextOption::WrapAtWordBoundaryOrAnywhere);
  const auto horizontal_alignment = normalized_text_horizontal_alignment(
      item.text_horizontal_alignment);
  option.setAlignment(horizontal_alignment == QStringLiteral("left")
                          ? Qt::AlignLeft
                          : horizontal_alignment == QStringLiteral("right")
                                ? Qt::AlignRight
                                : Qt::AlignHCenter);
  layout.setTextOption(option);
  const auto display_styles = rich_text_styles_for_text(
      display_text, remap_rich_text_spans(item.text, display_text, item.text_spans));
  layout.beginLayout();
  CarouselTextLayout result;
  int line_index = 0;
  double y = 0.0;
  bool first_line_of_paragraph = true;
  while (true) {
    auto line = layout.createLine();
    if (!line.isValid()) {
      break;
    }
    const auto hanging_indent = first_line_of_paragraph
                                    ? 0.0
                                    : qBound(0.0, item.text_hanging_indent * font_scale,
                                             available_width * 0.8);
    line.setLineWidth(qMax(kMinItemSize * font_scale, available_width - hanging_indent));
    const auto line_start = line.textStart();
    auto visible_length = line.textLength();
    auto line_text = display_text.mid(line_start, visible_length);
    const bool paragraph_end = line_text.contains(QLatin1Char('\n')) || line_text.contains(QLatin1Char('\r'));
    while (visible_length > 0 &&
           (display_text.at(line_start + visible_length - 1) == QLatin1Char('\n') ||
            display_text.at(line_start + visible_length - 1) == QLatin1Char('\r'))) {
      --visible_length;
    }
    line_text = display_text.mid(line_start, visible_length);
    const auto measured_line_height = qMax(line_height, line.height());
    if (item.text_maximum_line_count <= 0 || line_index < item.text_maximum_line_count) {
      CarouselTextLayoutLine result_line;
      result_line.text = line_text;
      result_line.text_start = line_start;
      result_line.text_length = visible_length;
      result_line.x = hanging_indent;
      result_line.y = y;
      result_line.height = measured_line_height;
      int segment_start = line_start;
      const auto line_end = line_start + visible_length;
      while (segment_start < line_end) {
        const auto style = display_styles.at(segment_start);
        int segment_end = segment_start + 1;
        while (segment_end < line_end && display_styles.at(segment_end) == style) {
          ++segment_end;
        }
        const auto start_x = line.cursorToX(segment_start);
        const auto end_x = line.cursorToX(segment_end);
        result_line.segment_styles.push_back(style);
        result_line.segment_texts.push_back(
            display_text.mid(segment_start, segment_end - segment_start));
        result_line.segment_x.push_back(hanging_indent + start_x);
        result_line.segment_width.push_back(qMax(0.0, end_x - start_x));
        segment_start = segment_end;
      }
      result.visible_lines.push_back(std::move(result_line));
      result.visible_height = y + measured_line_height;
    } else {
      result.maximum_line_overflow = true;
    }
    y += measured_line_height;
    if (paragraph_end) {
      y += paragraph_spacing;
    }
    first_line_of_paragraph = paragraph_end;
    ++line_index;
  }
  layout.endLayout();
  result.full_height = qMax(line_height, y) + total_inset * 2.0;
  return result;
}

QString normalized_blend_mode(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("multiply") || normalized == QStringLiteral("screen") ||
      normalized == QStringLiteral("overlay")) {
    return normalized;
  }
  return QStringLiteral("normal");
}

QPainter::CompositionMode composition_mode_for_blend_mode(const QString& value) {
  const auto normalized = normalized_blend_mode(value);
  if (normalized == QStringLiteral("multiply")) {
    return QPainter::CompositionMode_Multiply;
  }
  if (normalized == QStringLiteral("screen")) {
    return QPainter::CompositionMode_Screen;
  }
  if (normalized == QStringLiteral("overlay")) {
    return QPainter::CompositionMode_Overlay;
  }
  return QPainter::CompositionMode_SourceOver;
}

QString normalized_path(const QString& path) {
  if (path.trimmed().isEmpty()) {
    return {};
  }
  const QUrl url(path.trimmed());
  const auto local_path = url.isLocalFile() ? url.toLocalFile() : path;
  return QDir::cleanPath(QFileInfo(local_path).absoluteFilePath());
}

