QVariantMap CarouselDocumentController::readingOrderState() const {
  const auto entries = readingOrderEntriesForSlide(current_index_, false);
  int meaningful_count = 0;
  for (const auto& value : entries) {
    if (value.toMap().value(QStringLiteral("meaningful")).toBool()) {
      ++meaningful_count;
    }
  }
  const auto* slide = slideAt(current_index_);
  return QVariantMap{
      {QStringLiteral("boardIndex"), current_index_},
      {QStringLiteral("boardNumber"), current_index_ + 1},
      {QStringLiteral("boardName"), slide != nullptr ? slide->board_name : QString{}},
      {QStringLiteral("entries"), entries},
      {QStringLiteral("entryCount"), entries.size()},
      {QStringLiteral("meaningfulEntryCount"), meaningful_count},
      {QStringLiteral("hasExplicitOrder"),
       slide != nullptr && !slide->accessibility_reading_order.isEmpty()},
  };
}

