QVariantList CarouselDocumentController::missingFontEntries() const {
  QVariantList entries;
  const auto installed_fonts = QFontDatabase::families();
  for (const auto& item : items_) {
    if (item.kind != ItemKind::Text ||
        text_font_family_available(item.text_font_family, installed_fonts)) {
      continue;
    }
    entries.push_back(QVariantMap{
        {QStringLiteral("boardIndex"), slideIndexForItem(item)},
        {QStringLiteral("itemId"), item.id},
        {QStringLiteral("layerLabel"), summary_label(item)},
        {QStringLiteral("fontFamily"), item.text_font_family},
        {QStringLiteral("resolvedFontFamily"), font_family_for_text_family(item.text_font_family)},
        {QStringLiteral("originalFontFamily"), item.original_font_family.isEmpty()
                                                   ? item.text_font_family
                                                   : item.original_font_family},
        {QStringLiteral("text"), item.text},
        {QStringLiteral("pointSize"), item.text_point_size},
        {QStringLiteral("frameWidth"), item.bounds.width()},
        {QStringLiteral("frameHeight"), item.bounds.height()},
    });
  }
  return entries;
}

