QVariantList CarouselDocumentController::copyProofIssues() const {
  QVariantList issues;
  const auto& dictionary = system_spell_dictionary();
  QSet<QString> custom_words;
  for (const auto& word : custom_dictionary_words_) {
    custom_words.insert(word.toLower());
  }
  const QHash<QString, QString> common_corrections{
      {QStringLiteral("teh"), QStringLiteral("the")},
      {QStringLiteral("recieve"), QStringLiteral("receive")},
      {QStringLiteral("seperate"), QStringLiteral("separate")},
      {QStringLiteral("definately"), QStringLiteral("definitely")},
      {QStringLiteral("adress"), QStringLiteral("address")},
      {QStringLiteral("occured"), QStringLiteral("occurred")},
      {QStringLiteral("untill"), QStringLiteral("until")},
      {QStringLiteral("wich"), QStringLiteral("which")},
      {QStringLiteral("alot"), QStringLiteral("a lot")},
      {QStringLiteral("tobe"), QStringLiteral("to be")},
  };
  const QHash<QString, QString> us_variants{
      {QStringLiteral("colour"), QStringLiteral("color")},
      {QStringLiteral("favourite"), QStringLiteral("favorite")},
      {QStringLiteral("centre"), QStringLiteral("center")},
      {QStringLiteral("organise"), QStringLiteral("organize")},
  };
  const QHash<QString, QString> gb_variants{
      {QStringLiteral("color"), QStringLiteral("colour")},
      {QStringLiteral("favorite"), QStringLiteral("favourite")},
      {QStringLiteral("center"), QStringLiteral("centre")},
      {QStringLiteral("organize"), QStringLiteral("organise")},
  };
  auto add_issue = [this, &issues](
                       const CanvasItem& item,
                       const QString& code,
                       qsizetype start,
                       qsizetype length,
                       const QString& word,
                       const QString& message,
                       const QStringList& suggestions,
                       bool can_add_to_dictionary) {
    const auto issue_id = QStringLiteral("%1|%2|%3|%4")
                              .arg(item.id, code)
                              .arg(start)
                              .arg(word.toLower());
    if (ignored_copy_proof_issue_ids_.contains(issue_id)) {
      return;
    }
    issues.push_back(QVariantMap{
        {QStringLiteral("issueId"), issue_id},
        {QStringLiteral("code"), code},
        {QStringLiteral("boardIndex"), slideIndexForItem(item)},
        {QStringLiteral("itemId"), item.id},
        {QStringLiteral("layerLabel"), summary_label(item)},
        {QStringLiteral("start"), static_cast<qlonglong>(start)},
        {QStringLiteral("length"), static_cast<qlonglong>(length)},
        {QStringLiteral("word"), word},
        {QStringLiteral("message"), message},
        {QStringLiteral("suggestions"), suggestions},
        {QStringLiteral("canAddToDictionary"), can_add_to_dictionary},
    });
  };

  const QRegularExpression word_pattern(QStringLiteral("[A-Za-z][A-Za-z']*"));
  const QRegularExpression double_space_pattern(QStringLiteral(" {2,}"));
  const QRegularExpression punctuation_space_pattern(QStringLiteral("\\s+[,.;:!?]"));
  for (const auto& item : items_) {
    if (item.kind != ItemKind::Text || item.hidden || item.text.trimmed().isEmpty()) {
      continue;
    }
    QString previous_word;
    qsizetype previous_start = -1;
    auto word_matches = word_pattern.globalMatch(item.text);
    while (word_matches.hasNext()) {
      const auto match = word_matches.next();
      const auto authored_word = match.captured();
      auto normalized_word = authored_word.toLower();
      if (normalized_word.endsWith(QStringLiteral("'s"))) {
        normalized_word.chop(2);
      }
      if (!previous_word.isEmpty() && previous_word == normalized_word && previous_start >= 0) {
        add_issue(
            item,
            QStringLiteral("repeated-word"),
            match.capturedStart(),
            match.capturedLength(),
            authored_word,
            QStringLiteral("Repeated word “%1”.").arg(authored_word),
            {},
            false);
      }
      previous_word = normalized_word;
      previous_start = match.capturedStart();

      if (authored_word.size() > 1 && authored_word == authored_word.toUpper()) {
        continue;
      }
      if (custom_words.contains(normalized_word)) {
        continue;
      }
      const auto& variants = copy_proof_language_ == QStringLiteral("en-GB") ? gb_variants : us_variants;
      if (variants.contains(normalized_word)) {
        add_issue(
            item,
            QStringLiteral("language-variant"),
            match.capturedStart(),
            match.capturedLength(),
            authored_word,
            QStringLiteral("“%1” does not match %2 spelling.").arg(authored_word, copy_proof_language_),
            {variants.value(normalized_word)},
            false);
        continue;
      }
      if (common_corrections.contains(normalized_word)) {
        add_issue(
            item,
            QStringLiteral("spelling"),
            match.capturedStart(),
            match.capturedLength(),
            authored_word,
            QStringLiteral("“%1” is not in the %2 dictionary.").arg(authored_word, copy_proof_language_),
            {common_corrections.value(normalized_word)},
            true);
        continue;
      }
      if (normalized_word.size() <= 1 || dictionary.contains(normalized_word)) {
        continue;
      }
      const auto suggestion = common_corrections.value(normalized_word);
      add_issue(
          item,
          QStringLiteral("spelling"),
          match.capturedStart(),
          match.capturedLength(),
          authored_word,
          QStringLiteral("“%1” is not in the %2 dictionary.").arg(authored_word, copy_proof_language_),
          suggestion.isEmpty() ? QStringList{} : QStringList{suggestion},
          true);
    }

    auto double_spaces = double_space_pattern.globalMatch(item.text);
    while (double_spaces.hasNext()) {
      const auto match = double_spaces.next();
      add_issue(
          item,
          QStringLiteral("double-space"),
          match.capturedStart(),
          match.capturedLength(),
          match.captured(),
          QStringLiteral("Multiple spaces interrupt the copy rhythm."),
          {QStringLiteral("single space")},
          false);
    }
    auto punctuation_spaces = punctuation_space_pattern.globalMatch(item.text);
    while (punctuation_spaces.hasNext()) {
      const auto match = punctuation_spaces.next();
      add_issue(
          item,
          QStringLiteral("punctuation-spacing"),
          match.capturedStart(),
          match.capturedLength(),
          match.captured(),
          QStringLiteral("Remove the space before punctuation."),
          {},
          false);
    }
  }
  return issues;
}

