QVariantMap CarouselDocumentController::exportSummary() const {
  const auto size = configuredExportPixelSize();
  const auto preview_size = exportPixelSize();
  const auto board_indexes = exportBoardIndexes();
  QSet<QString> file_types;
  int image_count = 0;
  int video_count = 0;
  QStringList ordered_board_numbers;
  for (const auto index : board_indexes) {
    ordered_board_numbers.push_back(QString::number(index + 1));
    const auto* slide = slideAt(index);
    if (slide != nullptr && slide->template_kind == SlideTemplate::Single &&
        slide->primary.type == MediaType::Video) {
      file_types.insert(QStringLiteral("MP4"));
      ++video_count;
    } else {
      file_types.insert(export_image_format_ == QStringLiteral("jpeg")
                            ? QStringLiteral("JPEG")
                            : export_image_format_.toUpper());
      ++image_count;
    }
  }
  if (export_proof_sheet_enabled_) {
    file_types.insert(QStringLiteral("PDF"));
  }
  QStringList ordered_file_types = file_types.values();
  std::sort(ordered_file_types.begin(), ordered_file_types.end());
  const auto estimated_bytes = static_cast<qulonglong>(image_count) *
                               static_cast<qulonglong>(size.width()) *
                               static_cast<qulonglong>(size.height()) * 14ULL / 10ULL;
  const auto estimated_megabytes = static_cast<double>(estimated_bytes) / (1024.0 * 1024.0);
  auto estimated_output = QStringLiteral("~%1 MB").arg(estimated_megabytes, 0, 'f', 1);
  if (video_count > 0) {
    estimated_output += QStringLiteral(" plus %1 video source%2")
                            .arg(video_count)
                            .arg(video_count == 1 ? QString{} : QStringLiteral("s"));
  }
  int collision_count = 0;
  for (const auto& value : exportOutputPreview()) {
    if (value.toMap().value(QStringLiteral("collision")).toBool()) {
      ++collision_count;
    }
  }
  int blocking_issue_count = 0;
  int warning_count = 0;
  for (const auto& value : exportPreflightIssues()) {
    if (value.toMap().value(QStringLiteral("blocking")).toBool()) {
      ++blocking_issue_count;
    } else {
      ++warning_count;
    }
  }
  const auto preset_state = exportPresetState();
  return {
      {QStringLiteral("boardCount"), board_indexes.size()},
      {QStringLiteral("documentBoardCount"), slideCount()},
      {QStringLiteral("boardOrder"), ordered_board_numbers.join(QStringLiteral(", "))},
      {QStringLiteral("boardScope"), export_board_scope_},
      {QStringLiteral("ratio"), QString(document_format_).replace(QLatin1Char('x'), QLatin1Char(':'))},
      {QStringLiteral("pixelWidth"), size.width()},
      {QStringLiteral("pixelHeight"), size.height()},
      {QStringLiteral("pixelSize"), QStringLiteral("%1 × %2").arg(size.width()).arg(size.height())},
      {QStringLiteral("previewPixelSize"),
       QStringLiteral("%1 × %2").arg(preview_size.width()).arg(preview_size.height())},
      {QStringLiteral("fileTypes"), ordered_file_types.join(QStringLiteral(", "))},
      {QStringLiteral("colorSpace"), export_color_space_},
      {QStringLiteral("destination"), export_directory_},
      {QStringLiteral("estimatedBytes"), QVariant::fromValue(estimated_bytes)},
      {QStringLiteral("estimatedOutput"), estimated_output},
      {QStringLiteral("blockingIssueCount"), blocking_issue_count},
      {QStringLiteral("warningCount"), warning_count},
      {QStringLiteral("filenamePattern"), export_filename_pattern_},
      {QStringLiteral("exportVersion"), export_version_},
      {QStringLiteral("collisionPolicy"), export_collision_policy_},
      {QStringLiteral("collisionCount"), collision_count},
      {QStringLiteral("imageFormat"), export_image_format_},
      {QStringLiteral("imageQuality"), export_image_quality_},
      {QStringLiteral("preserveTransparency"), export_preserve_transparency_},
      {QStringLiteral("proofSheetEnabled"), export_proof_sheet_enabled_},
      {QStringLiteral("proofIncludeNotes"), export_proof_include_notes_},
      {QStringLiteral("proofPageSize"), QStringLiteral("A4 landscape")},
      {QStringLiteral("proofBoardsPerPage"), 4},
      {QStringLiteral("proofColorManagement"),
       QStringLiteral("%1 to sRGB proof space").arg(export_color_space_)},
      {QStringLiteral("presetId"), active_export_preset_id_},
      {QStringLiteral("presetVersion"), active_export_preset_version_},
      {QStringLiteral("presetName"), preset_state.value(QStringLiteral("activePresetName"))},
      {QStringLiteral("presetOverrideCount"),
       preset_state.value(QStringLiteral("overrideCount"))},
      {QStringLiteral("formatWarning"),
       export_image_format_ == QStringLiteral("jpeg")
           ? QStringLiteral("JPEG is lossy and does not support transparency; image boards are flattened.")
           : export_image_format_ == QStringLiteral("webp")
                 ? QStringLiteral("WebP supports transparency but is not accepted by every social platform.")
                 : QStringLiteral("PNG is lossless and broadly compatible.")},
  };
}

QVariantList CarouselDocumentController::exportPresets() const {
  const auto reviewed = QStringLiteral("2026-07-21");
  const auto tiktok_source = QStringLiteral(
      "https://ads.tiktok.com/help/article/specifications-for-carousel-ads?lang=en");
  const auto youtube_source = QStringLiteral(
      "https://support.google.com/youtube/answer/7124474?co=GENIE.Platform%3DDesktop&hl=en-0");
  const auto make_settings = [](
                                 const QString& size_mode,
                                 int width,
                                 int height,
                                 const QString& image_format,
                                 int image_quality,
                                 bool preserve_transparency,
                                 const QString& color_space,
                                 const QString& filename_pattern,
                                 bool manifest_enabled,
                                 bool proof_enabled,
                                 bool proof_include_notes) {
    return QVariantMap{
        {QStringLiteral("boardScope"), QStringLiteral("all")},
        {QStringLiteral("sizeMode"), size_mode},
        {QStringLiteral("customWidth"), width},
        {QStringLiteral("customHeight"), height},
        {QStringLiteral("aspectLocked"), true},
        {QStringLiteral("imageFormat"), image_format},
        {QStringLiteral("imageQuality"), image_quality},
        {QStringLiteral("preserveTransparency"), preserve_transparency},
        {QStringLiteral("colorSpace"), color_space},
        {QStringLiteral("filenamePattern"), filename_pattern},
        {QStringLiteral("collisionPolicy"), QStringLiteral("rename")},
        {QStringLiteral("manifestEnabled"), manifest_enabled},
        {QStringLiteral("proofSheetEnabled"), proof_enabled},
        {QStringLiteral("proofIncludeNotes"), proof_include_notes},
    };
  };
  const auto make_preset = [this](
                                const QString& preset_id,
                                const QString& name,
                                const QString& category,
                                const QString& required_format,
                                const QVariantMap& settings,
                                bool time_sensitive,
                                const QString& last_reviewed,
                                const QString& review_due,
                                const QString& source_url,
                                const QString& source_updated,
                                const QString& guidance,
                                const QString& app_defaults) {
    const bool compatible = required_format == QStringLiteral("any") ||
                            required_format == document_format_;
    const auto due_date = QDate::fromString(review_due, Qt::ISODate);
    const bool stale = time_sensitive && due_date.isValid() &&
                       QDate::currentDate() > due_date;
    return QVariantMap{
        {QStringLiteral("presetId"), preset_id},
        {QStringLiteral("presetVersion"), 1},
        {QStringLiteral("name"), name},
        {QStringLiteral("category"), category},
        {QStringLiteral("requiredDocumentFormat"), required_format},
        {QStringLiteral("requiredRatio"),
         required_format == QStringLiteral("any")
             ? QStringLiteral("Current document")
             : QString(required_format).replace(QLatin1Char('x'), QLatin1Char(':'))},
        {QStringLiteral("compatible"), compatible},
        {QStringLiteral("compatibilityMessage"),
         compatible
             ? QStringLiteral("Compatible with this document")
             : QStringLiteral("Requires a %1 document; the canvas will not be stretched.")
                   .arg(QString(required_format).replace(QLatin1Char('x'), QLatin1Char(':')))},
        {QStringLiteral("settings"), settings},
        {QStringLiteral("timeSensitive"), time_sensitive},
        {QStringLiteral("guidanceLastReviewed"), last_reviewed},
        {QStringLiteral("guidanceReviewDue"), review_due},
        {QStringLiteral("guidanceStale"), stale},
        {QStringLiteral("guidanceSourceUrl"), source_url},
        {QStringLiteral("guidanceSourceUpdated"), source_updated},
        {QStringLiteral("guidanceSummary"), guidance},
        {QStringLiteral("appChosenDefaults"), app_defaults},
    };
  };

  const auto base_width = exportPixelSize().width();
  const auto base_height = exportPixelSize().height();
  return {
      make_preset(
          QStringLiteral("tiktok-carousel-vertical"),
          QStringLiteral("TikTok Carousel · Vertical"),
          QStringLiteral("Platform delivery"),
          QStringLiteral("9x16"),
          make_settings(
              QStringLiteral("custom"), 720, 1280, QStringLiteral("jpeg"), 80, false,
              QStringLiteral("sRGB"), QStringLiteral("tiktok-{board_number}"), true,
              false, true),
          true, reviewed, QStringLiteral("2026-10-21"), tiktok_source,
          QStringLiteral("January 2026"),
          QStringLiteral(
              "TikTok Standard Carousel guidance lists 2–35 JPG/JPEG or PNG images, "
              "vertical resolution 720 × 1280 px, and a suggested file size of 100 KB or less."),
          QStringLiteral(
              "JPEG quality 80, sRGB, collision-safe names, and a delivery manifest are "
              "Looksy defaults; final file size must be checked in the resolved output list.")),
      make_preset(
          QStringLiteral("tiktok-carousel-square"),
          QStringLiteral("TikTok Carousel · Square"),
          QStringLiteral("Platform delivery"),
          QStringLiteral("1x1"),
          make_settings(
              QStringLiteral("custom"), 640, 640, QStringLiteral("jpeg"), 80, false,
              QStringLiteral("sRGB"), QStringLiteral("tiktok-{board_number}"), true,
              false, true),
          true, reviewed, QStringLiteral("2026-10-21"), tiktok_source,
          QStringLiteral("January 2026"),
          QStringLiteral(
              "TikTok Standard Carousel guidance lists 2–35 JPG/JPEG or PNG images, "
              "square resolution 640 × 640 px, and a suggested file size of 100 KB or less."),
          QStringLiteral(
              "JPEG quality 80, sRGB, collision-safe names, and a delivery manifest are "
              "Looksy defaults; final file size must be checked in the resolved output list.")),
      make_preset(
          QStringLiteral("youtube-community-square"),
          QStringLiteral("YouTube Community · Square"),
          QStringLiteral("Platform delivery"),
          QStringLiteral("1x1"),
          make_settings(
              QStringLiteral("custom"), 1080, 1080, QStringLiteral("jpeg"), 92, false,
              QStringLiteral("sRGB"), QStringLiteral("youtube-{board_number}"), true,
              false, true),
          true, reviewed, QStringLiteral("2026-10-21"), youtube_source,
          QStringLiteral("Reviewed July 2026"),
          QStringLiteral(
              "YouTube Community guidance allows up to 10 images, up to 16 MB each, in "
              "JPG, PNG, GIF, or WebP and suggests 1:1 because that is how images appear in the feed."),
          QStringLiteral(
              "1080 × 1080 px, JPEG quality 92, sRGB, collision-safe names, and a "
              "delivery manifest are Looksy working defaults, not YouTube requirements.")),
      make_preset(
          QStringLiteral("review-package"),
          QStringLiteral("Review Package"),
          QStringLiteral("Workflow"),
          QStringLiteral("any"),
          make_settings(
              QStringLiteral("1x"), base_width, base_height, QStringLiteral("png"), 100, true,
              QStringLiteral("sRGB"), QStringLiteral("review-{board_number}"), true,
              true, true),
          false, reviewed, QString{}, QString{}, QStringLiteral("Looksy v0.1.0"),
          QStringLiteral(
              "Creates platform-neutral PNG boards plus an ordered manifest and a separate "
              "A4 review contact sheet with board notes."),
          QStringLiteral("All settings are owned and versioned by Looksy.")),
      make_preset(
          QStringLiteral("archive-master"),
          QStringLiteral("Archive Master"),
          QStringLiteral("Workflow"),
          QStringLiteral("any"),
          make_settings(
              QStringLiteral("2x"), base_width * 2, base_height * 2, QStringLiteral("png"),
              100, true, QStringLiteral("Display P3"),
              QStringLiteral("archive-{board_number}"), true, false, true),
          false, reviewed, QString{}, QString{}, QStringLiteral("Looksy v0.1.0"),
          QStringLiteral(
              "Creates 2× lossless Display P3 image masters with embedded profiles and an "
              "ordered delivery manifest."),
          QStringLiteral("All settings are owned and versioned by Looksy.")),
  };
}

QVariantMap CarouselDocumentController::exportPresetById(const QString& preset_id) const {
  const auto normalized_id = preset_id.trimmed().toLower();
  for (const auto& value : exportPresets()) {
    const auto preset = value.toMap();
    if (preset.value(QStringLiteral("presetId")).toString() == normalized_id) {
      return preset;
    }
  }
  return {};
}

QVariantMap CarouselDocumentController::currentExportPresetControlledSettings() const {
  return {
      {QStringLiteral("boardScope"), export_board_scope_},
      {QStringLiteral("sizeMode"), export_size_mode_},
      {QStringLiteral("customWidth"), export_custom_pixel_width_},
      {QStringLiteral("customHeight"), export_custom_pixel_height_},
      {QStringLiteral("aspectLocked"), export_aspect_locked_},
      {QStringLiteral("imageFormat"), export_image_format_},
      {QStringLiteral("imageQuality"), export_image_quality_},
      {QStringLiteral("preserveTransparency"), export_preserve_transparency_},
      {QStringLiteral("colorSpace"), export_color_space_},
      {QStringLiteral("filenamePattern"), export_filename_pattern_},
      {QStringLiteral("collisionPolicy"), export_collision_policy_},
      {QStringLiteral("manifestEnabled"), export_manifest_enabled_},
      {QStringLiteral("proofSheetEnabled"), export_proof_sheet_enabled_},
      {QStringLiteral("proofIncludeNotes"), export_proof_include_notes_},
  };
}

QVariantMap CarouselDocumentController::normalizedExportPresetSettings(
    const QVariantMap& settings) const {
  const auto current = currentExportPresetControlledSettings();
  const auto requested_scope = settings.value(
      QStringLiteral("boardScope"), current.value(QStringLiteral("boardScope"))).toString().toLower();
  const auto requested_mode = settings.value(
      QStringLiteral("sizeMode"), current.value(QStringLiteral("sizeMode"))).toString().toLower();
  const auto requested_format = settings.value(
      QStringLiteral("imageFormat"), current.value(QStringLiteral("imageFormat"))).toString();
  return {
      {QStringLiteral("boardScope"),
       requested_scope == QStringLiteral("current") || requested_scope == QStringLiteral("selected")
           ? requested_scope
           : QStringLiteral("all")},
      {QStringLiteral("sizeMode"),
       requested_mode == QStringLiteral("2x") || requested_mode == QStringLiteral("custom")
           ? requested_mode
           : QStringLiteral("1x")},
      {QStringLiteral("customWidth"),
       qBound(64, settings.value(QStringLiteral("customWidth"),
                                 current.value(QStringLiteral("customWidth"))).toInt(), 16384)},
      {QStringLiteral("customHeight"),
       qBound(64, settings.value(QStringLiteral("customHeight"),
                                 current.value(QStringLiteral("customHeight"))).toInt(), 16384)},
      {QStringLiteral("aspectLocked"),
       settings.value(QStringLiteral("aspectLocked"),
                      current.value(QStringLiteral("aspectLocked"))).toBool()},
      {QStringLiteral("imageFormat"), normalized_export_image_format(requested_format)},
      {QStringLiteral("imageQuality"),
       qBound(1, settings.value(QStringLiteral("imageQuality"),
                                current.value(QStringLiteral("imageQuality"))).toInt(), 100)},
      {QStringLiteral("preserveTransparency"),
       settings.value(QStringLiteral("preserveTransparency"),
                      current.value(QStringLiteral("preserveTransparency"))).toBool()},
      {QStringLiteral("colorSpace"),
       normalized_output_color_space_name(settings.value(
           QStringLiteral("colorSpace"), current.value(QStringLiteral("colorSpace"))).toString())},
      {QStringLiteral("filenamePattern"),
       normalized_export_filename_pattern(settings.value(
           QStringLiteral("filenamePattern"), current.value(QStringLiteral("filenamePattern"))).toString())},
      {QStringLiteral("collisionPolicy"),
       normalized_export_collision_policy(settings.value(
           QStringLiteral("collisionPolicy"), current.value(QStringLiteral("collisionPolicy"))).toString())},
      {QStringLiteral("manifestEnabled"),
       settings.value(QStringLiteral("manifestEnabled"),
                      current.value(QStringLiteral("manifestEnabled"))).toBool()},
      {QStringLiteral("proofSheetEnabled"),
       settings.value(QStringLiteral("proofSheetEnabled"),
                      current.value(QStringLiteral("proofSheetEnabled"))).toBool()},
      {QStringLiteral("proofIncludeNotes"),
       settings.value(QStringLiteral("proofIncludeNotes"),
                      current.value(QStringLiteral("proofIncludeNotes"))).toBool()},
  };
}

void CarouselDocumentController::applyExportPresetSettings(const QVariantMap& settings) {
  const auto normalized = normalizedExportPresetSettings(settings);
  export_board_scope_ = normalized.value(QStringLiteral("boardScope")).toString();
  export_size_mode_ = normalized.value(QStringLiteral("sizeMode")).toString();
  export_custom_pixel_width_ = normalized.value(QStringLiteral("customWidth")).toInt();
  export_custom_pixel_height_ = normalized.value(QStringLiteral("customHeight")).toInt();
  export_aspect_locked_ = normalized.value(QStringLiteral("aspectLocked")).toBool();
  export_image_format_ = normalized.value(QStringLiteral("imageFormat")).toString();
  export_image_quality_ = normalized.value(QStringLiteral("imageQuality")).toInt();
  export_preserve_transparency_ =
      normalized.value(QStringLiteral("preserveTransparency")).toBool();
  export_color_space_ = normalized.value(QStringLiteral("colorSpace")).toString();
  export_filename_pattern_ = normalized.value(QStringLiteral("filenamePattern")).toString();
  export_collision_policy_ = normalized.value(QStringLiteral("collisionPolicy")).toString();
  export_manifest_enabled_ = normalized.value(QStringLiteral("manifestEnabled")).toBool();
  export_proof_sheet_enabled_ = normalized.value(QStringLiteral("proofSheetEnabled")).toBool();
  export_proof_include_notes_ = normalized.value(QStringLiteral("proofIncludeNotes")).toBool();
}

QVariantMap CarouselDocumentController::exportPresetState() const {
  const auto current = currentExportPresetControlledSettings();
  const auto baseline = normalizedExportPresetSettings(export_preset_baseline_);
  QVariantList overrides;
  if (!active_export_preset_id_.isEmpty() && !export_preset_baseline_.isEmpty()) {
    const QVariantMap labels{
        {QStringLiteral("boardScope"), QStringLiteral("Board scope")},
        {QStringLiteral("sizeMode"), QStringLiteral("Size mode")},
        {QStringLiteral("customWidth"), QStringLiteral("Custom width")},
        {QStringLiteral("customHeight"), QStringLiteral("Custom height")},
        {QStringLiteral("aspectLocked"), QStringLiteral("Aspect lock")},
        {QStringLiteral("imageFormat"), QStringLiteral("Image format")},
        {QStringLiteral("imageQuality"), QStringLiteral("Image quality")},
        {QStringLiteral("preserveTransparency"), QStringLiteral("Transparency")},
        {QStringLiteral("colorSpace"), QStringLiteral("Color profile")},
        {QStringLiteral("filenamePattern"), QStringLiteral("Filename pattern")},
        {QStringLiteral("collisionPolicy"), QStringLiteral("Collision policy")},
        {QStringLiteral("manifestEnabled"), QStringLiteral("Delivery manifest")},
        {QStringLiteral("proofSheetEnabled"), QStringLiteral("PDF review sheet")},
        {QStringLiteral("proofIncludeNotes"), QStringLiteral("PDF board notes")},
    };
    for (auto iterator = baseline.constBegin(); iterator != baseline.constEnd(); ++iterator) {
      if (current.value(iterator.key()) == iterator.value()) {
        continue;
      }
      overrides.push_back(QVariantMap{
          {QStringLiteral("key"), iterator.key()},
          {QStringLiteral("label"), labels.value(iterator.key(), iterator.key())},
          {QStringLiteral("presetValue"), iterator.value()},
          {QStringLiteral("resolvedValue"), current.value(iterator.key())},
      });
    }
  }

  const auto active = exportPresetById(active_export_preset_id_);
  const auto output_size = configuredExportPixelSize();
  const auto display_value = [](const QVariant& value) {
    if (value.metaType().id() == QMetaType::Bool) {
      return value.toBool() ? QStringLiteral("On") : QStringLiteral("Off");
    }
    return value.toString();
  };
  const auto is_overridden = [&overrides](const QString& key) {
    return std::any_of(overrides.constBegin(), overrides.constEnd(), [&key](const QVariant& value) {
      return value.toMap().value(QStringLiteral("key")).toString() == key;
    });
  };
  QVariantList resolved_rows;
  const auto append_row = [&resolved_rows, &is_overridden](
                              const QString& key,
                              const QString& label,
                              const QString& value) {
    resolved_rows.push_back(QVariantMap{
        {QStringLiteral("key"), key},
        {QStringLiteral("label"), label},
        {QStringLiteral("value"), value},
        {QStringLiteral("overridden"), is_overridden(key)},
    });
  };
  append_row(QStringLiteral("documentFormat"), QStringLiteral("Document ratio"),
             QString(document_format_).replace(QLatin1Char('x'), QLatin1Char(':')));
  append_row(QStringLiteral("boardScope"), QStringLiteral("Board scope"), export_board_scope_);
  append_row(QStringLiteral("sizeMode"), QStringLiteral("Size mode"), export_size_mode_);
  append_row(QStringLiteral("dimensions"), QStringLiteral("Resolved dimensions"),
             QStringLiteral("%1 × %2 px").arg(output_size.width()).arg(output_size.height()));
  append_row(QStringLiteral("imageFormat"), QStringLiteral("Image format"),
             export_image_format_ == QStringLiteral("jpeg") ? QStringLiteral("JPEG")
                                                              : export_image_format_.toUpper());
  append_row(QStringLiteral("imageQuality"), QStringLiteral("Image quality"),
             QStringLiteral("%1%").arg(export_image_quality_));
  append_row(QStringLiteral("preserveTransparency"), QStringLiteral("Preserve transparency"),
             display_value(export_preserve_transparency_));
  append_row(QStringLiteral("colorSpace"), QStringLiteral("Color profile"), export_color_space_);
  append_row(QStringLiteral("filenamePattern"), QStringLiteral("Filename pattern"),
             export_filename_pattern_);
  append_row(QStringLiteral("exportVersion"), QStringLiteral("Output version"),
             QStringLiteral("v%1").arg(export_version_));
  append_row(QStringLiteral("collisionPolicy"), QStringLiteral("Existing files"),
             export_collision_policy_);
  append_row(QStringLiteral("manifestEnabled"), QStringLiteral("Delivery manifest"),
             display_value(export_manifest_enabled_));
  append_row(QStringLiteral("proofSheetEnabled"), QStringLiteral("PDF review sheet"),
             display_value(export_proof_sheet_enabled_));
  append_row(QStringLiteral("proofIncludeNotes"), QStringLiteral("PDF board notes"),
             export_proof_sheet_enabled_ ? display_value(export_proof_include_notes_)
                                         : QStringLiteral("Not applicable"));
  append_row(QStringLiteral("destination"), QStringLiteral("Destination"),
             export_directory_.isEmpty() ? QStringLiteral("Not selected") : export_directory_);
  append_row(QStringLiteral("partialCleanupPolicy"), QStringLiteral("Partial-file cleanup"),
             export_partial_cleanup_policy_);

  const auto current_catalog_version = active.value(QStringLiteral("presetVersion")).toInt();
  return {
      {QStringLiteral("hasActivePreset"), !active_export_preset_id_.isEmpty()},
      {QStringLiteral("activePresetId"), active_export_preset_id_},
      {QStringLiteral("activePresetName"),
       active.isEmpty() ? QStringLiteral("Custom settings")
                        : active.value(QStringLiteral("name"))},
      {QStringLiteral("activePresetVersion"), active_export_preset_version_},
      {QStringLiteral("currentCatalogVersion"), current_catalog_version},
      {QStringLiteral("updateAvailable"),
       current_catalog_version > 0 && active_export_preset_version_ < current_catalog_version},
      {QStringLiteral("presetAvailable"), !active.isEmpty()},
      {QStringLiteral("compatible"), active.value(QStringLiteral("compatible"), true)},
      {QStringLiteral("compatibilityMessage"),
       active.value(QStringLiteral("compatibilityMessage"))},
      {QStringLiteral("overrideCount"), overrides.size()},
      {QStringLiteral("overrides"), overrides},
      {QStringLiteral("baselineSettings"), export_preset_baseline_},
      {QStringLiteral("controlledSettings"), current},
      {QStringLiteral("resolvedRows"), resolved_rows},
      {QStringLiteral("guidanceLastReviewed"),
       active.value(QStringLiteral("guidanceLastReviewed"))},
      {QStringLiteral("guidanceReviewDue"),
       active.value(QStringLiteral("guidanceReviewDue"))},
      {QStringLiteral("guidanceStale"), active.value(QStringLiteral("guidanceStale"), false)},
      {QStringLiteral("guidanceSourceUrl"),
       active.value(QStringLiteral("guidanceSourceUrl"))},
      {QStringLiteral("guidanceSourceUpdated"),
       active.value(QStringLiteral("guidanceSourceUpdated"))},
      {QStringLiteral("guidanceSummary"), active.value(QStringLiteral("guidanceSummary"))},
      {QStringLiteral("appChosenDefaults"), active.value(QStringLiteral("appChosenDefaults"))},
  };
}

