QVariantMap CarouselDocumentController::exportSizeSettings() const {
  const auto base_size = exportPixelSize();
  const auto output_size = configuredExportPixelSize();
  QString warning;
  const auto base_ratio = static_cast<double>(base_size.width()) / qMax(1, base_size.height());
  const auto output_ratio = static_cast<double>(output_size.width()) / qMax(1, output_size.height());
  if (output_size.width() > 4096 || output_size.height() > 4096) {
    warning = QStringLiteral(
        "This output exceeds 4096 px on one edge; many social platforms will downsample it.");
  } else if (qAbs(base_ratio - output_ratio) > 0.005) {
    warning = QStringLiteral(
        "The unlocked custom size changes the canvas aspect ratio and will stretch the rendered board.");
  } else if (export_size_mode_ == QStringLiteral("2x")) {
    warning = QStringLiteral(
        "2× output is for high-density delivery; social platforms may downsample it.");
  }
  return {
      {QStringLiteral("mode"), export_size_mode_},
      {QStringLiteral("baseWidth"), base_size.width()},
      {QStringLiteral("baseHeight"), base_size.height()},
      {QStringLiteral("width"), output_size.width()},
      {QStringLiteral("height"), output_size.height()},
      {QStringLiteral("customWidth"), export_custom_pixel_width_},
      {QStringLiteral("customHeight"), export_custom_pixel_height_},
      {QStringLiteral("aspectLocked"), export_aspect_locked_},
      {QStringLiteral("previewResolution"),
       QStringLiteral("%1 × %2").arg(base_size.width()).arg(base_size.height())},
      {QStringLiteral("exportResolution"),
       QStringLiteral("%1 × %2").arg(output_size.width()).arg(output_size.height())},
      {QStringLiteral("warning"), warning},
  };
}

QStringList CarouselDocumentController::exportSizeModeOptions() const {
  return {QStringLiteral("1x"), QStringLiteral("2x"), QStringLiteral("custom")};
}

QVector<int> CarouselDocumentController::exportBoardIndexes() const {
  if (slides_.isEmpty()) {
    return {};
  }
  if (export_board_scope_ == QStringLiteral("current")) {
    return {qBound(0, current_index_, static_cast<int>(slides_.size()) - 1)};
  }
  if (export_board_scope_ == QStringLiteral("selected")) {
    QVector<int> indexes;
    for (const auto index : selected_slide_indices_) {
      if (index >= 0 && index < slides_.size() && !indexes.contains(index)) {
        indexes.push_back(index);
      }
    }
    if (indexes.isEmpty()) {
      indexes.push_back(qBound(0, current_index_, static_cast<int>(slides_.size()) - 1));
    }
    std::sort(indexes.begin(), indexes.end());
    return indexes;
  }
  QVector<int> indexes;
  indexes.reserve(slides_.size());
  for (int index = 0; index < slides_.size(); ++index) {
    indexes.push_back(index);
  }
  return indexes;
}

QVariantList CarouselDocumentController::exportPreflightIssues() const {
  const auto board_indexes = exportBoardIndexes();
  QSet<int> included_boards;
  for (const auto index : board_indexes) {
    included_boards.insert(index);
  }
  const QSet<QString> global_codes{
      QStringLiteral("unsupported-image-format"),
      QStringLiteral("jpeg-transparency-flattened"),
      QStringLiteral("platform-output-size"),
      QStringLiteral("custom-export-aspect"),
  };
  QVariantList scoped_issues;
  for (const auto& value : preflightIssues()) {
    const auto issue = value.toMap();
    const auto code = issue.value(QStringLiteral("code")).toString();
    if (code == QStringLiteral("duplicate-output-name")) {
      continue;
    }
    const auto board_index = issue.value(QStringLiteral("boardIndex"), -1).toInt();
    bool affects_scope = global_codes.contains(code) || included_boards.contains(board_index);
    if (!affects_scope) {
      if (const auto* group = groupForIndex(board_index); group != nullptr) {
        for (int index = group->start_index; index < group->start_index + group->span; ++index) {
          if (included_boards.contains(index)) {
            affects_scope = true;
            break;
          }
        }
      }
    }
    if (affects_scope) {
      scoped_issues.push_back(issue);
    }
  }

  QSet<QString> output_names;
  for (const auto& value : exportOutputPreview()) {
    const auto plan = value.toMap();
    const auto board_index = plan.value(QStringLiteral("boardIndex"), -1).toInt();
    if (board_index < 0) {
      continue;
    }
    const auto output_name = plan.value(QStringLiteral("proposedName")).toString().toLower();
    if (output_names.contains(output_name)) {
      const auto message = QStringLiteral("Board %1 resolves to a duplicate export filename.")
                               .arg(board_index + 1);
      const auto message_hash = QString::fromLatin1(
          QCryptographicHash::hash(message.toUtf8(), QCryptographicHash::Sha256).toHex().left(12));
      const auto issue_id = QStringLiteral("duplicate-output-name:%1::%2")
                                .arg(board_index)
                                .arg(message_hash);
      scoped_issues.push_back(QVariantMap{
          {QStringLiteral("issueId"), issue_id},
          {QStringLiteral("code"), QStringLiteral("duplicate-output-name")},
          {QStringLiteral("severity"), QStringLiteral("error")},
          {QStringLiteral("blocking"), true},
          {QStringLiteral("boardIndex"), board_index},
          {QStringLiteral("boardNumber"), board_index + 1},
          {QStringLiteral("itemId"), QString{}},
          {QStringLiteral("message"), message},
          {QStringLiteral("actions"), QVariantList{}},
      });
    }
    output_names.insert(output_name);
  }
  return scoped_issues;
}

QVariantList CarouselDocumentController::exportOutputPreview() const {
  QVariantList preview;
  QSet<QString> occupied_names;
  const QDir output_dir(export_directory_);
  for (const auto index : exportBoardIndexes()) {
    const auto* slide = slideAt(index);
    const bool video = slide != nullptr && slide->template_kind == SlideTemplate::Single &&
                       slide->primary.type == MediaType::Video;
    const auto extension = video ? QStringLiteral("mp4")
                                 : export_image_format_ == QStringLiteral("jpeg")
                                       ? QStringLiteral("jpg")
                                       : export_image_format_;
    const auto base_name = exportBaseNameForSlide(index);
    const auto proposed_name = QStringLiteral("%1.%2").arg(base_name, extension);
    const auto proposed_key = proposed_name.toLower();
    const bool collides_in_job = occupied_names.contains(proposed_key);
    const bool exists_on_disk = !export_directory_.isEmpty() && output_dir.exists(proposed_name);
    const bool collision = collides_in_job || exists_on_disk;
    auto resolved_name = proposed_name;
    auto action = QStringLiteral("write");
    if (collision && export_collision_policy_ == QStringLiteral("rename")) {
      int suffix = 2;
      do {
        resolved_name = QStringLiteral("%1-%2.%3").arg(base_name).arg(suffix).arg(extension);
        ++suffix;
      } while (occupied_names.contains(resolved_name.toLower()) ||
               (!export_directory_.isEmpty() && output_dir.exists(resolved_name)));
      action = QStringLiteral("rename");
    } else if (collision && export_collision_policy_ == QStringLiteral("skip")) {
      action = QStringLiteral("skip");
    } else if (collision) {
      action = QStringLiteral("overwrite");
    }
    occupied_names.insert(resolved_name.toLower());
    preview.push_back(QVariantMap{
        {QStringLiteral("artifactType"), QStringLiteral("board")},
        {QStringLiteral("boardIndex"), index},
        {QStringLiteral("boardNumber"), index + 1},
        {QStringLiteral("boardRole"), slide != nullptr ? slide->board_role : QStringLiteral("content")},
        {QStringLiteral("boardName"), slide != nullptr ? slide->board_name : QString{}},
        {QStringLiteral("previewSource"), slide != nullptr ? slide->preview_source : QString{}},
        {QStringLiteral("backgroundColor"),
         slide != nullptr ? slide->background_color : QStringLiteral("#fbf7f1")},
        {QStringLiteral("proposedName"), proposed_name},
        {QStringLiteral("resolvedName"), resolved_name},
        {QStringLiteral("collision"), collision},
        {QStringLiteral("action"), action},
        {QStringLiteral("fileType"), extension.toUpper()},
        {QStringLiteral("outputPath"), export_directory_.isEmpty() ? QString{} : output_dir.filePath(resolved_name)},
    });
  }
  if (export_proof_sheet_enabled_) {
    const auto base_name = sanitized_filename_component(
        QStringLiteral("%1-proof-v%2").arg(document_name_).arg(export_version_));
    const auto proposed_name = base_name + QStringLiteral(".pdf");
    const bool collision = occupied_names.contains(proposed_name.toLower()) ||
                           (!export_directory_.isEmpty() && output_dir.exists(proposed_name));
    auto resolved_name = proposed_name;
    auto action = QStringLiteral("write");
    if (collision && export_collision_policy_ == QStringLiteral("rename")) {
      int suffix = 2;
      do {
        resolved_name = QStringLiteral("%1-%2.pdf").arg(base_name).arg(suffix);
        ++suffix;
      } while (occupied_names.contains(resolved_name.toLower()) ||
               (!export_directory_.isEmpty() && output_dir.exists(resolved_name)));
      action = QStringLiteral("rename");
    } else if (collision && export_collision_policy_ == QStringLiteral("skip")) {
      action = QStringLiteral("skip");
    } else if (collision) {
      action = QStringLiteral("overwrite");
    }
    occupied_names.insert(resolved_name.toLower());
    preview.push_back(QVariantMap{
        {QStringLiteral("artifactType"), QStringLiteral("proof")},
        {QStringLiteral("boardIndex"), -2},
        {QStringLiteral("boardNumber"), 0},
        {QStringLiteral("boardRole"), QStringLiteral("proof")},
        {QStringLiteral("proposedName"), proposed_name},
        {QStringLiteral("resolvedName"), resolved_name},
        {QStringLiteral("collision"), collision},
        {QStringLiteral("action"), action},
        {QStringLiteral("fileType"), QStringLiteral("PDF")},
        {QStringLiteral("pageSize"), QStringLiteral("A4 landscape")},
        {QStringLiteral("boardsPerPage"), 4},
        {QStringLiteral("includeNotes"), export_proof_include_notes_},
        {QStringLiteral("thumbnailColorManagement"),
         QStringLiteral("%1 to sRGB proof space").arg(export_color_space_)},
        {QStringLiteral("outputPath"),
         export_directory_.isEmpty() ? QString{} : output_dir.filePath(resolved_name)},
    });
  }
  if (export_manifest_enabled_) {
    const auto base_name = sanitized_filename_component(
        QStringLiteral("%1-delivery-manifest-v%2").arg(document_name_).arg(export_version_));
    const auto proposed_name = base_name + QStringLiteral(".json");
    const bool collision = occupied_names.contains(proposed_name.toLower()) ||
                           (!export_directory_.isEmpty() && output_dir.exists(proposed_name));
    auto resolved_name = proposed_name;
    auto action = QStringLiteral("write");
    if (collision && export_collision_policy_ == QStringLiteral("rename")) {
      int suffix = 2;
      do {
        resolved_name = QStringLiteral("%1-%2.json").arg(base_name).arg(suffix);
        ++suffix;
      } while (occupied_names.contains(resolved_name.toLower()) ||
               (!export_directory_.isEmpty() && output_dir.exists(resolved_name)));
      action = QStringLiteral("rename");
    } else if (collision && export_collision_policy_ == QStringLiteral("skip")) {
      action = QStringLiteral("skip");
    } else if (collision) {
      action = QStringLiteral("overwrite");
    }
    preview.push_back(QVariantMap{
        {QStringLiteral("artifactType"), QStringLiteral("manifest")},
        {QStringLiteral("boardIndex"), -1},
        {QStringLiteral("boardNumber"), 0},
        {QStringLiteral("boardRole"), QStringLiteral("manifest")},
        {QStringLiteral("proposedName"), proposed_name},
        {QStringLiteral("resolvedName"), resolved_name},
        {QStringLiteral("collision"), collision},
        {QStringLiteral("action"), action},
        {QStringLiteral("fileType"), QStringLiteral("JSON")},
        {QStringLiteral("outputPath"), export_directory_.isEmpty() ? QString{} : output_dir.filePath(resolved_name)},
    });
  }
  return preview;
}

