QVariantList CarouselDocumentController::templateLibraryEntries() const {
  QVariantList entries;
  const auto decorate = [this](QVariantMap entry, const QString& source_section,
                               const QString& entry_kind, const QString& preview_kind,
                               int preview_maximum_width, int preview_maximum_height) {
    const auto template_id = entry.value(QStringLiteral("templateId")).toString();
    const auto recent_rank = recent_template_ids_.indexOf(template_id);
    entry.insert(QStringLiteral("sourceSection"), source_section);
    entry.insert(QStringLiteral("entryKind"), entry_kind);
    entry.insert(QStringLiteral("goal"), entry.value(QStringLiteral("category")));
    entry.insert(QStringLiteral("isFavorite"), favorite_template_ids_.contains(template_id));
    entry.insert(QStringLiteral("isRecent"), recent_rank >= 0);
    entry.insert(QStringLiteral("recentRank"), recent_rank);
    entry.insert(QStringLiteral("previewKind"), preview_kind);
    entry.insert(QStringLiteral("previewMaximumPixelWidth"), preview_maximum_width);
    entry.insert(QStringLiteral("previewMaximumPixelHeight"), preview_maximum_height);
    return entry;
  };

  const auto installed = sequenceTemplates();
  entries.reserve(installed.size() + user_templates_.size());
  for (const auto& value : installed) {
    auto entry = value.toMap();
    entry.insert(QStringLiteral("kind"), QStringLiteral("sequence"));
    entry.insert(QStringLiteral("itemCount"), 0);
    entry.insert(QStringLiteral("previewSource"), QString{});
    entries.push_back(decorate(
        std::move(entry), QStringLiteral("installed"), QStringLiteral("sequence"),
        QStringLiteral("role-metadata"), 0, 0));
  }

  for (const auto& stored : user_templates_) {
    const auto kind = stored.value(QStringLiteral("kind")).toString() == QStringLiteral("component")
                          ? QStringLiteral("component")
                          : QStringLiteral("board");
    const auto item_count = stored.value(QStringLiteral("items")).toArray().size();
    QVariantList preview_roles;
    preview_roles.push_back(kind == QStringLiteral("component")
                                ? QStringLiteral("Component")
                                : QStringLiteral("Saved board"));
    QVariantMap entry{
        {QStringLiteral("templateId"), stored.value(QStringLiteral("templateId")).toString()},
        {QStringLiteral("name"), stored.value(QStringLiteral("name")).toString()},
        {QStringLiteral("category"), stored.value(QStringLiteral("category")).toString()},
        {QStringLiteral("kind"), kind},
        {QStringLiteral("purpose"),
         kind == QStringLiteral("component")
             ? QStringLiteral("Reusable component with %1 editable layers.").arg(item_count)
             : QStringLiteral("Saved board with %1 editable layers.").arg(item_count)},
        {QStringLiteral("boardCount"), kind == QStringLiteral("board") ? 1 : 0},
        {QStringLiteral("requiredMedia"), 0},
        {QStringLiteral("supportedRatios"), QStringLiteral("Scales to the current board")},
        {QStringLiteral("previewRoles"), preview_roles},
        {QStringLiteral("itemCount"), item_count},
        {QStringLiteral("previewSource"),
         fileUrlForPath(stored.value(QStringLiteral("previewPath")).toString())},
    };
    const auto has_thumbnail = !stored.value(QStringLiteral("previewPath")).toString().isEmpty();
    entries.push_back(decorate(
        std::move(entry), QStringLiteral("custom"), kind,
        has_thumbnail ? QStringLiteral("bounded-thumbnail") : QStringLiteral("symbol"),
        has_thumbnail ? 320 : 0, has_thumbnail ? 400 : 0));
  }
  return entries;
}

QVariantList CarouselDocumentController::componentLibraryEntries() const {
  QVariantList entries;
  const auto built_ins = built_in_component_specs();
  entries.reserve(built_ins.size() + user_templates_.size());
  for (auto entry : built_ins) {
    const auto component_id = entry.value(QStringLiteral("componentId")).toString();
    entry.insert(QStringLiteral("definitionId"), QStringLiteral("builtin:%1").arg(component_id));
    entry.insert(QStringLiteral("definitionVersion"), 1);
    entry.insert(QStringLiteral("source"), QStringLiteral("built-in"));
    entry.insert(
        QStringLiteral("previewSource"),
        fileUrlForPath(built_in_component_preview_path(component_id)));
    entry.insert(QStringLiteral("previewMaximumPixelWidth"), 240);
    entry.insert(QStringLiteral("previewMaximumPixelHeight"), 160);
    entries.push_back(entry);
  }
  for (const auto& stored : user_templates_) {
    if (stored.value(QStringLiteral("kind")).toString() != QStringLiteral("component")) {
      continue;
    }
    const auto template_id = stored.value(QStringLiteral("templateId")).toString();
    entries.push_back(QVariantMap{
        {QStringLiteral("componentId"), template_id},
        {QStringLiteral("definitionId"), QStringLiteral("custom:%1").arg(template_id)},
        {QStringLiteral("definitionVersion"),
         qMax(1, stored.value(QStringLiteral("componentDefinitionVersion")).toInt(1))},
        {QStringLiteral("name"), stored.value(QStringLiteral("name")).toString()},
        {QStringLiteral("category"), stored.value(QStringLiteral("category")).toString()},
        {QStringLiteral("description"), QStringLiteral("Saved editable component")},
        {QStringLiteral("layerCount"), stored.value(QStringLiteral("items")).toArray().size()},
        {QStringLiteral("source"), QStringLiteral("custom")},
        {QStringLiteral("previewSource"),
         fileUrlForPath(stored.value(QStringLiteral("previewPath")).toString())},
        {QStringLiteral("previewMaximumPixelWidth"), 320},
        {QStringLiteral("previewMaximumPixelHeight"), 400},
    });
  }
  return entries;
}

QVariantMap CarouselDocumentController::componentInstanceState() const {
  QVariantMap state{
      {QStringLiteral("attached"), false},
      {QStringLiteral("definitionId"), QString{}},
      {QStringLiteral("definitionName"), QString{}},
      {QStringLiteral("instanceId"), QString{}},
      {QStringLiteral("source"), QString{}},
      {QStringLiteral("version"), 0},
      {QStringLiteral("currentVersion"), 0},
      {QStringLiteral("updateAvailable"), false},
      {QStringLiteral("layerCount"), 0},
      {QStringLiteral("localOverrideCount"), 0},
      {QStringLiteral("canUpdateDefinition"), false},
      {QStringLiteral("canApplyUpdate"), false},
      {QStringLiteral("canDetach"), false},
  };
  const auto* selected = currentItem();
  if (selected == nullptr || selected->component_definition_id.isEmpty() ||
      selected->component_instance_id.isEmpty()) {
    return state;
  }
  const auto definition_id = selected->component_definition_id;
  const auto instance_id = selected->component_instance_id;
  const auto custom = definition_id.startsWith(QStringLiteral("custom:"));
  const auto template_id = custom ? definition_id.mid(QStringLiteral("custom:").size())
                                  : QString{};
  const auto* stored = custom ? userTemplateById(template_id) : nullptr;
  int layer_count = 0;
  int local_override_count = 0;
  for (const auto& item : items_) {
    if (item.component_instance_id != instance_id) {
      continue;
    }
    ++layer_count;
    if (componentItemHasLocalOverrides(item)) {
      ++local_override_count;
    }
  }
  const auto current_version = stored != nullptr
                                   ? qMax(1, stored->value(
                                                 QStringLiteral("componentDefinitionVersion"))
                                                 .toInt(1))
                                   : qMax(1, selected->component_definition_version);
  QString definition_name;
  if (stored != nullptr) {
    definition_name = stored->value(QStringLiteral("name")).toString();
  } else {
    for (const auto& spec : built_in_component_specs()) {
      if (definition_id == QStringLiteral("builtin:%1").arg(
                               spec.value(QStringLiteral("componentId")).toString())) {
        definition_name = spec.value(QStringLiteral("name")).toString();
        break;
      }
    }
  }
  state.insert(QStringLiteral("attached"), true);
  state.insert(QStringLiteral("definitionId"), definition_id);
  state.insert(QStringLiteral("definitionName"), definition_name);
  state.insert(QStringLiteral("instanceId"), instance_id);
  state.insert(QStringLiteral("source"), custom ? QStringLiteral("custom")
                                                 : QStringLiteral("built-in"));
  state.insert(QStringLiteral("version"), selected->component_definition_version);
  state.insert(QStringLiteral("currentVersion"), current_version);
  state.insert(
      QStringLiteral("updateAvailable"),
      stored != nullptr && current_version > selected->component_definition_version);
  state.insert(QStringLiteral("layerCount"), layer_count);
  state.insert(QStringLiteral("localOverrideCount"), local_override_count);
  state.insert(QStringLiteral("canUpdateDefinition"), stored != nullptr);
  state.insert(
      QStringLiteral("canApplyUpdate"),
      stored != nullptr && current_version > selected->component_definition_version);
  state.insert(QStringLiteral("canDetach"), layer_count > 0);
  return state;
}

