QVariantMap CarouselDocumentController::templatePackUpdateState() const {
  QVariantMap state{
      {QStringLiteral("sourceTemplateId"), source_template_id_},
      {QStringLiteral("sourceVersion"), source_template_version_},
      {QStringLiteral("currentVersion"), source_template_version_},
      {QStringLiteral("templateName"), QString{}},
      {QStringLiteral("updateAvailable"), false},
      {QStringLiteral("changes"), QVariantList{}},
      {QStringLiteral("automaticMigration"), false},
      {QStringLiteral("requiresApproval"), true},
      {QStringLiteral("migrationHistory"), source_template_migration_history_},
  };
  if (source_template_id_.isEmpty() || source_template_version_ <= 0) {
    return state;
  }
  for (const auto& value : sequenceTemplates()) {
    const auto metadata = value.toMap();
    if (metadata.value(QStringLiteral("templateId")).toString() != source_template_id_) {
      continue;
    }
    const auto current_version = qMax(1, metadata.value(QStringLiteral("packVersion")).toInt());
    state.insert(QStringLiteral("currentVersion"), current_version);
    state.insert(QStringLiteral("templateName"), metadata.value(QStringLiteral("name")));
    state.insert(QStringLiteral("updateAvailable"), current_version > source_template_version_);
    if (current_version > source_template_version_) {
      state.insert(QStringLiteral("changes"), metadata.value(QStringLiteral("changesSincePrevious")));
    }
    break;
  }
  return state;
}

