QVariantList CarouselDocumentController::brandColorTokens() const {
  QVariantList tokens;
  for (const auto& stored : brand_kits_) {
    const auto kit = normalized_brand_kit(stored);
    const auto brand_id = kit.value(QStringLiteral("brandId")).toString();
    const auto brand_name = kit.value(QStringLiteral("name")).toString();
    const auto palette = kit.value(QStringLiteral("palette")).toObject();
    for (const auto& group : {QStringLiteral("primary"), QStringLiteral("secondary"),
                              QStringLiteral("accent")}) {
      const auto entries = palette.value(group).toArray();
      for (int index = 0; index < entries.size(); ++index) {
        const auto token = entries.at(index).toObject();
        const auto token_id = QStringLiteral("%1:%2").arg(group).arg(index);
        tokens.push_back(QVariantMap{
            {QStringLiteral("bindingId"), brand_id + QLatin1Char('|') + token_id},
            {QStringLiteral("brandId"), brand_id},
            {QStringLiteral("brandName"), brand_name},
            {QStringLiteral("tokenId"), token_id},
            {QStringLiteral("group"), group},
            {QStringLiteral("name"), token.value(QStringLiteral("name")).toString()},
            {QStringLiteral("value"), normalized_color_value(
                 token.value(QStringLiteral("value")).toString(), QString{})},
        });
      }
    }
  }
  return tokens;
}

QVariantList CarouselDocumentController::brandTypographyTokens() const {
  QVariantList tokens;
  const auto roles = {QStringLiteral("title"), QStringLiteral("subtitle"),
                      QStringLiteral("heading"), QStringLiteral("body"),
                      QStringLiteral("caption"), QStringLiteral("quote"),
                      QStringLiteral("attribution"), QStringLiteral("number"),
                      QStringLiteral("cta")};
  for (const auto& stored : brand_kits_) {
    const auto kit = normalized_brand_kit(stored);
    const auto brand_id = kit.value(QStringLiteral("brandId")).toString();
    const auto brand_name = kit.value(QStringLiteral("name")).toString();
    const auto text_roles = kit.value(QStringLiteral("textRoles")).toObject();
    for (const auto& role : roles) {
      const auto token = text_roles.value(role).toObject();
      if (token.isEmpty()) {
        continue;
      }
      tokens.push_back(QVariantMap{
          {QStringLiteral("bindingId"), brand_id + QLatin1Char('|') + role},
          {QStringLiteral("brandId"), brand_id},
          {QStringLiteral("brandName"), brand_name},
          {QStringLiteral("tokenId"), role},
          {QStringLiteral("name"), role.left(1).toUpper() + role.mid(1)},
          {QStringLiteral("fontFamily"), token.value(QStringLiteral("fontFamily")).toString()},
          {QStringLiteral("fontWeight"), token.value(QStringLiteral("fontWeight")).toString()},
          {QStringLiteral("color"), token.value(QStringLiteral("color")).toString()},
      });
    }
  }
  return tokens;
}

QVariantList CarouselDocumentController::brandThemeVariants() const {
  QVariantList variants;
  for (const auto& stored : brand_kits_) {
    const auto kit = normalized_brand_kit(stored);
    const auto brand_id = kit.value(QStringLiteral("brandId")).toString();
    const auto brand_name = kit.value(QStringLiteral("name")).toString();
    const auto stored_variants = kit.value(QStringLiteral("themeVariants")).toObject();
    for (const auto& variant_id : {QStringLiteral("light"), QStringLiteral("dark"),
                                   QStringLiteral("campaign")}) {
      const auto variant = stored_variants.value(variant_id).toObject();
      variants.push_back(QVariantMap{
          {QStringLiteral("bindingId"), brand_id + QLatin1Char('|') + variant_id},
          {QStringLiteral("brandId"), brand_id},
          {QStringLiteral("brandName"), brand_name},
          {QStringLiteral("variantId"), variant_id},
          {QStringLiteral("name"), variant.value(QStringLiteral("name")).toString()},
          {QStringLiteral("backgroundColor"), variant.value(QStringLiteral("backgroundColor")).toString()},
          {QStringLiteral("textColor"), variant.value(QStringLiteral("textColor")).toString()},
          {QStringLiteral("accentColor"), variant.value(QStringLiteral("accentColor")).toString()},
      });
    }
  }
  return variants;
}

