QString CarouselDocumentController::resolvedVariableTextForItem(const CanvasItem& item) const {
  auto resolved = item.text;
  auto values = document_variables_;
  if (values.value(QStringLiteral("title")).toString().isEmpty()) {
    values.insert(QStringLiteral("title"), document_name_);
  }
  values.insert(QStringLiteral("board_number"), slideIndexForItem(item) + 1);
  values.insert(QStringLiteral("total_boards"), slideCount());
  for (const auto& key : documentVariableKeys()) {
    const auto value = values.value(key).toString();
    if (!value.isEmpty()) {
      resolved.replace(QStringLiteral("{{%1}}").arg(key), value);
    }
  }
  return resolved;
}

int CarouselDocumentController::stepNumberForItem(const CanvasItem& item) const {
  const auto item_board = slideIndexForItem(item);
  int number = 1;
  for (const auto& candidate : items_) {
    if (candidate.id == item.id) {
      continue;
    }
    if (candidate.kind != ItemKind::Text ||
        candidate.text_auto_number_source != QStringLiteral("step")) {
      continue;
    }
    const auto candidate_board = slideIndexForItem(candidate);
    if (candidate_board < item_board ||
        (candidate_board == item_board &&
         (candidate.bounds.y() < item.bounds.y() ||
          (qFuzzyCompare(candidate.bounds.y(), item.bounds.y()) &&
           candidate.bounds.x() < item.bounds.x())))) {
      ++number;
    }
  }
  return number;
}

QString CarouselDocumentController::resolvedTextForItem(const CanvasItem& item) const {
  auto resolved = resolvedVariableTextForItem(item);
  if (item.text_auto_number_source == QStringLiteral("board")) {
    return QString::number(slideIndexForItem(item) + 1);
  }
  if (item.text_auto_number_source == QStringLiteral("step")) {
    return QString::number(stepNumberForItem(item));
  }
  if (item.text_list_style == QStringLiteral("none")) {
    return resolved;
  }
  auto paragraphs = resolved.split(QLatin1Char('\n'), Qt::KeepEmptyParts);
  int number = 1;
  for (auto& paragraph : paragraphs) {
    if (paragraph.trimmed().isEmpty()) {
      continue;
    }
    paragraph.prepend(item.text_list_style == QStringLiteral("bullets")
                          ? QStringLiteral("• ")
                          : QStringLiteral("%1. ").arg(number++));
  }
  return paragraphs.join(QLatin1Char('\n'));
}

QVariantList CarouselDocumentController::defaultTextStyles() const {
  const auto style = [](const QString& id,
                        const QString& name,
                        const QString& role,
                        const QString& family,
                        double size,
                        const QString& weight,
                        double line_height) {
    return QVariantMap{
        {QStringLiteral("styleId"), id},
        {QStringLiteral("name"), name},
        {QStringLiteral("role"), role},
        {QStringLiteral("fontFamily"), family},
        {QStringLiteral("pointSize"), size},
        {QStringLiteral("fontWeight"), weight},
        {QStringLiteral("color"), QStringLiteral("#1e1a17")},
        {QStringLiteral("lineHeight"), line_height},
        {QStringLiteral("letterSpacing"), 0.0},
        {QStringLiteral("builtIn"), true},
    };
  };
  return {
      style(QStringLiteral("title"), QStringLiteral("Title"), QStringLiteral("title"),
            QStringLiteral("display"), 112.0, QStringLiteral("bold"), 0.95),
      style(QStringLiteral("subtitle"), QStringLiteral("Subtitle"), QStringLiteral("subtitle"),
            QStringLiteral("system"), 48.0, QStringLiteral("regular"), 1.1),
      style(QStringLiteral("heading"), QStringLiteral("Heading"), QStringLiteral("heading"),
            QStringLiteral("display"), 76.0, QStringLiteral("bold"), 1.0),
      style(QStringLiteral("body"), QStringLiteral("Body"), QStringLiteral("body"),
            QStringLiteral("system"), 38.0, QStringLiteral("regular"), 1.25),
      style(QStringLiteral("caption"), QStringLiteral("Caption"), QStringLiteral("caption"),
            QStringLiteral("system"), 26.0, QStringLiteral("regular"), 1.2),
      style(QStringLiteral("quote"), QStringLiteral("Quote"), QStringLiteral("quote"),
            QStringLiteral("serif"), 58.0, QStringLiteral("medium"), 1.15),
      style(QStringLiteral("attribution"), QStringLiteral("Attribution"), QStringLiteral("attribution"),
            QStringLiteral("system"), 28.0, QStringLiteral("medium"), 1.15),
      style(QStringLiteral("number"), QStringLiteral("Number"), QStringLiteral("number"),
            QStringLiteral("display"), 128.0, QStringLiteral("bold"), 0.9),
      style(QStringLiteral("cta"), QStringLiteral("CTA"), QStringLiteral("cta"),
            QStringLiteral("system"), 42.0, QStringLiteral("bold"), 1.0),
  };
}

QVariantMap CarouselDocumentController::textStyleById(const QString& style_id) const {
  const auto normalized = style_id.trimmed();
  for (const auto& value : text_styles_) {
    const auto style = value.toMap();
    if (style.value(QStringLiteral("styleId")).toString() == normalized) {
      return style;
    }
  }
  return {};
}

QVector<int> CarouselDocumentController::boardIndexesForScope(const QString& scope) const {
  QVector<int> indexes;
  const auto normalized_scope = scope.trimmed().toLower();
  if (normalized_scope == QStringLiteral("current")) {
    indexes.push_back(current_index_);
  } else if (normalized_scope == QStringLiteral("selected")) {
    indexes = selected_slide_indices_;
  } else if (normalized_scope == QStringLiteral("following")) {
    for (int index = current_index_; index < slides_.size(); ++index) {
      indexes.push_back(index);
    }
  } else if (normalized_scope == QStringLiteral("all")) {
    for (int index = 0; index < slides_.size(); ++index) {
      indexes.push_back(index);
    }
  }
  for (qsizetype index = indexes.size(); index > 0; --index) {
    if (indexes.at(index - 1) < 0 || indexes.at(index - 1) >= slides_.size()) {
      indexes.removeAt(index - 1);
    }
  }
  std::sort(indexes.begin(), indexes.end());
  indexes.erase(std::unique(indexes.begin(), indexes.end()), indexes.end());
  return indexes;
}

QVariantMap CarouselDocumentController::textStyleFromItem(
    const CanvasItem& item,
    const QString& style_id,
    const QString& name) const {
  return {
      {QStringLiteral("styleId"), style_id},
      {QStringLiteral("name"), name.simplified()},
      {QStringLiteral("role"), item.text_role},
      {QStringLiteral("fontFamily"), item.text_font_family},
      {QStringLiteral("pointSize"), item.text_fit_mode == QStringLiteral("auto")
                                               ? item.text_fit_max_point_size
                                               : item.text_point_size},
      {QStringLiteral("fontWeight"), item.text_weight},
      {QStringLiteral("color"), item.text_color},
      {QStringLiteral("lineHeight"), item.text_line_height},
      {QStringLiteral("letterSpacing"), item.text_letter_spacing},
      {QStringLiteral("builtIn"), false},
  };
}

