QVariantMap CarouselDocumentController::brandKitValidation() const {
  QVariantList blocking_issues;
  QVariantList warnings;
  QStringList missing_assets;
  QStringList unavailable_fonts;
  if (brand_kit_draft_.value(QStringLiteral("name")).toString().simplified().isEmpty()) {
    blocking_issues.push_back(QStringLiteral("Give the brand kit a name."));
  }
  const auto logo_required = brand_kit_draft_.value(QStringLiteral("logoRequired")).toBool();
  const auto logo_path = normalized_path(brand_kit_draft_.value(QStringLiteral("logoPath")).toString());
  if (logo_required && (logo_path.isEmpty() || !QFileInfo::exists(logo_path))) {
    missing_assets.push_back(
        brand_kit_draft_.value(QStringLiteral("logoName")).toString().simplified().isEmpty()
            ? QStringLiteral("Required logo")
            : brand_kit_draft_.value(QStringLiteral("logoName")).toString().simplified());
    blocking_issues.push_back(QStringLiteral("Choose an existing file for every required logo asset."));
  }
  const auto installed_fonts = QFontDatabase::families();
  for (const auto& key : {QStringLiteral("titleFont"), QStringLiteral("bodyFont")}) {
    const auto family = normalized_text_font_family(brand_kit_draft_.value(key).toString());
    if (!text_font_family_available(family, installed_fonts) &&
        !unavailable_fonts.contains(family, Qt::CaseInsensitive)) {
      unavailable_fonts.push_back(family);
    }
  }
  if (!unavailable_fonts.isEmpty()) {
    warnings.push_back(QStringLiteral("Some font faces are not installed on this computer."));
  }
  const auto license_notes = brand_kit_draft_.value(QStringLiteral("fontLicenseNotes")).toString().simplified();
  if (license_notes.isEmpty()) {
    warnings.push_back(QStringLiteral("Add a font license or source reminder before handoff."));
  }
  if (normalized_path(brand_kit_draft_.value(QStringLiteral("logoLightPath")).toString()).isEmpty()) {
    warnings.push_back(QStringLiteral("Add a light logo variant for dark surfaces."));
  }
  if (normalized_path(brand_kit_draft_.value(QStringLiteral("logoDarkPath")).toString()).isEmpty()) {
    warnings.push_back(QStringLiteral("Add a dark logo variant for light surfaces."));
  }
  if (normalized_path(
          brand_kit_draft_.value(QStringLiteral("logoMonochromePath")).toString()).isEmpty()) {
    warnings.push_back(QStringLiteral("Add a monochrome logo variant for constrained output."));
  }
  return {
      {QStringLiteral("canSave"), blocking_issues.isEmpty()},
      {QStringLiteral("blockingIssues"), blocking_issues},
      {QStringLiteral("warnings"), warnings},
      {QStringLiteral("missingRequiredAssets"), missing_assets},
      {QStringLiteral("unavailableFonts"), unavailable_fonts},
      {QStringLiteral("licenseReminderPending"), license_notes.isEmpty()},
  };
}

