QVariantMap CarouselDocumentController::brandLintState() const {
  const auto* stored = brandKitById(active_brand_lint_kit_id_);
  if (stored == nullptr) {
    return {
        {QStringLiteral("available"), false},
        {QStringLiteral("brandId"), QString{}},
        {QStringLiteral("brandName"), QString{}},
        {QStringLiteral("issues"), QVariantList{}},
        {QStringLiteral("issueCount"), 0},
        {QStringLiteral("ignoredCount"), ignored_brand_lint_issue_ids_.size()},
    };
  }
  const auto kit = normalized_brand_kit(*stored);
  QSet<QString> approved_colors;
  const auto palette = kit.value(QStringLiteral("palette")).toObject();
  for (const auto& group : {QStringLiteral("primary"), QStringLiteral("secondary"), QStringLiteral("accent")}) {
    for (const auto& value : palette.value(group).toArray()) {
      const auto color = normalized_color_value(value.toObject().value(QStringLiteral("value")).toString(), QString{});
      if (!color.isEmpty()) {
        approved_colors.insert(color.toLower());
      }
    }
  }
  QSet<QString> approved_fonts;
  for (const auto& value : kit.value(QStringLiteral("fontFaces")).toArray()) {
    approved_fonts.insert(normalized_text_font_family(
                              value.toObject().value(QStringLiteral("family")).toString())
                              .toLower());
  }
  QHash<QString, QJsonObject> logo_by_path;
  QSet<QString> available_logo_variants;
  for (const auto& value : kit.value(QStringLiteral("logoAssets")).toArray()) {
    const auto logo = value.toObject();
    const auto path = normalized_path(logo.value(QStringLiteral("filePath")).toString());
    const auto variant = logo.value(QStringLiteral("variant")).toString();
    if (!path.isEmpty()) {
      logo_by_path.insert(path, logo);
      available_logo_variants.insert(variant);
    }
  }
  const auto logo_rules = kit.value(QStringLiteral("logoRules")).toObject();
  const auto logo_safe_area_percent =
      logo_rules.value(QStringLiteral("safeAreaPercent")).toDouble(10.0);
  const auto logo_minimum_width =
      logo_rules.value(QStringLiteral("minimumWidthPixels")).toDouble(96.0);
  const auto logo_minimum_height =
      logo_rules.value(QStringLiteral("minimumHeightPixels")).toDouble(32.0);
  const auto logo_minimum_contrast =
      logo_rules.value(QStringLiteral("minimumContrast")).toDouble(3.0);
  QVariantList issues;
  const auto append_issue = [this, &issues](
                                const QString& code,
                                const QString& discriminator,
                                int board_index,
                                const QString& item_id,
                                const QString& message,
                                const QString& details) {
    const auto issue_id = active_brand_lint_kit_id_ + QLatin1Char(':') + code + QLatin1Char(':') + discriminator;
    if (ignored_brand_lint_issue_ids_.contains(issue_id)) {
      return;
    }
    issues.push_back(QVariantMap{
        {QStringLiteral("issueId"), issue_id},
        {QStringLiteral("code"), code},
        {QStringLiteral("severity"), code == QStringLiteral("minimum-contrast") ||
                                           code == QStringLiteral("missing-logo") ||
                                           code.startsWith(QStringLiteral("logo-"))
                                           ? QStringLiteral("warning")
                                           : QStringLiteral("info")},
        {QStringLiteral("boardIndex"), board_index},
        {QStringLiteral("boardNumber"), board_index >= 0 ? board_index + 1 : 0},
        {QStringLiteral("itemId"), item_id},
        {QStringLiteral("canFocus"), board_index >= 0},
        {QStringLiteral("message"), message},
        {QStringLiteral("details"), details},
    });
  };
  QMap<QString, QString> role_style_baselines;
  QMap<QString, QString> role_style_labels;
  for (const auto& item : items_) {
    if (item.hidden) {
      continue;
    }
    const auto board_index = slideIndexForItem(item);
    const auto* slide = slideAt(board_index);
    if (slide == nullptr) {
      continue;
    }
    if (item.kind == ItemKind::Text) {
      const auto family = normalized_text_font_family(item.text_font_family);
      if (!approved_fonts.contains(family.toLower())) {
        append_issue(
            QStringLiteral("unapproved-font"), item.id, board_index, item.id,
            QStringLiteral("%1 uses unapproved font %2.")
                .arg(item.text_role.isEmpty() ? QStringLiteral("Text") : item.text_role, family),
            QStringLiteral("Approved faces: %1").arg(QStringList(approved_fonts.cbegin(), approved_fonts.cend()).join(QStringLiteral(", "))));
      }
      const auto color = normalized_color_value(item.text_color, QString{}).toLower();
      if (!color.isEmpty() && !approved_colors.contains(color)) {
        append_issue(
            QStringLiteral("unapproved-color"), item.id + QStringLiteral(":text"), board_index, item.id,
            QStringLiteral("%1 text uses unapproved color %2.").arg(item.text_role, color),
            QStringLiteral("Map it to a named brand color or explicitly ignore this exception."));
      }
      if (item.text_role == QStringLiteral("heading") || item.text_role == QStringLiteral("caption")) {
        const auto signature = QStringLiteral("%1|%2|%3|%4|%5")
                                   .arg(family, item.text_weight, color)
                                   .arg(item.text_point_size, 0, 'f', 2)
                                   .arg(item.text_italic);
        if (!role_style_baselines.contains(item.text_role)) {
          role_style_baselines.insert(item.text_role, signature);
          role_style_labels.insert(item.text_role, item.id);
        } else if (role_style_baselines.value(item.text_role) != signature) {
          append_issue(
              QStringLiteral("inconsistent-role-style"), item.id, board_index, item.id,
              QStringLiteral("%1 styling differs from the first %1 layer.").arg(item.text_role),
              QStringLiteral("Baseline layer: %1").arg(role_style_labels.value(item.text_role)));
        }
      }
      QColor surface;
      QString surface_description;
      if (item.text_background_opacity >= 0.98) {
        surface = QColor(item.text_background_color);
        surface_description = QStringLiteral("opaque text background");
      } else if (slide->background_kind == QStringLiteral("solid")) {
        surface = QColor(slide->background_color);
        surface_description = QStringLiteral("solid board background");
      }
      const QColor foreground(item.text_color);
      if (foreground.isValid() && surface.isValid()) {
        const auto ratio = contrast_ratio(foreground, surface);
        if (ratio < 4.5) {
          append_issue(
              QStringLiteral("minimum-contrast"), item.id, board_index, item.id,
              QStringLiteral("%1 contrast is %2:1, below the 4.5:1 brand minimum.")
                  .arg(item.text_role)
                  .arg(ratio, 0, 'f', 2),
              QStringLiteral("Measured against the %1.").arg(surface_description));
        }
      }
    } else if (item.kind == ItemKind::Shape) {
      const auto fill = normalized_color_value(item.fill_color, QString{}).toLower();
      if (!fill.isEmpty() && !approved_colors.contains(fill)) {
        append_issue(
            QStringLiteral("unapproved-color"), item.id + QStringLiteral(":fill"), board_index, item.id,
            QStringLiteral("Shape fill %1 is not in the approved palette.").arg(fill),
            QStringLiteral("Map it to a named brand color or explicitly ignore this exception."));
      }
      const auto stroke = normalized_color_value(item.stroke_color, QString{}).toLower();
      if (item.stroke_width > 0.0 && !stroke.isEmpty() && !approved_colors.contains(stroke)) {
        append_issue(
            QStringLiteral("unapproved-color"), item.id + QStringLiteral(":stroke"), board_index, item.id,
            QStringLiteral("Shape stroke %1 is not in the approved palette.").arg(stroke),
            QStringLiteral("Map it to a named brand color or explicitly ignore this exception."));
      }
    } else if (item.kind == ItemKind::Brush && !item.brush_eraser) {
      const auto color = normalized_color_value(item.brush_color, QString{}).toLower();
      if (!color.isEmpty() && !approved_colors.contains(color)) {
        append_issue(
            QStringLiteral("unapproved-color"), item.id + QStringLiteral(":brush"), board_index, item.id,
            QStringLiteral("Brush color %1 is not in the approved palette.").arg(color),
            QStringLiteral("Map it to a named brand color or explicitly ignore this exception."));
      }
    } else if (item.kind == ItemKind::Image &&
               logo_by_path.contains(normalized_path(item.file_path))) {
      const auto logo = logo_by_path.value(normalized_path(item.file_path));
      const auto variant = logo.value(QStringLiteral("variant")).toString();
      if (item.bounds.width() < logo_minimum_width ||
          item.bounds.height() < logo_minimum_height) {
        append_issue(
            QStringLiteral("logo-minimum-size"), item.id, board_index, item.id,
            QStringLiteral("%1 is %2 × %3 px, below the %4 × %5 px minimum.")
                .arg(logo.value(QStringLiteral("name")).toString(QStringLiteral("Logo")))
                .arg(item.bounds.width(), 0, 'f', 0)
                .arg(item.bounds.height(), 0, 'f', 0)
                .arg(logo_minimum_width, 0, 'f', 0)
                .arg(logo_minimum_height, 0, 'f', 0),
            QStringLiteral("Resize or explicitly ignore this placement; lint never changes artwork."));
      }
      const auto required_clear_space =
          qMin(item.bounds.width(), item.bounds.height()) *
          logo_safe_area_percent / 100.0;
      const auto clear_area = item.bounds.adjusted(
          -required_clear_space, -required_clear_space,
          required_clear_space, required_clear_space);
      bool clear_area_blocked = !slideRectInDocument(board_index).contains(clear_area);
      QString blocking_item_id;
      for (const auto& candidate : items_) {
        if (candidate.id == item.id || candidate.hidden ||
            slideIndexForItem(candidate) != board_index) {
          continue;
        }
        if (candidate.bounds.intersects(clear_area)) {
          clear_area_blocked = true;
          blocking_item_id = candidate.id;
          break;
        }
      }
      if (clear_area_blocked) {
        append_issue(
            QStringLiteral("logo-safe-area"), item.id, board_index, item.id,
            QStringLiteral("%1 does not retain its %2% clear space.")
                .arg(logo.value(QStringLiteral("name")).toString(QStringLiteral("Logo")))
                .arg(logo_safe_area_percent, 0, 'f', 0),
            blocking_item_id.isEmpty()
                ? QStringLiteral("The required clear area crosses the board edge; lint does not move it.")
                : QStringLiteral("The clear area intersects layer %1; lint does not move either layer.")
                      .arg(blocking_item_id));
      }
      const QColor board_background(slide->background_color);
      const auto dark_background = board_background.isValid() &&
                                   board_background.lightnessF() < 0.5;
      if ((variant == QStringLiteral("light") && !dark_background) ||
          (variant == QStringLiteral("dark") && dark_background)) {
        append_issue(
            QStringLiteral("logo-variant-background"), item.id, board_index, item.id,
            QStringLiteral("%1 is the %2 variant on a %3 surface.")
                .arg(logo.value(QStringLiteral("name")).toString(QStringLiteral("Logo")),
                     variant,
                     dark_background ? QStringLiteral("dark") : QStringLiteral("light")),
            QStringLiteral("Use the %1 variant or explicitly keep this exception; lint never swaps assets.")
                .arg(dark_background ? QStringLiteral("light") : QStringLiteral("dark")));
      }
      const auto sampled_logo_color = average_opaque_image_color(item.file_path);
      if (sampled_logo_color.isValid() && board_background.isValid()) {
        const auto ratio = contrast_ratio(sampled_logo_color, board_background);
        if (ratio < logo_minimum_contrast) {
          append_issue(
              QStringLiteral("logo-background-contrast"), item.id, board_index, item.id,
              QStringLiteral("%1 contrast is approximately %2:1, below the %3:1 logo minimum.")
                  .arg(logo.value(QStringLiteral("name")).toString(QStringLiteral("Logo")))
                  .arg(ratio, 0, 'f', 2)
                  .arg(logo_minimum_contrast, 0, 'f', 1),
              QStringLiteral("Estimated from opaque logo pixels against the solid board surface; lint never recolors the asset."));
        }
      }
    }
  }
  for (const auto& variant : {QStringLiteral("light"), QStringLiteral("dark"),
                              QStringLiteral("monochrome")}) {
    if (!available_logo_variants.contains(variant)) {
      append_issue(
          QStringLiteral("logo-variant-missing"), variant, -1, QString{},
          QStringLiteral("The brand kit has no %1 logo variant.").arg(variant),
          QStringLiteral("Add the variant in the Brand Kit editor; existing artwork remains unchanged."));
    }
  }
  for (const auto& value : kit.value(QStringLiteral("logoAssets")).toArray()) {
    const auto logo = value.toObject();
    if (!logo.value(QStringLiteral("required")).toBool()) {
      continue;
    }
    const auto required_path = normalized_path(logo.value(QStringLiteral("filePath")).toString());
    bool found = false;
    for (const auto& item : items_) {
      if (normalized_path(item.file_path) == required_path) {
        found = true;
        break;
      }
    }
    if (!found) {
      for (const auto& slide : slides_) {
        if (normalized_path(slide.primary.file_path) == required_path ||
            normalized_path(slide.secondary.file_path) == required_path ||
            normalized_path(slide.tertiary.file_path) == required_path) {
          found = true;
          break;
        }
      }
    }
    if (!found) {
      append_issue(
          QStringLiteral("missing-logo"), logo.value(QStringLiteral("assetId")).toString(), -1, QString{},
          QStringLiteral("Required logo '%1' is not placed in this carousel.")
              .arg(logo.value(QStringLiteral("name")).toString(QStringLiteral("Logo"))),
          required_path.isEmpty() ? QStringLiteral("The brand kit does not point to a logo file.")
                                   : QStringLiteral("Required asset: %1").arg(required_path));
    }
  }
  int warning_count = 0;
  for (const auto& value : issues) {
    if (value.toMap().value(QStringLiteral("severity")).toString() == QStringLiteral("warning")) {
      ++warning_count;
    }
  }
  return {
      {QStringLiteral("available"), true},
      {QStringLiteral("brandId"), active_brand_lint_kit_id_},
      {QStringLiteral("brandName"), kit.value(QStringLiteral("name")).toString()},
      {QStringLiteral("issues"), issues},
      {QStringLiteral("issueCount"), issues.size()},
      {QStringLiteral("warningCount"), warning_count},
      {QStringLiteral("ignoredCount"), ignored_brand_lint_issue_ids_.size()},
  };
}

QVariantMap CarouselDocumentController::layoutSettings() const { return layout_settings_; }

QVariantList CarouselDocumentController::layoutRecipes() const {
  QVariantList recipes;
  recipes.reserve(layout_recipes_.size());
  for (const auto& stored : layout_recipes_) {
    const auto settings = normalized_layout_settings(
        stored.value(QStringLiteral("layoutSettings")).toObject().toVariantMap());
    const auto board = stored.value(QStringLiteral("boardTokens")).toObject();
    recipes.push_back(QVariantMap{
        {QStringLiteral("recipeId"), stored.value(QStringLiteral("recipeId")).toString()},
        {QStringLiteral("name"), stored.value(QStringLiteral("name")).toString()},
        {QStringLiteral("columns"), board.value(QStringLiteral("columns")).toInt(4)},
        {QStringLiteral("rows"), board.value(QStringLiteral("rows")).toInt(4)},
        {QStringLiteral("marginX"), board.value(QStringLiteral("marginX")).toDouble(72.0)},
        {QStringLiteral("marginY"), board.value(QStringLiteral("marginY")).toDouble(72.0)},
        {QStringLiteral("gutterX"), board.value(QStringLiteral("gutterX")).toDouble(24.0)},
        {QStringLiteral("gutterY"), board.value(QStringLiteral("gutterY")).toDouble(24.0)},
        {QStringLiteral("guideCount"), settings.value(QStringLiteral("customGuides")).toList().size()},
        {QStringLiteral("safePreset"), settings.value(QStringLiteral("safePreset")).toString()},
        {QStringLiteral("gridEnabled"), settings.value(QStringLiteral("gridEnabled")).toBool()},
        {QStringLiteral("createdAt"), stored.value(QStringLiteral("createdAt")).toString()},
    });
  }
  return recipes;
}

