QString CarouselDocumentController::documentContentHash() const {
  auto canonical_object = persistentDocumentObject();
  migrate_carousel_document(&canonical_object);

  QJsonArray canonical_slides;
  for (const auto& value : canonical_object.value(QStringLiteral("slides")).toArray()) {
    if (!value.isObject()) {
      continue;
    }
    const auto source = value.toObject();
    canonical_slides.push_back(
        merge_preserving_unknown_fields(source, slideObject(slideFromObject(source))));
  }
  canonical_object.insert(QStringLiteral("slides"), canonical_slides);

  QJsonArray canonical_groups;
  for (const auto& value : canonical_object.value(QStringLiteral("groups")).toArray()) {
    if (!value.isObject()) {
      continue;
    }
    const auto source = value.toObject();
    canonical_groups.push_back(
        merge_preserving_unknown_fields(source, groupObject(groupFromObject(source))));
  }
  canonical_object.insert(QStringLiteral("groups"), canonical_groups);

  QJsonArray canonical_items;
  for (const auto& value : canonical_object.value(QStringLiteral("items")).toArray()) {
    if (!value.isObject()) {
      continue;
    }
    const auto source = value.toObject();
    canonical_items.push_back(
        merge_preserving_unknown_fields(source, itemObject(itemFromObject(source))));
  }
  canonical_object.insert(QStringLiteral("items"), canonical_items);
  canonical_object.insert(
      QStringLiteral("layoutSettings"),
      QJsonObject::fromVariantMap(normalized_layout_settings(
          canonical_object.value(QStringLiteral("layoutSettings")).toObject().toVariantMap())));
  canonical_object.remove(QStringLiteral("currentIndex"));
  canonical_object.remove(QStringLiteral("activeSlot"));
  canonical_object.remove(QStringLiteral("selectedItemId"));
  canonical_object.remove(QStringLiteral("selectedItemIds"));

  const auto canonical = QJsonDocument(canonical_object).toJson(QJsonDocument::Compact);
  return QString::fromLatin1(QCryptographicHash::hash(canonical, QCryptographicHash::Sha256).toHex());
}

