QVariantMap CarouselDocumentController::mediaUsageReport(
    const QVariantList& candidate_paths) const {
  struct Usage final {
    QString path;
    QString label;
    QString media_type;
    bool offline = false;
    int placement_count = 0;
    QSet<int> board_indexes;
    QHash<QString, int> crop_counts;
    QVariantList placements;
  };

  QHash<QString, Usage> usage_by_path;
  auto append_usage = [&usage_by_path](
                          const QString& raw_path,
                          const QString& label,
                          const QString& media_type,
                          int board_index,
                          const QString& target_kind,
                          const QString& slot,
                          const QString& item_id,
                          const QString& crop_signature) {
    const auto path = normalized_path(raw_path);
    if (path.isEmpty()) {
      return;
    }
    auto& usage = usage_by_path[path];
    usage.path = path;
    if (usage.label.isEmpty()) {
      usage.label = label.trimmed().isEmpty() ? QFileInfo(path).completeBaseName() : label.trimmed();
    }
    if (usage.media_type.isEmpty()) {
      usage.media_type = media_type;
    }
    usage.offline = !QFileInfo::exists(path);
    ++usage.placement_count;
    if (board_index >= 0) {
      usage.board_indexes.insert(board_index);
    }
    ++usage.crop_counts[crop_signature];
    usage.placements.push_back(QVariantMap{
        {QStringLiteral("boardIndex"), board_index},
        {QStringLiteral("boardNumber"), board_index + 1},
        {QStringLiteral("targetKind"), target_kind},
        {QStringLiteral("slot"), slot},
        {QStringLiteral("itemId"), item_id},
        {QStringLiteral("cropSignature"), crop_signature},
    });
  };
  auto media_crop_signature = [](const MediaItem& media) {
    return QStringLiteral("%1|%2|%3|%4|%5|%6|%7|%8")
        .arg(media.fit_mode == FitMode::Contain ? QStringLiteral("contain") : QStringLiteral("cover"))
        .arg(media.scale, 0, 'f', 6)
        .arg(media.offset_x, 0, 'f', 6)
        .arg(media.offset_y, 0, 'f', 6)
        .arg(media.focal_x, 0, 'f', 6)
        .arg(media.focal_y, 0, 'f', 6)
        .arg(media.manual_crop ? QStringLiteral("manual") : QStringLiteral("smart"))
        .arg(media.crop_source);
  };
  auto item_crop_signature = [](const CanvasItem& item) {
    return QStringLiteral("%1|%2|%3|%4|%5|%6|%7|%8")
        .arg(item.fit_mode == FitMode::Contain ? QStringLiteral("contain") : QStringLiteral("cover"))
        .arg(item.media_scale, 0, 'f', 6)
        .arg(item.media_offset_x, 0, 'f', 6)
        .arg(item.media_offset_y, 0, 'f', 6)
        .arg(item.media_focal_x, 0, 'f', 6)
        .arg(item.media_focal_y, 0, 'f', 6)
        .arg(item.media_manual_crop ? QStringLiteral("manual") : QStringLiteral("smart"))
        .arg(item.media_crop_source);
  };
  auto media_type_name = [](MediaType type) {
    return type == MediaType::Video ? QStringLiteral("video") : QStringLiteral("image");
  };

  QSet<QString> visited_groups;
  for (int board_index = 0; board_index < slides_.size(); ++board_index) {
    const auto* slide = slideAt(board_index);
    if (slide == nullptr) {
      continue;
    }
    if (const auto* group = groupForIndex(board_index); group != nullptr) {
      if (visited_groups.contains(group->id) || group->media.type == MediaType::Empty) {
        continue;
      }
      visited_groups.insert(group->id);
      for (int group_board = group->start_index;
           group_board < qMin(slides_.size(), group->start_index + group->span);
           ++group_board) {
        append_usage(
            group->media.file_path,
            group->media.display_label,
            media_type_name(group->media.type),
            group_board,
            QStringLiteral("group"),
            QStringLiteral("linked"),
            QString{},
            media_crop_signature(group->media));
      }
      continue;
    }
    auto append_slot = [&](const MediaItem& media, const QString& slot) {
      if (media.type == MediaType::Empty) {
        return;
      }
      append_usage(
          media.file_path,
          media.display_label,
          media_type_name(media.type),
          board_index,
          QStringLiteral("slot"),
          slot,
          QString{},
          media_crop_signature(media));
    };
    append_slot(slide->primary, QStringLiteral("primary"));
    append_slot(slide->secondary, QStringLiteral("secondary"));
    append_slot(slide->tertiary, QStringLiteral("tertiary"));
  }
  for (const auto& item : items_) {
    if ((item.kind != ItemKind::Image && item.kind != ItemKind::Video) ||
        item.file_path.trimmed().isEmpty()) {
      continue;
    }
    append_usage(
        item.file_path,
        item.display_label,
        item.kind == ItemKind::Video ? QStringLiteral("video") : QStringLiteral("image"),
        slideIndexForItem(item),
        QStringLiteral("item"),
        QString{},
        item.id,
        item_crop_signature(item));
  }

  auto ordered_paths = usage_by_path.keys();
  std::sort(ordered_paths.begin(), ordered_paths.end(), [&usage_by_path](const QString& lhs, const QString& rhs) {
    const auto left_label = usage_by_path.value(lhs).label.toCaseFolded();
    const auto right_label = usage_by_path.value(rhs).label.toCaseFolded();
    return left_label == right_label ? lhs < rhs : left_label < right_label;
  });

  QVariantList entries;
  int placement_count = 0;
  int duplicate_source_count = 0;
  int offline_source_count = 0;
  int reused_crop_source_count = 0;
  for (const auto& path : ordered_paths) {
    const auto& usage = usage_by_path[path];
    placement_count += usage.placement_count;
    if (usage.placement_count > 1) {
      ++duplicate_source_count;
    }
    if (usage.offline) {
      ++offline_source_count;
    }
    int reused_crop_count = 0;
    for (auto iterator = usage.crop_counts.cbegin(); iterator != usage.crop_counts.cend(); ++iterator) {
      reused_crop_count += qMax(0, iterator.value() - 1);
    }
    if (reused_crop_count > 0) {
      ++reused_crop_source_count;
    }
    auto board_indexes = usage.board_indexes.values();
    std::sort(board_indexes.begin(), board_indexes.end());
    QVariantList board_index_values;
    QVariantList board_number_values;
    QStringList board_number_labels;
    for (const auto board_index : board_indexes) {
      board_index_values.push_back(board_index);
      board_number_values.push_back(board_index + 1);
      board_number_labels.push_back(QString::number(board_index + 1));
    }
    entries.push_back(QVariantMap{
        {QStringLiteral("sourcePath"), usage.path},
        {QStringLiteral("displayLabel"), usage.label},
        {QStringLiteral("mediaType"), usage.media_type},
        {QStringLiteral("offline"), usage.offline},
        {QStringLiteral("placementCount"), usage.placement_count},
        {QStringLiteral("duplicate"), usage.placement_count > 1},
        {QStringLiteral("boardIndexes"), board_index_values},
        {QStringLiteral("boardNumbers"), board_number_values},
        {QStringLiteral("boardNumbersLabel"), board_number_labels.join(QStringLiteral(", "))},
        {QStringLiteral("cropVariantCount"), usage.crop_counts.size()},
        {QStringLiteral("reusedCropCount"), reused_crop_count},
        {QStringLiteral("hasReusedCrop"), reused_crop_count > 0},
        {QStringLiteral("placements"), usage.placements},
    });
  }

  QVariantList candidates = candidate_paths;
  if (candidates.isEmpty()) {
    candidates = media_autofill_plan_;
  }
  QVariantList unused_selections;
  QSet<QString> visited_candidates;
  for (const auto& value : candidates) {
    const auto candidate = value.toMap();
    const auto raw_path = candidate.isEmpty() ? value.toString()
                                               : candidate.value(QStringLiteral("filePath")).toString();
    const auto path = normalized_path(raw_path);
    if (path.isEmpty() || visited_candidates.contains(path) || usage_by_path.contains(path)) {
      continue;
    }
    visited_candidates.insert(path);
    const bool has_mapping = !candidate.isEmpty() && candidate.contains(QStringLiteral("boardIndex"));
    const auto board_index = candidate.value(QStringLiteral("boardIndex"), -1).toInt();
    const auto skipped = candidate.value(QStringLiteral("skipped")).toBool();
    unused_selections.push_back(QVariantMap{
        {QStringLiteral("sourcePath"), path},
        {QStringLiteral("displayLabel"),
         candidate.value(QStringLiteral("displayLabel"), QFileInfo(path).completeBaseName()).toString()},
        {QStringLiteral("offline"), !QFileInfo::exists(path)},
        {QStringLiteral("reason"),
         has_mapping && board_index < 0
             ? QStringLiteral("No open target")
             : skipped ? QStringLiteral("Skipped before autofill")
                       : QStringLiteral("Not used in document")},
    });
  }

  return QVariantMap{
      {QStringLiteral("sourceCount"), entries.size()},
      {QStringLiteral("placementCount"), placement_count},
      {QStringLiteral("duplicateSourceCount"), duplicate_source_count},
      {QStringLiteral("offlineSourceCount"), offline_source_count},
      {QStringLiteral("reusedCropSourceCount"), reused_crop_source_count},
      {QStringLiteral("unusedSelectionCount"), unused_selections.size()},
      {QStringLiteral("entries"), entries},
      {QStringLiteral("unusedSelections"), unused_selections},
  };
}

void CarouselDocumentController::focusMediaUsagePlacement(
    int board_index,
    const QString& item_id,
    const QString& slot) {
  const auto normalized_item_id = item_id.trimmed();
  if (!normalized_item_id.isEmpty()) {
    selectItem(normalized_item_id);
    return;
  }
  selectSlide(board_index);
  setActiveSlot(slot == QStringLiteral("secondary") || slot == QStringLiteral("tertiary")
                    ? slot
                    : QStringLiteral("primary"));
}

