void CarouselDocumentController::setSelectedSlidesRole(const QString& board_role) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto normalized = normalized_board_role(board_role);
  QVector<int> targets;
  for (const auto index : selected_slide_indices_) {
    if (index >= 0 && index < slides_.size() && !targets.contains(index)) {
      targets.push_back(index);
    }
  }
  if (targets.isEmpty()) {
    targets.push_back(current_index_);
  }
  bool changed = false;
  for (const auto index : targets) {
    changed = changed || slides_.at(index).board_role != normalized;
  }
  if (!changed) {
    return;
  }
  pushUndoState(QStringLiteral("Assign board roles"));
  for (const auto index : targets) {
    slides_[index].board_role = normalized;
  }
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Set %1 selected board role%2 to %3.")
                .arg(targets.size())
                .arg(targets.size() == 1 ? QString{} : QStringLiteral("s"))
                .arg(normalized));
}

