void CarouselDocumentController::setSelectedTextPointSize(double point_size) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto* item = currentItem();
  if (item == nullptr || item->kind != ItemKind::Text || item->locked) {
    return;
  }

  pushUndoState(QStringLiteral("Resize text"), true);
  const auto normalized = qBound(kMinTextPointSize, point_size, 400.0);
  if (item->text_fit_mode == QStringLiteral("auto")) {
    item->text_fit_max_point_size = normalized;
    item->text_fit_min_point_size = qMin(item->text_fit_min_point_size, normalized);
  } else {
    item->text_point_size = normalized;
  }
  updateTextFit(item);
  emitCanvasStateChanged(false);
}

void CarouselDocumentController::setSelectedTextFitSettings(
    const QString& mode,
    double minimum_point_size,
    double maximum_point_size) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto* item = currentItem();
  if (item == nullptr || item->kind != ItemKind::Text || item->locked) {
    return;
  }
  const auto requested_mode = mode.trimmed().toLower();
  const auto normalized_mode = requested_mode == QStringLiteral("auto") ||
                                       requested_mode == QStringLiteral("fixed")
                                   ? requested_mode
                                   : QStringLiteral("content");
  const auto normalized_minimum = qBound(kMinTextPointSize, minimum_point_size, 400.0);
  const auto normalized_maximum =
      qBound(normalized_minimum, maximum_point_size, 400.0);
  if (item->text_fit_mode == normalized_mode &&
      qFuzzyCompare(item->text_fit_min_point_size, normalized_minimum) &&
      qFuzzyCompare(item->text_fit_max_point_size, normalized_maximum)) {
    return;
  }
  pushUndoState(QStringLiteral("Change text fitting"), true);
  item->text_fit_mode = normalized_mode;
  item->text_fit_min_point_size = normalized_minimum;
  item->text_fit_max_point_size = normalized_maximum;
  if (normalized_mode == QStringLiteral("fixed")) {
    item->text_point_size = normalized_maximum;
  }
  updateTextFit(item);
  emitCanvasStateChanged(false);
  setStatus(textFitState(*item));
}

