bool CarouselDocumentController::applyFontFamilyFromBrowser(const QString& font_family) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  auto* item = currentItem();
  if (item == nullptr || item->kind != ItemKind::Text || item->locked) {
    return false;
  }
  const auto normalized = normalized_text_font_family(font_family);
  if (!text_font_family_available(normalized, QFontDatabase::families())) {
    setStatus(QStringLiteral("Choose an installed font or preview an explicit fallback."));
    return false;
  }
  if (!text_font_family_available(item->text_font_family, QFontDatabase::families())) {
    setStatus(QStringLiteral("Preview the missing-font fallback before applying it."));
    return false;
  }
  setSelectedTextFontFamily(normalized);
  for (qsizetype index = recent_font_families_.size(); index > 0; --index) {
    if (recent_font_families_.at(index - 1).compare(normalized, Qt::CaseInsensitive) == 0) {
      recent_font_families_.removeAt(index - 1);
    }
  }
  recent_font_families_.prepend(normalized);
  while (recent_font_families_.size() > 12) {
    recent_font_families_.removeLast();
  }
  saveDesignLibrary();
  emit fontLibraryChanged();
  return true;
}

void CarouselDocumentController::toggleFavoriteFontFamily(const QString& font_family) {
  const auto normalized = normalized_text_font_family(font_family);
  if (!text_font_family_available(normalized, QFontDatabase::families())) {
    return;
  }
  for (qsizetype index = favorite_font_families_.size(); index > 0; --index) {
    if (favorite_font_families_.at(index - 1).compare(normalized, Qt::CaseInsensitive) == 0) {
      favorite_font_families_.removeAt(index - 1);
      saveDesignLibrary();
      emit fontLibraryChanged();
      return;
    }
  }
  favorite_font_families_.push_back(normalized);
  favorite_font_families_.sort(Qt::CaseInsensitive);
  saveDesignLibrary();
  emit fontLibraryChanged();
}

void CarouselDocumentController::setCopyProofLanguage(const QString& language) {
  const auto normalized = language == QStringLiteral("en-GB") ? QStringLiteral("en-GB")
                                                               : QStringLiteral("en-US");
  if (copy_proof_language_ == normalized) {
    return;
  }
  pushUndoState(QStringLiteral("Change proofing language"));
  copy_proof_language_ = normalized;
  copy_proof_current_issue_id_.clear();
  updateDocumentDirty();
  emit copyProofChanged();
  setStatus(QStringLiteral("Proofing copy with %1 spelling.").arg(normalized));
}

void CarouselDocumentController::nextCopyProofIssue() {
  const auto issues = copyProofIssues();
  if (issues.isEmpty()) {
    copy_proof_current_issue_id_.clear();
    emit copyProofChanged();
    setStatus(QStringLiteral("No copy proof issues remain."));
    return;
  }
  int current = -1;
  for (int index = 0; index < issues.size(); ++index) {
    if (issues.at(index).toMap().value(QStringLiteral("issueId")).toString() ==
        copy_proof_current_issue_id_) {
      current = index;
      break;
    }
  }
  const auto issue = issues.at((current + 1) % issues.size()).toMap();
  copy_proof_current_issue_id_ = issue.value(QStringLiteral("issueId")).toString();
  focusPreflightIssue(
      issue.value(QStringLiteral("boardIndex")).toInt(),
      issue.value(QStringLiteral("itemId")).toString());
  emit copyProofChanged();
  setStatus(QStringLiteral("Copy proof: %1").arg(issue.value(QStringLiteral("message")).toString()));
}

void CarouselDocumentController::ignoreCopyProofIssue(const QString& issue_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto normalized = issue_id;
  if (normalized.trimmed().isEmpty() || ignored_copy_proof_issue_ids_.contains(normalized)) {
    return;
  }
  bool exists = false;
  for (const auto& value : copyProofIssues()) {
    if (value.toMap().value(QStringLiteral("issueId")).toString() == normalized) {
      exists = true;
      break;
    }
  }
  if (!exists) {
    return;
  }
  pushUndoState(QStringLiteral("Ignore copy proof issue"));
  ignored_copy_proof_issue_ids_.push_back(normalized);
  if (copy_proof_current_issue_id_ == normalized) {
    copy_proof_current_issue_id_.clear();
  }
  updateDocumentDirty();
  emit copyProofChanged();
  setStatus(QStringLiteral("Ignored that copy proof issue without changing authored text."));
}

void CarouselDocumentController::addCopyProofWord(const QString& word) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto normalized = word.trimmed().toLower();
  static const QRegularExpression word_pattern(QStringLiteral("^[a-z][a-z']+$"));
  if (!word_pattern.match(normalized).hasMatch() ||
      custom_dictionary_words_.contains(normalized, Qt::CaseInsensitive)) {
    return;
  }
  custom_dictionary_words_.push_back(normalized);
  custom_dictionary_words_.sort(Qt::CaseInsensitive);
  saveDesignLibrary();
  copy_proof_current_issue_id_.clear();
  emit copyProofChanged();
  setStatus(QStringLiteral("Added “%1” to the Carousel proofing dictionary.").arg(normalized));
}

