void CarouselDocumentController::nudgeSelectedItemMediaByPixels(double delta_x, double delta_y) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto* item = currentItem();
  if (item == nullptr || (item->kind != ItemKind::Image && item->kind != ItemKind::Video) ||
      item->locked || !item->source_size.isValid()) {
    return;
  }
  const auto base_scale = item->fit_mode == FitMode::Contain
                              ? qMin(item->bounds.width() / item->source_size.width(),
                                     item->bounds.height() / item->source_size.height())
                              : qMax(item->bounds.width() / item->source_size.width(),
                                     item->bounds.height() / item->source_size.height());
  const auto draw_width = qMax(1.0, item->source_size.width() * base_scale * item->media_scale);
  const auto draw_height = qMax(1.0, item->source_size.height() * base_scale * item->media_scale);
  const auto free_x = item->bounds.width() - draw_width;
  const auto free_y = item->bounds.height() - draw_height;
  const auto update_axis = [](double offset, double free_space, double delta) {
    if (qAbs(free_space) <= 0.001) {
      return 0.0;
    }
    const auto minimum_position = qMin(0.0, free_space);
    const auto maximum_position = qMax(0.0, free_space);
    const auto current_position = free_space * ((offset + 1.0) / 2.0);
    const auto next_position = qBound(
        minimum_position, current_position + delta, maximum_position);
    return clamp_unit_interval(((next_position / free_space) * 2.0) - 1.0);
  };
  const auto next_x = update_axis(item->media_offset_x, free_x, delta_x);
  const auto next_y = update_axis(item->media_offset_y, free_y, delta_y);
  if (qFuzzyCompare(item->media_offset_x, next_x) &&
      qFuzzyCompare(item->media_offset_y, next_y) && item->media_manual_crop) {
    return;
  }
  pushUndoState(QStringLiteral("Nudge media crop"), true);
  item->media_offset_x = next_x;
  item->media_offset_y = next_y;
  item->media_manual_crop = true;
  emitCanvasStateChanged(true);
}

bool CarouselDocumentController::selectAdjacentMediaItem(int direction) {
  QVector<int> media_indexes;
  media_indexes.reserve(items_.size());
  for (int index = 0; index < items_.size(); ++index) {
    const auto& item = items_.at(index);
    if (!item.hidden && (item.kind == ItemKind::Image || item.kind == ItemKind::Video)) {
      media_indexes.push_back(index);
    }
  }
  if (media_indexes.isEmpty()) {
    return false;
  }
  std::stable_sort(media_indexes.begin(), media_indexes.end(), [this](int left, int right) {
    const auto left_board = slideIndexForItem(items_.at(left));
    const auto right_board = slideIndexForItem(items_.at(right));
    if (left_board != right_board) {
      return left_board < right_board;
    }
    return left < right;
  });
  int position = -1;
  for (int index = 0; index < media_indexes.size(); ++index) {
    if (items_.at(media_indexes.at(index)).id == selected_item_id_) {
      position = index;
      break;
    }
  }
  const auto step = direction < 0 ? -1 : 1;
  const auto next_position = position < 0
                                 ? (step < 0 ? media_indexes.size() - 1 : 0)
                                 : (position + step + media_indexes.size()) % media_indexes.size();
  selectItem(items_.at(media_indexes.at(next_position)).id);
  setStatus(QStringLiteral("Selected %1 media layer of %2.")
                .arg(next_position + 1)
                .arg(media_indexes.size()));
  return true;
}

