void CarouselDocumentController::resetSelectedItemMediaCrop() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto indexes = selectedItemIndexes(false, true);
  if (indexes.isEmpty()) {
    return;
  }

  pushUndoState(QStringLiteral("Reset media crop"));
  bool changed = false;
  for (const auto index : indexes) {
    auto& item = items_[index];
    if (item.kind != ItemKind::Image && item.kind != ItemKind::Video) {
      continue;
    }
    if (qFuzzyCompare(item.media_scale, 1.0) && qFuzzyCompare(item.media_offset_x, 0.0) &&
        qFuzzyCompare(item.media_offset_y, 0.0) && !item.media_manual_crop) {
      continue;
    }
    item.media_scale = 1.0;
    item.media_offset_x = 0.0;
    item.media_offset_y = 0.0;
    item.media_manual_crop = false;
    changed = true;
  }
  if (changed) {
    emitCanvasStateChanged(true);
  }
}

bool CarouselDocumentController::applyPhotoFramePreset(const QString& preset_id) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized = preset_id.trimmed().toLower();
  static const QSet<QString> presets = {
      QStringLiteral("bordered-print"),
      QStringLiteral("rounded-card"),
      QStringLiteral("instant-photo"),
      QStringLiteral("contact-sheet"),
      QStringLiteral("browser-device"),
      QStringLiteral("editorial-mount"),
  };
  const auto photo_index = indexOfItem(selected_item_id_);
  if (!presets.contains(normalized) || photo_index < 0 ||
      items_.at(photo_index).kind != ItemKind::Image || items_.at(photo_index).locked) {
    return false;
  }

  pushUndoState(QStringLiteral("Apply photo frame component"));
  const auto photo_id = items_.at(photo_index).id;
  const auto photo_bounds = items_.at(photo_index).bounds;
  const auto photo_label = summary_label(items_.at(photo_index));
  const auto group_id = QUuid::createUuid().toString(QUuid::WithoutBraces);

  CanvasItem mount;
  mount.id = QUuid::createUuid().toString(QUuid::WithoutBraces);
  mount.object_group_id = group_id;
  mount.kind = ItemKind::Shape;
  mount.shape_kind = QStringLiteral("rectangle");
  mount.display_label = QStringLiteral("%1 mount").arg(normalized);
  mount.fill_color = QStringLiteral("#fffdf8");
  mount.stroke_color = QStringLiteral("#d8cec2");
  mount.stroke_width = 2.0;
  mount.bounds = photo_bounds.adjusted(-28.0, -28.0, 28.0, 28.0);

  QString caption;
  QRectF caption_bounds;
  if (normalized == QStringLiteral("bordered-print")) {
    mount.stroke_color = QStringLiteral("#1e1a17");
    mount.stroke_width = 3.0;
  } else if (normalized == QStringLiteral("rounded-card")) {
    mount.corner_radius = 44.0;
    mount.shadow_opacity = 0.28;
    mount.shadow_offset_x = 18.0;
    mount.shadow_offset_y = 24.0;
  } else if (normalized == QStringLiteral("instant-photo")) {
    mount.bounds = photo_bounds.adjusted(-30.0, -30.0, 30.0, 126.0);
    caption = photo_label;
    caption_bounds = QRectF(
        mount.bounds.left() + 24.0, photo_bounds.bottom() + 20.0,
        mount.bounds.width() - 48.0, 72.0);
  } else if (normalized == QStringLiteral("contact-sheet")) {
    mount.fill_color = QStringLiteral("#121212");
    mount.stroke_color = QStringLiteral("#f5f0e8");
    mount.bounds = photo_bounds.adjusted(-18.0, -18.0, 18.0, 58.0);
    caption = QStringLiteral("01  %1").arg(photo_label);
    caption_bounds = QRectF(
        mount.bounds.left() + 16.0, photo_bounds.bottom() + 8.0,
        mount.bounds.width() - 32.0, 36.0);
  } else if (normalized == QStringLiteral("browser-device")) {
    mount.fill_color = QStringLiteral("#eef1f3");
    mount.stroke_color = QStringLiteral("#59646c");
    mount.stroke_width = 4.0;
    mount.corner_radius = 24.0;
    mount.bounds = photo_bounds.adjusted(-18.0, -74.0, 18.0, 18.0);
    caption = QStringLiteral("●  ●  ●     %1").arg(photo_label);
    caption_bounds = QRectF(
        mount.bounds.left() + 18.0, mount.bounds.top() + 12.0,
        mount.bounds.width() - 36.0, 44.0);
  } else {
    mount.fill_color = QStringLiteral("#f3eee5");
    mount.stroke_color = QStringLiteral("#c9bbaa");
    mount.bounds = photo_bounds.adjusted(-48.0, -48.0, 48.0, 118.0);
    caption = QStringLiteral("%1 · EDITORIAL CREDIT").arg(photo_label.toUpper());
    caption_bounds = QRectF(
        mount.bounds.left() + 28.0, photo_bounds.bottom() + 22.0,
        mount.bounds.width() - 56.0, 54.0);
  }

  items_.insert(photo_index, mount);
  auto& photo = items_[photo_index + 1];
  photo.object_group_id = group_id;
  if (normalized == QStringLiteral("bordered-print")) {
    photo.frame_color = QStringLiteral("#ffffff");
    photo.frame_width = 12.0;
  } else if (normalized == QStringLiteral("rounded-card") ||
             normalized == QStringLiteral("browser-device")) {
    photo.corner_radius = normalized == QStringLiteral("rounded-card") ? 32.0 : 14.0;
  } else if (normalized == QStringLiteral("contact-sheet")) {
    photo.frame_color = QStringLiteral("#f5f0e8");
    photo.frame_width = 6.0;
  }

  QStringList selected_ids{mount.id, photo_id};
  if (!caption.isEmpty()) {
    CanvasItem label;
    label.id = QUuid::createUuid().toString(QUuid::WithoutBraces);
    label.object_group_id = group_id;
    label.kind = ItemKind::Text;
    label.text = caption;
    label.display_label = caption.left(24);
    label.text_role = QStringLiteral("caption");
    label.text_style_id = QStringLiteral("caption");
    label.text_font_family = normalized == QStringLiteral("instant-photo")
                                 ? QStringLiteral("serif")
                                 : QStringLiteral("mono");
    label.text_point_size = normalized == QStringLiteral("instant-photo") ? 30.0 : 24.0;
    label.text_weight = normalized == QStringLiteral("instant-photo")
                            ? QStringLiteral("normal")
                            : QStringLiteral("bold");
    label.text_horizontal_alignment = QStringLiteral("left");
    label.text_vertical_alignment = QStringLiteral("middle");
    label.text_color = normalized == QStringLiteral("contact-sheet")
                           ? QStringLiteral("#f5f0e8")
                           : QStringLiteral("#1e1a17");
    label.bounds = caption_bounds;
    items_.push_back(label);
    selected_ids.push_back(label.id);
  }
  setSelectedItemIds(selected_ids, photo_id);
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Applied editable %1 photo frame component.").arg(normalized));
  return true;
}

void CarouselDocumentController::setSelectedShapeKind(const QString& shape_kind) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto* item = currentItem();
  if (item == nullptr || item->kind != ItemKind::Shape || item->locked) {
    return;
  }

  const auto normalized = normalized_shape_kind(shape_kind);
  if (item->shape_kind == normalized) {
    return;
  }
  pushUndoState(QStringLiteral("Change shape"));
  item->shape_kind = normalized;
  item->display_label = normalized == QStringLiteral("ellipse") ? QStringLiteral("Ellipse")
                      : normalized == QStringLiteral("line")    ? QStringLiteral("Line")
                      : normalized == QStringLiteral("arrow")   ? QStringLiteral("Arrow")
                      : normalized == QStringLiteral("triangle") ? QStringLiteral("Triangle")
                      : normalized == QStringLiteral("diamond") ? QStringLiteral("Diamond")
                      : normalized == QStringLiteral("star") ? QStringLiteral("Star")
                      : normalized == QStringLiteral("hexagon") ? QStringLiteral("Hexagon")
                                                                : QStringLiteral("Rectangle");
  emitCanvasStateChanged(true);
}

