void CarouselDocumentController::setSelectedBrushColor(const QString& color_value) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto* item = currentItem();
  if (item == nullptr || item->kind != ItemKind::Brush || item->locked || item->brush_eraser) {
    return;
  }
  const auto normalized = normalized_color_value(color_value, item->brush_color);
  if (item->brush_color == normalized && item->brand_color_kit_id.isEmpty()) {
    return;
  }
  pushUndoState(QStringLiteral("Change brush color"));
  item->brush_color = normalized;
  item->brand_color_kit_id.clear();
  item->brand_color_token_id.clear();
  emitCanvasStateChanged(true);
}

void CarouselDocumentController::setSelectedBrushWidth(double width) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto* item = currentItem();
  if (item == nullptr || item->kind != ItemKind::Brush || item->locked) {
    return;
  }
  const auto normalized = qBound(1.0, width, 320.0);
  if (qFuzzyCompare(item->brush_width, normalized)) {
    return;
  }
  pushUndoState(QStringLiteral("Change brush width"), true);
  item->brush_width = normalized;
  emitCanvasStateChanged(true);
}

