void CarouselDocumentController::setCurrentMediaCropMode(const QString& crop_mode) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const bool use_manual = crop_mode.trimmed().toLower() == QStringLiteral("manual");
  if (auto* item = currentItem(); item != nullptr &&
      (item->kind == ItemKind::Image || item->kind == ItemKind::Video)) {
    if (item->media_manual_crop == use_manual) {
      return;
    }
    pushUndoState(QStringLiteral("Change media crop mode"));
    if (use_manual && item->source_size.isValid()) {
      const auto base_scale = item->fit_mode == FitMode::Contain
                                  ? qMin(item->bounds.width() / item->source_size.width(),
                                         item->bounds.height() / item->source_size.height())
                                  : qMax(item->bounds.width() / item->source_size.width(),
                                         item->bounds.height() / item->source_size.height());
      const auto draw_width = item->source_size.width() * base_scale * item->media_scale;
      const auto draw_height = item->source_size.height() * base_scale * item->media_scale;
      item->media_offset_x = smart_crop_offset(item->media_focal_x, item->bounds.width(), draw_width);
      item->media_offset_y = smart_crop_offset(item->media_focal_y, item->bounds.height(), draw_height);
    }
    item->media_manual_crop = use_manual;
    refreshCurrentSelectionPreviews();
    emitCanvasStateChanged(true);
    return;
  }
  auto* media = currentEditableMedia();
  if (media == nullptr || media->manual_crop == use_manual) {
    return;
  }
  pushUndoState(QStringLiteral("Change media crop mode"));
  if (use_manual) {
    const auto viewport = currentMediaViewportSize();
    const auto source = effectiveMediaSourceSize(*media);
    if (viewport.isValid() && source.isValid()) {
      const auto base_scale = media->fit_mode == FitMode::Contain
                                  ? qMin(static_cast<double>(viewport.width()) / source.width(),
                                         static_cast<double>(viewport.height()) / source.height())
                                  : qMax(static_cast<double>(viewport.width()) / source.width(),
                                         static_cast<double>(viewport.height()) / source.height());
      const auto draw_width = static_cast<double>(source.width()) * base_scale * media->scale;
      const auto draw_height = static_cast<double>(source.height()) * base_scale * media->scale;
      media->offset_x = smart_crop_offset(media->focal_x, viewport.width(), draw_width);
      media->offset_y = smart_crop_offset(media->focal_y, viewport.height(), draw_height);
    }
  }
  media->manual_crop = use_manual;
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
}

void CarouselDocumentController::setCurrentMediaCropSource(const QString& crop_source) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto requested = crop_source.trimmed().toLower();
  const auto normalized = requested == QStringLiteral("original") ||
                                  requested == QStringLiteral("carousel")
                              ? requested
                              : QStringLiteral("edit");
  if (auto* item = currentItem(); item != nullptr &&
      (item->kind == ItemKind::Image || item->kind == ItemKind::Video)) {
    if (item->media_crop_source == normalized) {
      return;
    }
    pushUndoState(QStringLiteral("Change crop ownership"));
    item->media_crop_source = normalized;
    if (normalized == QStringLiteral("carousel")) {
      item->media_manual_crop = true;
    }
    refreshCurrentSelectionPreviews();
    emitCanvasStateChanged(true);
    setStatus(normalized == QStringLiteral("edit")
                  ? QStringLiteral("Using the Edit crop as the photographic source.")
                  : normalized == QStringLiteral("original")
                        ? QStringLiteral("Using the unedited original source without changing saved edits.")
                        : QStringLiteral("Using uncropped edits with Carousel framing authoritative."));
    return;
  }
  auto* media = currentEditableMedia();
  if (media == nullptr || media->type == MediaType::Empty || media->crop_source == normalized) {
    return;
  }
  pushUndoState(QStringLiteral("Change crop ownership"));
  media->crop_source = normalized;
  if (normalized == QStringLiteral("carousel")) {
    media->manual_crop = true;
  }
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
  setStatus(normalized == QStringLiteral("edit")
                ? QStringLiteral("Using the Edit crop as the photographic source.")
                : normalized == QStringLiteral("original")
                      ? QStringLiteral("Using the unedited original source without changing saved edits.")
                      : QStringLiteral("Using uncropped edits with Carousel framing authoritative."));
}

bool CarouselDocumentController::startSelectedMediaBackgroundRemoval() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (cutout_watcher_ == nullptr || cutout_watcher_->isRunning()) {
    setStatus(QStringLiteral("Background removal is already processing."));
    return false;
  }
  const auto target_key = currentCutoutTargetKey();
  if (target_key.isEmpty()) {
    setStatus(QStringLiteral("Select a photo layer or photo slot before removing its background."));
    return false;
  }
  QImage source_image;
  if (const auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Image) {
    if (!decodeEditedImage(*item, &source_image, true, 1024)) {
      setStatus(QStringLiteral("Unable to decode the selected photo for background removal."));
      return false;
    }
  } else {
    const auto* media = currentEditableMedia();
    if (media == nullptr || !decodeEditedImage(*media, &source_image, true, 1024)) {
      setStatus(QStringLiteral("Unable to decode the selected photo for background removal."));
      return false;
    }
  }
  cutout_processing_target_ = target_key;
  cutout_processing_document_hash_ = documentContentHash();
  cutout_error_target_.clear();
  cutout_error_message_.clear();
  emit selectionChanged();
  setStatus(QStringLiteral("Removing the photo background…"));
  cutout_watcher_->setFuture(QtConcurrent::run(
      [source_image = std::move(source_image)]() mutable {
        return generate_bounded_subject_cutout(std::move(source_image));
      }));
  return true;
}

void CarouselDocumentController::finishBackgroundRemoval() {
  const auto target_key = cutout_processing_target_;
  const auto source_hash = cutout_processing_document_hash_;
  const auto result = cutout_watcher_ != nullptr ? cutout_watcher_->result() : QVariantMap{};
  cutout_processing_target_.clear();
  cutout_processing_document_hash_.clear();
  if (target_key.isEmpty()) {
    emit selectionChanged();
    return;
  }
  if (source_hash != documentContentHash()) {
    cutout_error_target_ = target_key;
    cutout_error_message_ = QStringLiteral("The document changed while the matte was processing. Run background removal again.");
    emit selectionChanged();
    setStatus(cutout_error_message_);
    return;
  }
  if (!result.value(QStringLiteral("success")).toBool()) {
    cutout_error_target_ = target_key;
    cutout_error_message_ = result.value(QStringLiteral("error")).toString();
    emit selectionChanged();
    setStatus(cutout_error_message_);
    return;
  }
  const auto mask_data = result.value(QStringLiteral("maskData")).toByteArray();
  const auto mask_width = result.value(QStringLiteral("maskWidth")).toInt();
  const auto mask_height = result.value(QStringLiteral("maskHeight")).toInt();
  if (mask_data.size() != mask_width * mask_height || mask_width <= 0 || mask_height <= 0) {
    cutout_error_target_ = target_key;
    cutout_error_message_ = QStringLiteral("Background removal returned an invalid matte.");
    emit selectionChanged();
    setStatus(cutout_error_message_);
    return;
  }

  const auto undo_size_before = undo_stack_.size();
  pushUndoState(QStringLiteral("Remove background"));
  bool applied = false;
  if (target_key.startsWith(QStringLiteral("item:"))) {
    const auto item_id = target_key.mid(QStringLiteral("item:").size());
    const auto item_index = indexOfItem(item_id);
    if (item_index >= 0 && items_[item_index].kind == ItemKind::Image) {
      auto& item = items_[item_index];
      item.cutout_mask_data = mask_data;
      item.cutout_mask_width = mask_width;
      item.cutout_mask_height = mask_height;
      item.cutout_enabled = true;
      item.cutout_feather = 0.0;
      item.cutout_expand = 0.0;
      item.cutout_edge_contrast = 0.0;
      applied = true;
    }
  } else if (auto* media = mediaForCutoutTarget(target_key);
             media != nullptr && media->type == MediaType::Image) {
    media->cutout_mask_data = mask_data;
    media->cutout_mask_width = mask_width;
    media->cutout_mask_height = mask_height;
    media->cutout_enabled = true;
    media->cutout_feather = 0.0;
    media->cutout_expand = 0.0;
    media->cutout_edge_contrast = 0.0;
    applied = true;
  }
  if (!applied) {
    if (undo_stack_.size() > undo_size_before) {
      undo_stack_.removeLast();
      emit historyChanged();
    }
    cutout_error_target_ = target_key;
    cutout_error_message_ = QStringLiteral("The selected photo was removed before background processing finished.");
    emit selectionChanged();
    setStatus(cutout_error_message_);
    return;
  }
  cutout_error_target_.clear();
  cutout_error_message_.clear();
  cutout_preview_mode_ = QStringLiteral("result");
  emit cutoutPreviewChanged();
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Background removed. Refine the edge or return to the original at any time."));
}

void CarouselDocumentController::useSelectedMediaOriginal() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto target_key = currentCutoutTargetKey();
  if (target_key.isEmpty()) {
    return;
  }
  if (auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Image) {
    if (!item->cutout_enabled || item->cutout_mask_data.isEmpty()) {
      return;
    }
    pushUndoState(QStringLiteral("Use original background"));
    item->cutout_enabled = false;
  } else {
    auto* media = currentEditableMedia();
    if (media == nullptr || !media->cutout_enabled || media->cutout_mask_data.isEmpty()) {
      return;
    }
    pushUndoState(QStringLiteral("Use original background"));
    media->cutout_enabled = false;
  }
  cutout_preview_mode_ = QStringLiteral("result");
  emit cutoutPreviewChanged();
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Showing the original photo; the cutout matte is retained."));
}

void CarouselDocumentController::restoreSelectedMediaCutout() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  if (auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Image) {
    if (item->cutout_enabled || item->cutout_mask_data.isEmpty()) {
      return;
    }
    pushUndoState(QStringLiteral("Restore cutout"));
    item->cutout_enabled = true;
  } else {
    auto* media = currentEditableMedia();
    if (media == nullptr || media->cutout_enabled || media->cutout_mask_data.isEmpty()) {
      return;
    }
    pushUndoState(QStringLiteral("Restore cutout"));
    media->cutout_enabled = true;
  }
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Restored the saved cutout matte."));
}

void CarouselDocumentController::setSelectedMediaCutoutRefinement(
    double feather,
    double expand,
    double edge_contrast) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto normalized_feather = qBound(0.0, feather, 16.0);
  const auto normalized_expand = qBound(-16.0, expand, 16.0);
  const auto normalized_contrast = qBound(-45.0, edge_contrast, 100.0);
  if (auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Image) {
    if (item->cutout_mask_data.isEmpty() ||
        (qFuzzyCompare(item->cutout_feather, normalized_feather) &&
         qFuzzyCompare(item->cutout_expand, normalized_expand) &&
         qFuzzyCompare(item->cutout_edge_contrast, normalized_contrast))) {
      return;
    }
    pushUndoState(QStringLiteral("Refine cutout"), true);
    item->cutout_feather = normalized_feather;
    item->cutout_expand = normalized_expand;
    item->cutout_edge_contrast = normalized_contrast;
  } else {
    auto* media = currentEditableMedia();
    if (media == nullptr || media->cutout_mask_data.isEmpty() ||
        (qFuzzyCompare(media->cutout_feather, normalized_feather) &&
         qFuzzyCompare(media->cutout_expand, normalized_expand) &&
         qFuzzyCompare(media->cutout_edge_contrast, normalized_contrast))) {
      return;
    }
    pushUndoState(QStringLiteral("Refine cutout"), true);
    media->cutout_feather = normalized_feather;
    media->cutout_expand = normalized_expand;
    media->cutout_edge_contrast = normalized_contrast;
  }
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
}

void CarouselDocumentController::setCutoutPreviewMode(const QString& mode) {
  const auto normalized = mode == QStringLiteral("black") || mode == QStringLiteral("white") ||
                                  mode == QStringLiteral("matte") || mode == QStringLiteral("edges")
                              ? mode
                              : QStringLiteral("result");
  if (cutout_preview_mode_ == normalized) {
    return;
  }
  cutout_preview_mode_ = normalized;
  refreshCurrentSelectionPreviews();
  emit cutoutPreviewChanged();
  emit selectionChanged();
}

void CarouselDocumentController::setCurrentVideoTrim(double in_seconds, double out_seconds) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto normalize = [](double duration, double requested_in, double requested_out) {
    const auto safe_duration = qMax(0.05, duration);
    const auto trim_in = qBound(0.0, requested_in, qMax(0.0, safe_duration - 0.05));
    const auto trim_out = qBound(
        trim_in + 0.05,
        requested_out <= 0.0 ? safe_duration : requested_out,
        safe_duration);
    return QPair<double, double>{trim_in, trim_out};
  };
  if (auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Video) {
    const auto duration = item->video_duration_seconds > 0.0
                              ? item->video_duration_seconds
                              : probeVideoDuration(item->file_path);
    const auto values = normalize(duration, in_seconds, out_seconds);
    if (qFuzzyCompare(item->video_trim_in_seconds, values.first) &&
        qFuzzyCompare(item->video_trim_out_seconds, values.second)) {
      return;
    }
    pushUndoState(QStringLiteral("Trim video"), true);
    item->video_duration_seconds = duration;
    item->video_trim_in_seconds = values.first;
    item->video_trim_out_seconds = values.second;
    item->video_poster_seconds = qBound(values.first, item->video_poster_seconds, values.second);
    emitCanvasStateChanged(true);
    return;
  }
  auto* media = currentEditableMedia();
  if (media == nullptr || media->type != MediaType::Video) {
    return;
  }
  const auto duration = media->video_duration_seconds > 0.0
                            ? media->video_duration_seconds
                            : probeVideoDuration(media->file_path);
  const auto values = normalize(duration, in_seconds, out_seconds);
  if (qFuzzyCompare(media->video_trim_in_seconds, values.first) &&
      qFuzzyCompare(media->video_trim_out_seconds, values.second)) {
    return;
  }
  pushUndoState(QStringLiteral("Trim video"), true);
  media->video_duration_seconds = duration;
  media->video_trim_in_seconds = values.first;
  media->video_trim_out_seconds = values.second;
  media->video_poster_seconds = qBound(values.first, media->video_poster_seconds, values.second);
  emitCanvasStateChanged(true);
}

void CarouselDocumentController::setCurrentVideoPosterFrame(double seconds) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  if (auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Video) {
    const auto trim_out = item->video_trim_out_seconds > item->video_trim_in_seconds
                              ? item->video_trim_out_seconds
                              : qMax(item->video_trim_in_seconds, item->video_duration_seconds);
    const auto normalized = qBound(item->video_trim_in_seconds, seconds, trim_out);
    if (qFuzzyCompare(item->video_poster_seconds, normalized)) {
      return;
    }
    pushUndoState(QStringLiteral("Set video poster frame"), true);
    item->video_poster_seconds = normalized;
    emitCanvasStateChanged(false);
    return;
  }
  auto* media = currentEditableMedia();
  if (media == nullptr || media->type != MediaType::Video) {
    return;
  }
  const auto trim_out = media->video_trim_out_seconds > media->video_trim_in_seconds
                            ? media->video_trim_out_seconds
                            : qMax(media->video_trim_in_seconds, media->video_duration_seconds);
  const auto normalized = qBound(media->video_trim_in_seconds, seconds, trim_out);
  if (qFuzzyCompare(media->video_poster_seconds, normalized)) {
    return;
  }
  pushUndoState(QStringLiteral("Set video poster frame"), true);
  media->video_poster_seconds = normalized;
  emitCanvasStateChanged(false);
}

void CarouselDocumentController::setCurrentVideoAudioPolicy(const QString& policy) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto normalized = policy.trimmed().toLower() == QStringLiteral("preserve")
                              ? QStringLiteral("preserve")
                              : QStringLiteral("mute");
  if (auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Video) {
    if (item->video_audio_policy == normalized) {
      return;
    }
    pushUndoState(QStringLiteral("Change video audio policy"));
    item->video_audio_policy = normalized;
    emitCanvasStateChanged(false);
    return;
  }
  auto* media = currentEditableMedia();
  if (media == nullptr || media->type != MediaType::Video || media->video_audio_policy == normalized) {
    return;
  }
  pushUndoState(QStringLiteral("Change video audio policy"));
  media->video_audio_policy = normalized;
  emitCanvasStateChanged(false);
}

void CarouselDocumentController::setCurrentVideoLoopIntent(bool loop) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  if (auto* item = currentItem(); item != nullptr && item->kind == ItemKind::Video) {
    if (item->video_loop_intent == loop) {
      return;
    }
    pushUndoState(QStringLiteral("Change video loop intent"));
    item->video_loop_intent = loop;
    emitCanvasStateChanged(false);
    return;
  }
  auto* media = currentEditableMedia();
  if (media == nullptr || media->type != MediaType::Video || media->video_loop_intent == loop) {
    return;
  }
  pushUndoState(QStringLiteral("Change video loop intent"));
  media->video_loop_intent = loop;
  emitCanvasStateChanged(false);
}

void CarouselDocumentController::moveCurrentMediaByPixels(double delta_x, double delta_y) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  if (currentItem() != nullptr) {
    return;
  }

  auto* media = currentEditableMedia();
  if (media == nullptr || media->type == MediaType::Empty || media->file_path.trimmed().isEmpty()) {
    return;
  }

  const auto viewport_size = currentMediaViewportSize();
  const auto source_size = effectiveMediaSourceSize(*media);
  if (!viewport_size.isValid() || !source_size.isValid()) {
    return;
  }

  const double viewport_width = static_cast<double>(viewport_size.width());
  const double viewport_height = static_cast<double>(viewport_size.height());
  const double source_width = static_cast<double>(source_size.width());
  const double source_height = static_cast<double>(source_size.height());
  if (viewport_width <= 0.0 || viewport_height <= 0.0 || source_width <= 0.0 || source_height <= 0.0) {
    return;
  }

  const double base_scale = media->fit_mode == FitMode::Contain
                                ? qMin(viewport_width / source_width, viewport_height / source_height)
                                : qMax(viewport_width / source_width, viewport_height / source_height);
  const double scaled_width = qMax(1.0, source_width * base_scale * media->scale);
  const double scaled_height = qMax(1.0, source_height * base_scale * media->scale);
  const double free_x = viewport_width - scaled_width;
  const double free_y = viewport_height - scaled_height;

  auto update_axis = [](double offset, double free_space, double delta) {
    if (qAbs(free_space) <= 0.001) {
      return 0.0;
    }
    const double minimum_position = qMin(0.0, free_space);
    const double maximum_position = qMax(0.0, free_space);
    const double current_position = free_space * ((offset + 1.0) / 2.0);
    const double next_position = qBound(minimum_position, current_position + delta, maximum_position);
    double next_offset = ((next_position / free_space) * 2.0) - 1.0;
    if (qAbs(next_offset) < 0.06) {
      next_offset = 0.0;
    } else if (qAbs(next_offset - 1.0) < 0.04) {
      next_offset = 1.0;
    } else if (qAbs(next_offset + 1.0) < 0.04) {
      next_offset = -1.0;
    }
    return clamp_unit_interval(next_offset);
  };

  const double next_offset_x = update_axis(media->offset_x, free_x, delta_x);
  const double next_offset_y = update_axis(media->offset_y, free_y, delta_y);
  if (qFuzzyCompare(media->offset_x, next_offset_x) && qFuzzyCompare(media->offset_y, next_offset_y)) {
    return;
  }

  pushUndoState(QStringLiteral("Position media"), true);
  media->offset_x = next_offset_x;
  media->offset_y = next_offset_y;
  media->manual_crop = true;
  preview_debounce_timer_->start();
  emitCanvasStateChanged(true);
}

void CarouselDocumentController::clearCurrentSlot() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  if (currentItem() != nullptr) {
    removeSelectedItem();
    return;
  }
  if (currentSelectionIsLinked()) {
    clearCurrentGroup();
    return;
  }

  auto* slide = slideAt(current_index_);
  if (slide == nullptr) {
    return;
  }

  pushUndoState(QStringLiteral("Clear media"));
  if (active_slot_ == QStringLiteral("secondary") &&
      (slide->template_kind == SlideTemplate::SplitPair || slide->template_kind == SlideTemplate::StackedTriptych)) {
    slide->secondary = MediaItem{};
    setStatus(slide->template_kind == SlideTemplate::SplitPair
                  ? QStringLiteral("Cleared the secondary media slot.")
                  : QStringLiteral("Cleared the middle media slot."));
  } else if (active_slot_ == QStringLiteral("tertiary") &&
             slide->template_kind == SlideTemplate::StackedTriptych) {
    slide->tertiary = MediaItem{};
    setStatus(QStringLiteral("Cleared the bottom media slot."));
  } else {
    slide->primary = MediaItem{};
    setStatus(QStringLiteral("Cleared the current slide media."));
  }

  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
}

void CarouselDocumentController::clearCurrentGroup() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  pushUndoState(QStringLiteral("Collapse spread"));
  removeGroupAtIndex(current_index_, true);
  refreshPreviews();
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Collapsed the linked spread back to a single canvas."));
}

