void CarouselDocumentController::assignPrimaryVideo(
    const QString& file_path,
    const QString& display_label) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  const auto normalized = normalized_path(file_path);
  if (!isVideoFile(normalized)) {
    setStatus(QStringLiteral("That file is not a supported video format."));
    return;
  }

  if (currentSelectionIsLinked()) {
    setStatus(QStringLiteral("Video is only supported on a single canvas."));
    return;
  }

  auto* slide = slideAt(current_index_);
  if (slide == nullptr) {
    return;
  }
  if (slide->template_kind != SlideTemplate::Single) {
    setStatus(QStringLiteral("Video is only supported on the Single template."));
    return;
  }

  pushUndoState(QStringLiteral("Add video"));
  const auto source_identity = source_file_identity(normalized, probeVideoSize(normalized));

  slide->primary = MediaItem{
      .type = MediaType::Video,
      .file_path = normalized,
      .display_label = displayNameForPath(normalized, display_label),
      .fit_mode = FitMode::Cover,
      .scale = 1.0,
      .offset_x = 0.0,
      .offset_y = 0.0,
      .video_duration_seconds = probeVideoDuration(normalized),
      .source_file_size = source_identity.file_size,
      .source_modified_ms = source_identity.modified_ms,
      .source_pixel_size = source_identity.pixel_size,
      .source_fingerprint = source_identity.fingerprint,
  };
  slide->secondary = MediaItem{};
  slide->tertiary = MediaItem{};
  active_slot_ = QStringLiteral("primary");
  setSelectedItemIds({});
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Video added to the current canvas."));
}

bool CarouselDocumentController::dropMediaOnTarget(
    const QString& file_path,
    const QString& media_type,
    int board_index,
    const QString& target_kind,
    const QString& slot_name,
    double normalized_x,
    double normalized_y,
    const QString& display_label,
    const QString& adjustment_patch_json) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (board_index < 0 || board_index >= slides_.size()) {
    setStatus(QStringLiteral("The drop target board is unavailable."));
    return false;
  }
  const auto normalized_file = normalized_path(file_path);
  const auto type = media_type.trimmed().toLower();
  const bool is_video = type == QStringLiteral("video") || isVideoFile(normalized_file);
  const bool is_image = !is_video && isImageFile(normalized_file);
  if (!is_video && !is_image) {
    setStatus(QStringLiteral("That dropped file is not supported media."));
    return false;
  }
  const auto target = target_kind.trimmed().toLower();
  if (target != QStringLiteral("slot") && target != QStringLiteral("board") &&
      target != QStringLiteral("thumbnail") && target != QStringLiteral("layer") &&
      target != QStringLiteral("layer-stack")) {
    setStatus(QStringLiteral("The drop target is unavailable."));
    return false;
  }
  auto slot = slot_name.trimmed().toLower();
  if (target == QStringLiteral("thumbnail")) {
    slot = QStringLiteral("primary");
  }
  if (slot != QStringLiteral("secondary") && slot != QStringLiteral("tertiary")) {
    slot = QStringLiteral("primary");
  }
  const bool as_layer = target == QStringLiteral("layer") || target == QStringLiteral("layer-stack");
  const auto* target_slide = slideAt(board_index);
  if (is_video && !as_layer &&
      (target_slide == nullptr || target_slide->template_kind != SlideTemplate::Single ||
       groupForIndex(board_index) != nullptr || slot != QStringLiteral("primary"))) {
    setStatus(QStringLiteral("Video can only be dropped into a Single board's primary slot or layer stack."));
    return false;
  }

  selectSlide(board_index);
  const auto before_hash = documentContentHash();
  beginHistoryTransaction(QStringLiteral("Drop media"));
  if (as_layer) {
    if (is_video) {
      addVideoItem(normalized_file, display_label);
    } else {
      addPhotoItem(normalized_file, display_label, adjustment_patch_json);
    }
    const auto slide_rect = slideRectInDocument(board_index);
    setSelectedItemCenter(
        slide_rect.left() + slide_rect.width() * clamp_focal_coordinate(normalized_x),
        slide_rect.top() + slide_rect.height() * clamp_focal_coordinate(normalized_y));
  } else if (is_video) {
    assignPrimaryVideo(normalized_file, display_label);
  } else if (slot == QStringLiteral("secondary")) {
    assignSecondaryImage(normalized_file, display_label, adjustment_patch_json);
  } else if (slot == QStringLiteral("tertiary")) {
    assignTertiaryImage(normalized_file, display_label, adjustment_patch_json);
  } else {
    assignPrimaryImage(normalized_file, display_label, adjustment_patch_json);
  }
  commitHistoryTransaction();
  const bool changed = before_hash != documentContentHash();
  if (changed) {
    setStatus(as_layer
                  ? QStringLiteral("Dropped media into board %1's layer stack.").arg(board_index + 1)
                  : QStringLiteral("Dropped media into board %1's %2 slot.")
                        .arg(board_index + 1)
                        .arg(slot));
  }
  return changed;
}

