bool CarouselDocumentController::exportBoardToPlan(
    int index,
    const QVariantMap& output_plan,
    const QSize& size,
    QString* failure_reason) {
  if (exportCancellationRequested()) return false;
  if (output_plan.value(QStringLiteral("action")).toString() == QStringLiteral("skip")) {
    return true;
  }
  const auto output_path = output_plan.value(QStringLiteral("outputPath")).toString();
  const auto* slide = slideAt(index);
  const auto* group = groupForIndex(index);
  if (slide == nullptr || output_path.isEmpty()) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("The export plan for board %1 is invalid.").arg(index + 1);
    }
    return false;
  }
  if (group != nullptr && group->media.type != MediaType::Image) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("A linked spread is missing its source image.");
    }
    return false;
  }
  if (group == nullptr && slide->template_kind == SlideTemplate::SplitPair &&
      (slide->primary.type != MediaType::Image || slide->secondary.type != MediaType::Image)) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("A split canvas is missing one of its images.");
    }
    return false;
  }
  if (group == nullptr && slide->template_kind == SlideTemplate::StackedTriptych &&
      (slide->primary.type != MediaType::Image || slide->secondary.type != MediaType::Image ||
       slide->tertiary.type != MediaType::Image)) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("A stacked canvas is missing one of its images.");
    }
    return false;
  }

  if (slide->template_kind == SlideTemplate::Single && slide->primary.type == MediaType::Video) {
    if (!exportVideoSlide(slide->primary, output_path, size, index)) {
      if (failure_reason != nullptr) {
        *failure_reason = QStringLiteral(
                              "Unable to export video canvas %1. Install ffmpeg to enable video export.")
                              .arg(index + 1);
      }
      return false;
    }
    return true;
  }

  auto image = renderSlideImage(index, size, false);
  if (exportCancellationRequested()) return false;
  if (!export_preserve_transparency_ || export_image_format_ == QStringLiteral("jpeg")) {
    image = image.convertToFormat(QImage::Format_RGB32);
    image.setColorSpace(output_color_space_for_name(export_color_space_));
  }
  const auto writer_format = export_image_format_ == QStringLiteral("jpeg")
                                 ? QByteArrayLiteral("jpg")
                                 : export_image_format_.toLatin1();
  QImageWriter writer(output_path, writer_format);
  writer.setQuality(export_image_quality_);
  if (!writer.write(image)) {
    if (failure_reason != nullptr) {
      *failure_reason = writer.errorString();
    }
    return false;
  }
  if (exportCancellationRequested()) return false;
  QImageReader verification_reader(output_path);
  const auto verified_format = verification_reader.format().toLower();
  const auto verified_image = verification_reader.read();
  const auto expected_color_space = output_color_space_for_name(export_color_space_);
  const bool format_matches =
      export_image_format_ == QStringLiteral("jpeg")
          ? verified_format == QByteArrayLiteral("jpg") || verified_format == QByteArrayLiteral("jpeg")
          : verified_format == writer_format;
  if (verified_image.isNull() || verified_image.size() != size || !format_matches ||
      !verified_image.colorSpace().isValid() || verified_image.colorSpace() != expected_color_space) {
    QFile::remove(output_path);
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral(
                            "Exported board %1 failed %2 pixel, format, or %3 profile verification.")
                            .arg(index + 1)
                            .arg(export_image_format_.toUpper())
                            .arg(export_color_space_);
    }
    return false;
  }
  return true;
}

bool CarouselDocumentController::writeProofContactSheet(
    const QVariantList& output_preview,
    const QSize& size,
    QString* failure_reason) {
  if (!export_proof_sheet_enabled_) {
    return true;
  }

  QVariantMap proof_plan;
  QVector<QVariantMap> board_plans;
  for (const auto& value : output_preview) {
    const auto plan = value.toMap();
    const auto artifact_type = plan.value(QStringLiteral("artifactType")).toString();
    if (artifact_type == QStringLiteral("proof")) {
      proof_plan = plan;
    } else if (artifact_type == QStringLiteral("board")) {
      board_plans.push_back(plan);
    }
  }
  if (proof_plan.isEmpty() || board_plans.isEmpty()) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("The PDF proof export plan is incomplete.");
    }
    return false;
  }
  if (proof_plan.value(QStringLiteral("action")).toString() == QStringLiteral("skip")) {
    return true;
  }

  const auto output_path = proof_plan.value(QStringLiteral("outputPath")).toString();
  QSaveFile output_file(output_path);
  if (output_path.isEmpty() || !output_file.open(QIODevice::WriteOnly)) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("Unable to create the PDF proof contact sheet.");
    }
    return false;
  }

  {
    QPdfWriter writer(&output_file);
    writer.setResolution(144);
    writer.setPageLayout(QPageLayout(
        QPageSize(QPageSize::A4),
        QPageLayout::Landscape,
        QMarginsF(10.0, 10.0, 10.0, 10.0),
        QPageLayout::Millimeter));
    writer.setTitle(QStringLiteral("%1 · PDF proof").arg(document_name_));
    writer.setCreator(QStringLiteral("Looksy Carousel"));

    QPainter painter(&writer);
    if (!painter.isActive()) {
      if (failure_reason != nullptr) {
        *failure_reason = QStringLiteral("Unable to initialize PDF proof rendering.");
      }
      return false;
    }
    painter.setRenderHint(QPainter::Antialiasing, true);
    painter.setRenderHint(QPainter::TextAntialiasing, true);
    painter.setRenderHint(QPainter::SmoothPixmapTransform, true);

    const auto page_rect = writer.pageLayout().paintRectPixels(writer.resolution());
    constexpr int columns = 2;
    constexpr int rows = 2;
    constexpr int boards_per_page = columns * rows;
    const int header_height = qMax(76, page_rect.height() / 12);
    const int footer_height = 24;
    const int gap = qMax(14, page_rect.width() / 90);
    const int grid_width = page_rect.width() - gap;
    const int grid_height = page_rect.height() - header_height - footer_height - gap;
    const int cell_width = grid_width / columns;
    const int cell_height = grid_height / rows;
    const auto proof_space = QColorSpace(QColorSpace::SRgb);

    const auto draw_page_header = [&](int page_number) {
      painter.save();
      painter.setPen(QColor(QStringLiteral("#17191c")));
      QFont title_font(QStringLiteral("Helvetica Neue"));
      title_font.setPointSizeF(15.0);
      title_font.setWeight(QFont::DemiBold);
      painter.setFont(title_font);
      painter.drawText(
          QRect(page_rect.left(), page_rect.top(), page_rect.width() * 2 / 3,
                header_height / 2),
          Qt::AlignLeft | Qt::AlignVCenter,
          document_name_);
      QFont detail_font(QStringLiteral("Helvetica Neue"));
      detail_font.setPointSizeF(8.5);
      painter.setFont(detail_font);
      painter.setPen(QColor(QStringLiteral("#545b64")));
      painter.drawText(
          QRect(page_rect.left(), page_rect.top() + header_height / 2,
                page_rect.width(), header_height / 2),
          Qt::AlignLeft | Qt::AlignVCenter,
          QStringLiteral(
              "PDF proof · review only · thumbnails color-managed from %1 to sRGB · platform-ready files exported separately")
              .arg(export_color_space_));
      painter.drawText(
          QRect(page_rect.right() - 180, page_rect.top(), 180, header_height / 2),
          Qt::AlignRight | Qt::AlignVCenter,
          QStringLiteral("Page %1").arg(page_number));
      painter.restore();
    };

    draw_page_header(1);
    int page_number = 1;
    for (int position = 0; position < board_plans.size(); ++position) {
      if (exportCancellationRequested()) return false;
      if (position > 0 && position % boards_per_page == 0) {
        if (!writer.newPage()) {
          if (failure_reason != nullptr) {
            *failure_reason = QStringLiteral("Unable to add a page to the PDF proof.");
          }
          return false;
        }
        ++page_number;
        draw_page_header(page_number);
      }
      const auto& plan = board_plans.at(position);
      const auto board_index = plan.value(QStringLiteral("boardIndex"), -1).toInt();
      const auto* slide = slideAt(board_index);
      if (slide == nullptr) {
        if (failure_reason != nullptr) {
          *failure_reason = QStringLiteral("Unable to render board %1 into the PDF proof.")
                                .arg(board_index + 1);
        }
        return false;
      }
      const int page_position = position % boards_per_page;
      const int column = page_position % columns;
      const int row = page_position / columns;
      const QRect cell_rect(
          page_rect.left() + column * cell_width + (column > 0 ? gap : 0),
          page_rect.top() + header_height + row * cell_height + (row > 0 ? gap : 0),
          cell_width - gap,
          cell_height - gap);

      painter.save();
      painter.setPen(QPen(QColor(QStringLiteral("#c9cdd2")), 1));
      painter.setBrush(QColor(QStringLiteral("#f7f8f9")));
      painter.drawRoundedRect(cell_rect, 8, 8);

      const int cell_padding = 12;
      const int metadata_height = export_proof_include_notes_ ? qMax(122, cell_height / 3)
                                                               : qMax(68, cell_height / 6);
      const QRect image_area = cell_rect.adjusted(
          cell_padding,
          cell_padding,
          -cell_padding,
          -(metadata_height + cell_padding));
      const auto source_aspect = static_cast<double>(qMax(1, size.width())) /
                                 static_cast<double>(qMax(1, size.height()));
      auto thumbnail_width = image_area.width();
      auto thumbnail_height = qRound(static_cast<double>(thumbnail_width) / source_aspect);
      if (thumbnail_height > image_area.height()) {
        thumbnail_height = image_area.height();
        thumbnail_width = qRound(static_cast<double>(thumbnail_height) * source_aspect);
      }
      const QRect thumbnail_rect(
          image_area.center().x() - thumbnail_width / 2,
          image_area.center().y() - thumbnail_height / 2,
          thumbnail_width,
          thumbnail_height);
      auto thumbnail = renderSlideImage(board_index, thumbnail_rect.size(), false);
      if (exportCancellationRequested()) {
        painter.restore();
        return false;
      }
      if (!thumbnail.colorSpace().isValid()) {
        thumbnail.setColorSpace(output_color_space_for_name(export_color_space_));
      }
      if (thumbnail.colorSpace() != proof_space) {
        thumbnail = convert_tagged_qimage_color_space(
            thumbnail,
            proof_space,
            QImageColorConversionPurpose::ProofPublication);
      }
      QImage flattened_thumbnail(thumbnail.size(), QImage::Format_RGB32);
      flattened_thumbnail.setColorSpace(proof_space);
      flattened_thumbnail.fill(Qt::white);
      {
        QPainter flatten_painter(&flattened_thumbnail);
        flatten_painter.drawImage(0, 0, thumbnail);
      }
      painter.drawImage(thumbnail_rect, flattened_thumbnail);
      painter.setPen(QPen(QColor(QStringLiteral("#9da3aa")), 1));
      painter.setBrush(Qt::NoBrush);
      painter.drawRect(thumbnail_rect.adjusted(0, 0, -1, -1));

      const QRect metadata_rect(
          cell_rect.left() + cell_padding,
          cell_rect.bottom() - metadata_height,
          cell_rect.width() - cell_padding * 2,
          metadata_height - cell_padding);
      QFont heading_font(QStringLiteral("Helvetica Neue"));
      heading_font.setPointSizeF(10.0);
      heading_font.setWeight(QFont::DemiBold);
      painter.setFont(heading_font);
      painter.setPen(QColor(QStringLiteral("#1c2024")));
      const auto board_name = slide->board_name.isEmpty()
                                  ? QStringLiteral("Untitled board")
                                  : slide->board_name;
      painter.drawText(
          QRect(metadata_rect.left(), metadata_rect.top(), metadata_rect.width(), 24),
          Qt::AlignLeft | Qt::AlignVCenter,
          QStringLiteral("Board %1 · %2 · %3")
              .arg(board_index + 1)
              .arg(board_name, slide->board_role));

      QFont metadata_font(QStringLiteral("Helvetica Neue"));
      metadata_font.setPointSizeF(7.5);
      painter.setFont(metadata_font);
      painter.setPen(QColor(QStringLiteral("#4f565e")));
      painter.drawText(
          QRect(metadata_rect.left(), metadata_rect.top() + 25,
                metadata_rect.width(), 20),
          Qt::AlignLeft | Qt::AlignVCenter,
          QStringLiteral("File: %1 · Output profile: %2")
              .arg(plan.value(QStringLiteral("resolvedName")).toString(),
                   export_color_space_));
      if (export_proof_include_notes_) {
        QStringList notes;
        if (!slide->message_note.isEmpty()) {
          notes.push_back(QStringLiteral("Message: %1").arg(slide->message_note));
        }
        if (!slide->media_intent_note.isEmpty()) {
          notes.push_back(QStringLiteral("Media: %1").arg(slide->media_intent_note));
        }
        if (!slide->source_reference_note.isEmpty()) {
          notes.push_back(QStringLiteral("Source: %1").arg(slide->source_reference_note));
        }
        const auto note_text = notes.isEmpty()
                                   ? QStringLiteral("Notes: none")
                                   : notes.join(QStringLiteral("\n"));
        QTextOption text_option;
        text_option.setWrapMode(QTextOption::WrapAtWordBoundaryOrAnywhere);
        painter.drawText(
            QRectF(metadata_rect.left(), metadata_rect.top() + 48,
                   metadata_rect.width(), metadata_rect.height() - 48),
            note_text,
            text_option);
      }
      painter.restore();
    }
    painter.end();
  }

  if (!output_file.commit()) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("Unable to finish the PDF proof contact sheet.");
    }
    return false;
  }
  return true;
}

bool CarouselDocumentController::writeDeliveryManifest(
    const QVariantList& output_preview,
    const QVariantList& preflight_issues,
    const QSize& size,
    QString* failure_reason) {
  if (!export_manifest_enabled_) {
    return true;
  }
  QVariantMap manifest_plan;
  for (const auto& value : output_preview) {
    const auto plan = value.toMap();
    if (plan.value(QStringLiteral("artifactType")).toString() ==
        QStringLiteral("manifest")) {
      manifest_plan = plan;
      break;
    }
  }
  if (manifest_plan.isEmpty()) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("The delivery manifest export plan is missing.");
    }
    return false;
  }
  if (manifest_plan.value(QStringLiteral("action")).toString() == QStringLiteral("skip")) {
    return true;
  }

  QJsonArray warning_array;
  for (const auto& value : preflight_issues) {
    const auto issue = value.toMap();
    if (!issue.value(QStringLiteral("blocking")).toBool()) {
      warning_array.push_back(QJsonObject{
          {QStringLiteral("code"), issue.value(QStringLiteral("code")).toString()},
          {QStringLiteral("boardIndex"), issue.value(QStringLiteral("boardIndex")).toInt()},
          {QStringLiteral("itemId"), issue.value(QStringLiteral("itemId")).toString()},
          {QStringLiteral("message"), issue.value(QStringLiteral("message")).toString()},
      });
    }
  }

  QJsonArray ordered_outputs;
  for (const auto& value : output_preview) {
    const auto output_plan = value.toMap();
    const auto index = output_plan.value(QStringLiteral("boardIndex"), -1).toInt();
    if (index < 0) {
      continue;
    }
    QFile output_file(output_plan.value(QStringLiteral("outputPath")).toString());
    QCryptographicHash hash(QCryptographicHash::Sha256);
    bool hashed = output_file.open(QIODevice::ReadOnly);
    while (hashed && !output_file.atEnd()) {
      if (exportCancellationRequested()) return false;
      const auto bytes = output_file.read(1024 * 1024);
      if (bytes.isEmpty() && output_file.error() != QFile::NoError) hashed = false;
      else hash.addData(bytes);
    }
    if (!hashed) {
      if (failure_reason != nullptr) {
        *failure_reason = QStringLiteral("Unable to hash exported board %1 for the delivery manifest.")
                              .arg(index + 1);
      }
      return false;
    }
    const auto* slide = slideAt(index);
    QJsonArray board_warnings;
    for (const auto& warning_value : warning_array) {
      const auto warning = warning_value.toObject();
      if (warning.value(QStringLiteral("boardIndex")).toInt() == index) {
        board_warnings.push_back(warning);
      }
    }
    QJsonArray board_reading_order;
    for (const auto& entry_value : readingOrderEntriesForSlide(index, true)) {
      const auto entry = entry_value.toMap();
      board_reading_order.push_back(QJsonObject{
          {QStringLiteral("position"), entry.value(QStringLiteral("position")).toInt()},
          {QStringLiteral("key"), entry.value(QStringLiteral("key")).toString()},
          {QStringLiteral("kind"), entry.value(QStringLiteral("kind")).toString()},
          {QStringLiteral("sourceType"), entry.value(QStringLiteral("sourceType")).toString()},
          {QStringLiteral("slot"), entry.value(QStringLiteral("slot")).toString()},
          {QStringLiteral("itemId"), entry.value(QStringLiteral("itemId")).toString()},
          {QStringLiteral("label"), entry.value(QStringLiteral("label")).toString()},
          {QStringLiteral("text"), entry.value(QStringLiteral("text")).toString()},
          {QStringLiteral("description"), entry.value(QStringLiteral("description")).toString()},
      });
    }
    ordered_outputs.push_back(QJsonObject{
        {QStringLiteral("boardIndex"), index},
        {QStringLiteral("boardNumber"), index + 1},
        {QStringLiteral("fileName"), output_plan.value(QStringLiteral("resolvedName")).toString()},
        {QStringLiteral("fileType"), output_plan.value(QStringLiteral("fileType")).toString()},
        {QStringLiteral("width"), size.width()},
        {QStringLiteral("height"), size.height()},
        {QStringLiteral("sha256"), QString::fromLatin1(hash.result().toHex())},
        {QStringLiteral("colorProfile"), export_color_space_},
        {QStringLiteral("boardRole"), slide != nullptr ? slide->board_role : QStringLiteral("content")},
        {QStringLiteral("altText"), slide != nullptr ? slide->alt_text : QString{}},
        {QStringLiteral("plainLanguageDescription"),
         slide != nullptr ? slide->plain_language_description : QString{}},
        {QStringLiteral("readingOrder"), board_reading_order},
        {QStringLiteral("warnings"), board_warnings},
    });
  }

  const QJsonObject manifest{
      {QStringLiteral("manifestVersion"), 2},
      {QStringLiteral("documentId"), saved_document_id_.isEmpty() ? session_id_ : saved_document_id_},
      {QStringLiteral("documentName"), document_name_},
      {QStringLiteral("documentSchemaVersion"), kCarouselDocumentSchemaVersion},
      {QStringLiteral("exportVersion"), export_version_},
      {QStringLiteral("boardScope"), export_board_scope_},
      {QStringLiteral("exportedAt"), QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)},
      {QStringLiteral("ratio"), document_format_},
      {QStringLiteral("colorProfile"), export_color_space_},
      {QStringLiteral("exportPreset"), QJsonObject{
           {QStringLiteral("presetId"), active_export_preset_id_},
           {QStringLiteral("presetVersion"), active_export_preset_version_},
           {QStringLiteral("overrideCount"),
            exportPresetState().value(QStringLiteral("overrideCount")).toInt()},
       }},
      {QStringLiteral("outputs"), ordered_outputs},
      {QStringLiteral("warnings"), warning_array},
  };
  QSaveFile manifest_file(manifest_plan.value(QStringLiteral("outputPath")).toString());
  if (!manifest_file.open(QIODevice::WriteOnly)) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("Unable to create the delivery manifest.");
    }
    return false;
  }
  manifest_file.write(QJsonDocument(manifest).toJson(QJsonDocument::Indented));
  if (!manifest_file.commit()) {
    if (failure_reason != nullptr) {
      *failure_reason = QStringLiteral("Unable to finish the delivery manifest.");
    }
    return false;
  }
  return true;
}

void CarouselDocumentController::exportCarousel() {
  const auto directory_path = chooseExportDirectory();
  if (directory_path.isEmpty()) {
    return;
  }
  startConfiguredExport();
}

bool CarouselDocumentController::exportCarouselToDirectory(const QString& directory_path) {
  if (export_busy_ || export_task_state_) return false;
  const QDir output_dir(directory_path);
  if (!output_dir.exists()) {
    setStatus(QStringLiteral("Export folder does not exist."));
    return false;
  }
  setExportDirectory(output_dir.absolutePath());

  const auto preflight_issues = exportPreflightIssues();
  for (const auto& value : preflight_issues) {
    const auto issue = value.toMap();
    if (!issue.value(QStringLiteral("blocking")).toBool()) {
      continue;
    }
    setStatus(QStringLiteral("Export blocked: %1").arg(issue.value(QStringLiteral("message")).toString()));
    return false;
  }

  setExportBusy(true);
  bool success = true;
  QString failure_reason;
  int written_count = 0;
  int skipped_count = 0;
  const auto size = configuredExportPixelSize();
  const auto output_preview = exportOutputPreview();

  for (const auto& value : output_preview) {
    const auto output_plan = value.toMap();
    const auto board_index = output_plan.value(QStringLiteral("boardIndex"), -1).toInt();
    if (board_index < 0) {
      continue;
    }
    if (output_plan.value(QStringLiteral("action")).toString() == QStringLiteral("skip")) {
      ++skipped_count;
      continue;
    }
    if (!exportBoardToPlan(board_index, output_plan, size, &failure_reason)) {
      success = false;
      break;
    }
    ++written_count;
  }

  if (success && (export_proof_sheet_enabled_ || export_manifest_enabled_)) {
    for (const auto& value : output_preview) {
      const auto output_plan = value.toMap();
      if (output_plan.value(QStringLiteral("artifactType")).toString() !=
              QStringLiteral("board") &&
          output_plan.value(QStringLiteral("action")).toString() == QStringLiteral("skip")) {
        ++skipped_count;
      }
    }
  }
  if (success &&
      !writeProofContactSheet(output_preview, size, &failure_reason)) {
    success = false;
  }
  if (success && !writeDeliveryManifest(output_preview, preflight_issues, size, &failure_reason)) {
    success = false;
  }

  setExportBusy(false);
  if (!success) {
    setStatus(failure_reason);
    return false;
  }

  setStatus(QStringLiteral("Exported %1 canvas%2 to %3.")
                .arg(written_count)
                .arg(written_count == 1 ? QString{} : QStringLiteral("es"))
                .arg(output_dir.absolutePath()) +
            (skipped_count > 0
                 ? QStringLiteral(" Skipped %1 existing file%2.")
                       .arg(skipped_count)
                       .arg(skipped_count == 1 ? QString{} : QStringLiteral("s"))
                 : QString{}));
  return true;
}

void CarouselDocumentController::focusPreflightIssue(int board_index, const QString& item_id) {
  if (slides_.isEmpty()) {
    return;
  }
  const auto normalized_index = qBound(0, board_index, static_cast<int>(slides_.size()) - 1);
  const auto normalized_item_id = item_id.trimmed();
  if (!normalized_item_id.isEmpty() && indexOfItem(normalized_item_id) >= 0) {
    selectItem(normalized_item_id);
  } else {
    selectSlide(normalized_index);
    setSelectedItemIds({});
  }
  setStatus(QStringLiteral("Focused preflight issue on board %1.").arg(normalized_index + 1));
}

void CarouselDocumentController::focusPreflightIssueById(const QString& issue_id) {
  const auto normalized = issue_id.trimmed();
  for (const auto& value : preflightIssues()) {
    const auto issue = value.toMap();
    if (issue.value(QStringLiteral("issueId")).toString() != normalized) {
      continue;
    }
    preflight_current_issue_id_ = normalized;
    focusPreflightIssue(
        issue.value(QStringLiteral("boardIndex")).toInt(),
        issue.value(QStringLiteral("itemId")).toString());
    emit preflightChanged();
    return;
  }
}

void CarouselDocumentController::setPreflightSeverityFilter(const QString& severity) {
  const auto normalized = severity.trimmed().toLower();
  const auto next = normalized == QStringLiteral("error") || normalized == QStringLiteral("warning")
                        ? normalized
                        : QStringLiteral("all");
  if (preflight_severity_filter_ == next) {
    return;
  }
  preflight_severity_filter_ = next;
  preflight_current_issue_id_.clear();
  emit preflightChanged();
}

void CarouselDocumentController::navigatePreflightIssue(int direction) {
  const auto state = preflightIssueState();
  const auto issues = state.value(QStringLiteral("issues")).toList();
  if (issues.isEmpty()) {
    return;
  }
  auto index = state.value(QStringLiteral("currentIndex")).toInt();
  if (index < 0) {
    index = 0;
  } else if (direction < 0) {
    index = (index + static_cast<int>(issues.size()) - 1) % static_cast<int>(issues.size());
  } else {
    index = (index + 1) % static_cast<int>(issues.size());
  }
  focusPreflightIssueById(issues.at(index).toMap().value(QStringLiteral("issueId")).toString());
}

bool CarouselDocumentController::ignorePreflightIssue(const QString& issue_id, const QString& reason) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_id = issue_id.trimmed();
  const auto normalized_reason = reason.simplified();
  if (normalized_id.isEmpty() || normalized_reason.isEmpty()) {
    setStatus(QStringLiteral("Give a reason before ignoring a preflight issue."));
    return false;
  }
  for (const auto& value : preflightIssues()) {
    const auto issue = value.toMap();
    if (issue.value(QStringLiteral("issueId")).toString() != normalized_id) {
      continue;
    }
    if (issue.value(QStringLiteral("severity")).toString() == QStringLiteral("error")) {
      setStatus(QStringLiteral("Blocking preflight errors cannot be ignored."));
      return false;
    }
    pushUndoState(QStringLiteral("Ignore preflight issue"));
    ignored_preflight_issue_reasons_.insert(normalized_id, normalized_reason);
    preflight_current_issue_id_.clear();
    markDocumentDirty();
    emit preflightChanged();
    setStatus(QStringLiteral("Ignored one preflight warning: %1").arg(normalized_reason));
    return true;
  }
  return false;
}

bool CarouselDocumentController::resolveTextPreflightIssue(
    const QString& item_id,
    const QString& issue_code,
    const QString& action) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto item_index = indexOfItem(item_id.trimmed());
  if (item_index < 0 || items_.at(item_index).kind != ItemKind::Text) {
    setStatus(QStringLiteral("The affected text layer is unavailable."));
    return false;
  }
  const auto code = issue_code.trimmed().toLower();
  const auto normalized_action = action.trimmed().toLower();
  if (code != QStringLiteral("text-overflow") && code != QStringLiteral("text-too-small")) {
    return false;
  }
  const auto board_index = qBound(
      0,
      slideIndexForItem(items_.at(item_index)),
      qMax(0, static_cast<int>(slides_.size()) - 1));
  if (normalized_action == QStringLiteral("inspect")) {
    focusPreflightIssue(board_index, item_id);
    setStatus(QStringLiteral("Inspecting the affected text frame on board %1.").arg(board_index + 1));
    return true;
  }
  if (normalized_action == QStringLiteral("ignore")) {
    if (items_.at(item_index).ignored_preflight_codes.contains(code)) {
      return true;
    }
    pushUndoState(QStringLiteral("Ignore text preflight issue"));
    items_[item_index].ignored_preflight_codes.push_back(code);
    emitCanvasStateChanged(true);
    setStatus(QStringLiteral("Ignored '%1' for the selected layer; the exception is saved with the document.")
                  .arg(code));
    return true;
  }

  auto next = items_.at(item_index);
  if (normalized_action == QStringLiteral("resize-frame")) {
    if (code == QStringLiteral("text-too-small")) {
      next.text_point_size = qMax(next.text_point_size, kMinReadableTextPointSize);
    }
    next.bounds.setHeight(qMax(next.bounds.height(), measuredTextHeight(next) + 2.0));
    pushUndoState(QStringLiteral("Resize text frame for preflight"));
    items_[item_index] = next;
  } else if (normalized_action == QStringLiteral("fit-text")) {
    if (code == QStringLiteral("text-too-small")) {
      next.text_point_size = qMax(next.text_point_size, kMinReadableTextPointSize);
      if (measuredTextHeight(next) > next.bounds.height() + 1.0) {
        setStatus(QStringLiteral("The readable minimum does not fit this frame; resize the frame first."));
        return false;
      }
    } else {
      auto smallest = next;
      smallest.text_point_size = kMinTextPointSize;
      if (measuredTextHeight(smallest) > smallest.bounds.height() + 1.0) {
        setStatus(QStringLiteral("Text still overflows at the minimum size; resize the frame instead."));
        return false;
      }
      double low = kMinTextPointSize;
      double high = next.text_point_size;
      for (int iteration = 0; iteration < 24; ++iteration) {
        const auto candidate_size = (low + high) * 0.5;
        auto candidate = next;
        candidate.text_point_size = candidate_size;
        if (measuredTextHeight(candidate) <= candidate.bounds.height() + 1.0) {
          low = candidate_size;
        } else {
          high = candidate_size;
        }
      }
      next.text_point_size = qMax(kMinTextPointSize, low);
    }
    pushUndoState(QStringLiteral("Fit text for preflight"));
    items_[item_index] = next;
  } else {
    return false;
  }

  items_[item_index].ignored_preflight_codes.removeAll(code);
  setSelectedItemId(item_id);
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
  setStatus(normalized_action == QStringLiteral("resize-frame")
                ? QStringLiteral("Resized the affected text frame on board %1.").arg(board_index + 1)
                : QStringLiteral("Fit the affected text on board %1 without clipping.").arg(board_index + 1));
  return true;
}

QString CarouselDocumentController::chooseRelinkDirectory() {
  const auto directory = QFileDialog::getExistingDirectory(
      nullptr,
      QStringLiteral("Choose Folder Containing Missing Media"),
      relink_directory_.isEmpty() ? QDir::homePath() : relink_directory_);
  if (!directory.isEmpty()) {
    scanRelinkDirectory(directory);
  }
  return relink_directory_;
}

bool CarouselDocumentController::scanRelinkDirectory(const QString& directory_path) {
  const auto normalized_directory = QDir::cleanPath(directory_path.trimmed());
  if (normalized_directory.isEmpty() || !QDir(normalized_directory).exists()) {
    setStatus(QStringLiteral("Choose an available folder to scan for missing media."));
    return false;
  }

  struct Candidate final {
    QString path;
    SourceFileIdentity identity;
  };
  QVector<Candidate> candidates;
  QDirIterator iterator(
      normalized_directory,
      QDir::Files | QDir::Readable,
      QDirIterator::Subdirectories);
  while (iterator.hasNext() && candidates.size() < 5000) {
    const auto path = iterator.next();
    if (!isImageFile(path) && !isVideoFile(path)) {
      continue;
    }
    candidates.push_back(Candidate{path, source_file_identity(path)});
  }

  QVariantList plan;
  int safe_count = 0;
  for (const auto& value : missingMediaEntries()) {
    auto entry = value.toMap();
    const auto original_path = entry.value(QStringLiteral("originalPath")).toString();
    const auto original_name = QFileInfo(original_path).fileName();
    const auto expected_size = entry.value(QStringLiteral("sourceFileSize")).toLongLong();
    const QSize expected_pixels(
        entry.value(QStringLiteral("sourceWidth")).toInt(),
        entry.value(QStringLiteral("sourceHeight")).toInt());
    const auto expected_fingerprint = entry.value(QStringLiteral("sourceFingerprint")).toString();
    int best_score = 0;
    QVector<int> best_indexes;
    QString best_reason;
    for (int index = 0; index < candidates.size(); ++index) {
      const auto& candidate = candidates.at(index);
      const bool fingerprint_match = !expected_fingerprint.isEmpty() &&
                                     candidate.identity.fingerprint == expected_fingerprint;
      const bool size_match = expected_size > 0 && candidate.identity.file_size == expected_size;
      const bool dimensions_match = expected_pixels.isValid() && candidate.identity.pixel_size.isValid() &&
                                    candidate.identity.pixel_size == expected_pixels;
      const bool name_match = QFileInfo(candidate.path).fileName().compare(
                                  original_name, Qt::CaseInsensitive) == 0;
      int score = 0;
      QString reason;
      if (fingerprint_match) {
        score = 4;
        reason = QStringLiteral("Content fingerprint matches");
      } else if (name_match && size_match && (dimensions_match || !expected_pixels.isValid())) {
        score = 3;
        reason = QStringLiteral("File name, size, and dimensions match");
      } else if (name_match && dimensions_match) {
        score = 2;
        reason = QStringLiteral("File name and dimensions match; size differs");
      } else if (name_match) {
        score = 1;
        reason = QStringLiteral("File name matches but source metadata does not");
      }
      if (score > best_score) {
        best_score = score;
        best_indexes = {index};
        best_reason = reason;
      } else if (score > 0 && score == best_score) {
        best_indexes.push_back(index);
      }
    }

    const bool safe = best_score >= 3 && best_indexes.size() == 1;
    const bool ambiguous = best_indexes.size() > 1;
    const auto candidate = best_indexes.isEmpty() ? Candidate{} : candidates.at(best_indexes.constFirst());
    entry.insert(QStringLiteral("candidatePath"), candidate.path);
    entry.insert(QStringLiteral("candidateFileSize"), candidate.identity.file_size);
    entry.insert(QStringLiteral("candidateWidth"), candidate.identity.pixel_size.width());
    entry.insert(QStringLiteral("candidateHeight"), candidate.identity.pixel_size.height());
    entry.insert(QStringLiteral("candidateFingerprint"), candidate.identity.fingerprint);
    entry.insert(QStringLiteral("matchState"),
                 safe ? QStringLiteral("verified")
                      : ambiguous ? QStringLiteral("ambiguous")
                                  : best_score > 0 ? QStringLiteral("metadata-mismatch")
                                                   : QStringLiteral("not-found"));
    entry.insert(
        QStringLiteral("matchReason"),
        ambiguous ? QStringLiteral("Multiple files match the stored source metadata; no file was selected.")
                  : best_score > 0 ? best_reason
                                   : QStringLiteral("No candidate matched the stored source identity."));
    entry.insert(QStringLiteral("safeToApply"), safe);
    if (safe) {
      ++safe_count;
    }
    plan.push_back(entry);
  }
  relink_directory_ = normalized_directory;
  relink_plan_ = plan;
  emit relinkChanged();
  setStatus(QStringLiteral("Verified %1 of %2 missing media instance%3 for relink.")
                .arg(safe_count)
                .arg(plan.size())
                .arg(plan.size() == 1 ? QString{} : QStringLiteral("s")));
  return !plan.isEmpty();
}

bool CarouselDocumentController::applyRelinkPlan() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  int safe_count = 0;
  for (const auto& value : relink_plan_) {
    if (value.toMap().value(QStringLiteral("safeToApply")).toBool()) {
      ++safe_count;
    }
  }
  if (safe_count == 0) {
    setStatus(QStringLiteral("No verified relink matches are ready to apply."));
    return false;
  }
  pushUndoState(QStringLiteral("Relink missing media"));
  int applied_count = 0;
  for (const auto& value : relink_plan_) {
    const auto entry = value.toMap();
    if (!entry.value(QStringLiteral("safeToApply")).toBool()) {
      continue;
    }
    const auto candidate_path = entry.value(QStringLiteral("candidatePath")).toString();
    const auto identity = source_file_identity(
        candidate_path,
        QSize(entry.value(QStringLiteral("candidateWidth")).toInt(),
              entry.value(QStringLiteral("candidateHeight")).toInt()));
    const auto target_kind = entry.value(QStringLiteral("targetKind")).toString();
    if (target_kind == QStringLiteral("item")) {
      const auto item_index = indexOfItem(entry.value(QStringLiteral("itemId")).toString());
      if (item_index < 0) {
        continue;
      }
      auto& item = items_[item_index];
      item.file_path = candidate_path;
      item.source_file_size = identity.file_size;
      item.source_modified_ms = identity.modified_ms;
      item.source_fingerprint = identity.fingerprint;
      item.preview_source.clear();
      item.preview_source_size = {};
      ++applied_count;
      continue;
    }
    MediaItem* media = nullptr;
    if (target_kind == QStringLiteral("group")) {
      if (auto* group = groupById(entry.value(QStringLiteral("groupId")).toString())) {
        media = &group->media;
      }
    } else if (auto* slide = slideAt(entry.value(QStringLiteral("boardIndex")).toInt())) {
      const auto slot = entry.value(QStringLiteral("slot")).toString();
      media = slot == QStringLiteral("secondary") ? &slide->secondary
            : slot == QStringLiteral("tertiary") ? &slide->tertiary
                                                   : &slide->primary;
    }
    if (media == nullptr) {
      continue;
    }
    media->file_path = candidate_path;
    media->source_file_size = identity.file_size;
    media->source_modified_ms = identity.modified_ms;
    if (identity.pixel_size.isValid()) {
      media->source_pixel_size = identity.pixel_size;
    }
    media->source_fingerprint = identity.fingerprint;
    ++applied_count;
  }
  relink_plan_.clear();
  relink_directory_.clear();
  emit relinkChanged();
  refreshPreviews();
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Relinked %1 missing media instance%2; existing crops were preserved.")
                .arg(applied_count)
                .arg(applied_count == 1 ? QString{} : QStringLiteral("s")));
  return applied_count > 0;
}

void CarouselDocumentController::clearRelinkPlan() {
  relink_plan_.clear();
  relink_directory_.clear();
  emit relinkChanged();
}

bool CarouselDocumentController::previewFontSubstitution(
    const QString& missing_family,
    const QString& replacement_family) {
  const auto source = normalized_text_font_family(missing_family);
  const auto replacement = normalized_text_font_family(replacement_family);
  const auto installed_fonts = QFontDatabase::families();
  if (source.isEmpty() || text_font_family_available(source, installed_fonts) ||
      !text_font_family_available(replacement, installed_fonts)) {
    setStatus(QStringLiteral("Choose one missing font and an installed replacement to preview."));
    return false;
  }

  QVariantList preview;
  for (const auto& item : items_) {
    if (item.kind != ItemKind::Text ||
        item.text_font_family.compare(source, Qt::CaseInsensitive) != 0) {
      continue;
    }
    auto substituted = item;
    substituted.text_font_family = replacement;
    const auto before_height = measuredTextHeight(item);
    const auto after_height = measuredTextHeight(substituted);
    preview.push_back(QVariantMap{
        {QStringLiteral("boardIndex"), slideIndexForItem(item)},
        {QStringLiteral("itemId"), item.id},
        {QStringLiteral("layerLabel"), summary_label(item)},
        {QStringLiteral("sourceFontFamily"), item.text_font_family},
        {QStringLiteral("replacementFontFamily"), replacement},
        {QStringLiteral("beforeHeight"), before_height},
        {QStringLiteral("afterHeight"), after_height},
        {QStringLiteral("heightDelta"), after_height - before_height},
        {QStringLiteral("frameHeight"), item.bounds.height()},
        {QStringLiteral("overflowBefore"), before_height > item.bounds.height() + 1.0},
        {QStringLiteral("overflowAfter"), after_height > item.bounds.height() + 1.0},
        {QStringLiteral("layoutChanged"), qAbs(after_height - before_height) > 0.5},
    });
  }
  if (preview.isEmpty()) {
    setStatus(QStringLiteral("No text layers use that missing font."));
    return false;
  }
  font_substitution_source_ = source;
  font_substitution_replacement_ = replacement;
  font_substitution_preview_ = preview;
  emit fontRecoveryChanged();
  setStatus(QStringLiteral("Previewing '%1' → '%2' on %3 text layer%4.")
                .arg(source, replacement)
                .arg(preview.size())
                .arg(preview.size() == 1 ? QString{} : QStringLiteral("s")));
  return true;
}

bool CarouselDocumentController::applyFontSubstitution() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (font_substitution_preview_.isEmpty() || font_substitution_source_.isEmpty() ||
      font_substitution_replacement_.isEmpty()) {
    setStatus(QStringLiteral("Preview a font substitution before applying it."));
    return false;
  }
  pushUndoState(QStringLiteral("Substitute missing font"));
  int applied_count = 0;
  for (auto& item : items_) {
    if (item.kind != ItemKind::Text ||
        item.text_font_family.compare(font_substitution_source_, Qt::CaseInsensitive) != 0) {
      continue;
    }
    if (item.original_font_family.isEmpty()) {
      item.original_font_family = item.text_font_family;
    }
    item.text_font_family = font_substitution_replacement_;
    ++applied_count;
  }
  const auto replacement = font_substitution_replacement_;
  clearFontSubstitutionPreview();
  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
  setStatus(QStringLiteral("Substituted %1 text layer%2 with '%3'; original font identity was retained.")
                .arg(applied_count)
                .arg(applied_count == 1 ? QString{} : QStringLiteral("s"))
                .arg(replacement));
  return applied_count > 0;
}

void CarouselDocumentController::clearFontSubstitutionPreview() {
  font_substitution_preview_.clear();
  font_substitution_source_.clear();
  font_substitution_replacement_.clear();
  emit fontRecoveryChanged();
}

void CarouselDocumentController::openFontManagement() {
  const auto font_book_path = QStringLiteral("/System/Applications/Font Book.app");
  if (QFileInfo::exists(font_book_path) &&
      QDesktopServices::openUrl(QUrl::fromLocalFile(font_book_path))) {
    setStatus(QStringLiteral("Opened Font Book. Install the missing face, then return to Carousel."));
    return;
  }
  QDesktopServices::openUrl(QUrl(QStringLiteral("https://support.apple.com/guide/font-book/welcome/mac")));
  setStatus(QStringLiteral("Opened the system font-management help route."));
}

