void CarouselDocumentController::setExportCustomPixelSize(int width, int height) {
  auto normalized_width = qBound(64, width, 16384);
  auto normalized_height = qBound(64, height, 16384);
  if (export_aspect_locked_) {
    const auto base_size = exportPixelSize();
    const auto ratio = static_cast<double>(base_size.width()) / qMax(1, base_size.height());
    const bool width_changed = normalized_width != export_custom_pixel_width_;
    const bool height_changed = normalized_height != export_custom_pixel_height_;
    if (height_changed && !width_changed) {
      normalized_width = qBound(64, qRound(normalized_height * ratio), 16384);
    } else {
      normalized_height = qBound(64, qRound(normalized_width / ratio), 16384);
    }
  }
  if (export_custom_pixel_width_ == normalized_width &&
      export_custom_pixel_height_ == normalized_height &&
      export_size_mode_ == QStringLiteral("custom")) {
    return;
  }
  pushUndoState(QStringLiteral("Change custom export size"), true);
  export_custom_pixel_width_ = normalized_width;
  export_custom_pixel_height_ = normalized_height;
  export_size_mode_ = QStringLiteral("custom");
  emit exportSettingsChanged();
  emitCanvasStateChanged(false);
  setStatus(QStringLiteral("Custom export set to %1 × %2 px.")
                .arg(normalized_width)
                .arg(normalized_height));
}

void CarouselDocumentController::setExportAspectLocked(bool locked) {
  if (export_aspect_locked_ == locked) {
    return;
  }
  pushUndoState(QStringLiteral("Change export aspect lock"));
  export_aspect_locked_ = locked;
  if (locked && export_size_mode_ == QStringLiteral("custom")) {
    const auto base_size = exportPixelSize();
    const auto ratio = static_cast<double>(base_size.width()) / qMax(1, base_size.height());
    export_custom_pixel_height_ =
        qBound(64, qRound(export_custom_pixel_width_ / ratio), 16384);
  }
  emit exportSettingsChanged();
  emitCanvasStateChanged(false);
  setStatus(locked ? QStringLiteral("Custom export aspect locked to the document.")
                   : QStringLiteral("Custom export aspect unlocked."));
}

