QString CarouselDocumentController::templateNameForIndex(int index) const {
  const auto* group = groupForIndex(index);
  if (group != nullptr) {
    return group->kind == GroupKind::HorizontalPair ? QStringLiteral("linked-horizontal-pair")
                                                    : QStringLiteral("single");
  }

  const auto* slide = slideAt(index);
  if (slide == nullptr) {
    return QStringLiteral("single");
  }
  if (slide->template_kind == SlideTemplate::SplitPair) {
    return QStringLiteral("split-pair");
  }
  if (slide->template_kind == SlideTemplate::StackedTriptych) {
    return QStringLiteral("stacked-triptych");
  }
  return QStringLiteral("single");
}

QString CarouselDocumentController::fitModeName(FitMode fit_mode) {
  return fit_mode == FitMode::Contain ? QStringLiteral("contain") : QStringLiteral("cover");
}

CarouselDocumentController::FitMode CarouselDocumentController::fitModeFromName(const QString& fit_mode) const {
  return fit_mode == QStringLiteral("contain") ? FitMode::Contain : FitMode::Cover;
}

QString CarouselDocumentController::groupKindName(GroupKind kind) {
  switch (kind) {
    case GroupKind::HorizontalPair:
      return QStringLiteral("linked-horizontal-pair");
    case GroupKind::None:
      break;
  }
  return QStringLiteral("none");
}

int CarouselDocumentController::spanForGroupKind(GroupKind kind) const {
  switch (kind) {
    case GroupKind::HorizontalPair:
      return 2;
    case GroupKind::None:
      break;
  }
  return 0;
}

CarouselDocumentController::GroupKind CarouselDocumentController::groupKindFromTemplate(
    const QString& template_kind) const {
  if (template_kind == QStringLiteral("linked-horizontal-pair")) {
    return GroupKind::HorizontalPair;
  }
  return GroupKind::None;
}

bool CarouselDocumentController::currentSelectionIsLinked() const {
  return groupForIndex(current_index_) != nullptr;
}

QString CarouselDocumentController::currentActiveSlot() const {
  const auto* slide = slideAt(current_index_);
  if (slide == nullptr) {
    return QStringLiteral("primary");
  }
  if (slide->template_kind == SlideTemplate::Single) {
    return QStringLiteral("primary");
  }
  if (slide->template_kind == SlideTemplate::SplitPair && active_slot_ == QStringLiteral("tertiary")) {
    return QStringLiteral("primary");
  }
  return active_slot_;
}

QSize CarouselDocumentController::currentMediaViewportSize() const {
  if (currentSelectionIsLinked()) {
    if (const auto* group = groupForIndex(current_index_)) {
      const auto slide_size = exportPixelSize();
      return QSize(slide_size.width() * qMax(1, group->span), slide_size.height());
    }
    return exportPixelSize();
  }

  const auto* slide = slideAt(current_index_);
  if (slide == nullptr) {
    return exportPixelSize();
  }

  const auto slide_size = exportPixelSize();
  switch (slide->template_kind) {
    case SlideTemplate::SplitPair:
      return QSize(slide_size.width() / 2, slide_size.height());
    case SlideTemplate::StackedTriptych:
      return QSize(slide_size.width(), slide_size.height() / 3);
    case SlideTemplate::Single:
      break;
  }
  return slide_size;
}

QSize CarouselDocumentController::effectiveMediaSourceSize(const MediaItem& media) const {
  if (media.type == MediaType::Video) {
    return probeVideoSize(media.file_path);
  }
  if (media.type != MediaType::Image || media.file_path.trimmed().isEmpty()) {
    return {};
  }

  QImageReader reader(media.file_path);
  QSize source_size = reader.size();
  bool using_decoded_size = false;
  if (!source_size.isValid()) {
    QImage decoded;
    if (decodeEditedImage(media, &decoded, true, kPreviewLongEdge * 2)) {
      source_size = decoded.size();
      using_decoded_size = true;
    }
  }
  if (!source_size.isValid()) {
    return {};
  }

  if (!using_decoded_size && media.crop_source == QStringLiteral("edit") &&
      (carousel_has_explicit_crop_rect(media.recipe_state) ||
      media.recipe_state.crop_preset != QStringLiteral("Original") ||
      !qFuzzyCompare(media.recipe_state.crop_zoom, 1.0))) {
    source_size =
        carousel_crop_rect_for_image(source_size, media.recipe_state).size();
  }
  return source_size;
}

qreal CarouselDocumentController::normalizedAspectRatio(const CanvasItem& item) const {
  if (item.source_size.width() > 0.0 && item.source_size.height() > 0.0) {
    return item.source_size.width() / item.source_size.height();
  }
  if (item.bounds.width() > 0.0 && item.bounds.height() > 0.0) {
    return item.bounds.width() / item.bounds.height();
  }
  return 1.0;
}

qreal CarouselDocumentController::measuredTextHeight(const CanvasItem& item) const {
  auto resolved_item = item;
  const auto resolved_text = resolvedTextForItem(item);
  resolved_item.text_spans = remap_rich_text_spans(item.text, resolved_text, item.text_spans);
  resolved_item.text = resolved_text;
  return layout_carousel_text(resolved_item, resolved_item.bounds.width()).full_height;
}

void CarouselDocumentController::updateTextFit(
    CanvasItem* item,
    bool allow_content_frame_resize) {
  if (item == nullptr || item->kind != ItemKind::Text) {
    return;
  }
  const auto reflow_stack = [this, item]() {
    relayoutConstraintStackForItem(item->id);
  };
  if (item->text_fit_mode == QStringLiteral("content")) {
    if (allow_content_frame_resize) {
      const auto center = item->bounds.center();
      item->bounds.setHeight(measuredTextHeight(*item));
      item->bounds.moveCenter(center);
    }
    reflow_stack();
    return;
  }
  if (item->text_fit_mode != QStringLiteral("auto")) {
    reflow_stack();
    return;
  }

  const auto minimum = qBound(
      kMinTextPointSize,
      item->text_fit_min_point_size,
      qMax(kMinTextPointSize, item->text_fit_max_point_size));
  const auto maximum = qBound(minimum, item->text_fit_max_point_size, 400.0);
  item->text_fit_min_point_size = minimum;
  item->text_fit_max_point_size = maximum;
  item->text_point_size = maximum;
  if (measuredTextHeight(*item) <= item->bounds.height() + 1.0) {
    reflow_stack();
    return;
  }
  item->text_point_size = minimum;
  if (measuredTextHeight(*item) > item->bounds.height() + 1.0) {
    reflow_stack();
    return;
  }
  double low = minimum;
  double high = maximum;
  for (int iteration = 0; iteration < 24; ++iteration) {
    const auto candidate_size = (low + high) * 0.5;
    item->text_point_size = candidate_size;
    if (measuredTextHeight(*item) <= item->bounds.height() + 1.0) {
      low = candidate_size;
    } else {
      high = candidate_size;
    }
  }
  item->text_point_size = low;
  reflow_stack();
}

QString CarouselDocumentController::textFitState(const CanvasItem& item) const {
  const auto point_size = qRound(item.text_point_size);
  const auto overflow = textVerticallyOverflows(item);
  if (item.text_fit_mode == QStringLiteral("auto")) {
    if (overflow) {
      return QStringLiteral("Minimum %1 pt still overflows; enlarge the frame or shorten the copy.")
          .arg(qRound(item.text_fit_min_point_size));
    }
    if (item.text_point_size + 0.1 < item.text_fit_max_point_size) {
      return QStringLiteral("Fitted from %1 pt to %2 pt.")
          .arg(qRound(item.text_fit_max_point_size))
          .arg(point_size);
    }
    return QStringLiteral("Fits at the %1 pt maximum.").arg(point_size);
  }
  if (item.text_fit_mode == QStringLiteral("fixed")) {
    return overflow
               ? QStringLiteral("Fixed at %1 pt; preflight will report overflow.").arg(point_size)
               : QStringLiteral("Fixed at %1 pt and fits the frame.").arg(point_size);
  }
  return QStringLiteral("Frame follows the content at %1 pt.").arg(point_size);
}

QVariantMap CarouselDocumentController::textLayoutPresentation(
    const CanvasItem& item,
    const QString& resolved_text) const {
  auto resolved_item = item;
  resolved_item.text_spans = remap_rich_text_spans(item.text, resolved_text, item.text_spans);
  resolved_item.text = resolved_text;
  const auto layout = layout_carousel_text(resolved_item, resolved_item.bounds.width());
  const auto total_inset = qMax(0.0, item.text_padding) + qMax(0.0, item.text_inset);
  const auto available_height = qMax(0.0, item.bounds.height() - total_inset * 2.0);
  double vertical_offset = 0.0;
  const auto visible_height = qMin(available_height, layout.visible_height);
  if (item.text_vertical_alignment == QStringLiteral("bottom")) {
    vertical_offset = qMax(0.0, available_height - visible_height);
  } else if (item.text_vertical_alignment != QStringLiteral("top")) {
    vertical_offset = qMax(0.0, (available_height - visible_height) * 0.5);
  }
  QVariantList lines;
  lines.reserve(layout.visible_lines.size());
  for (const auto& line : layout.visible_lines) {
    QVariantList segments;
    segments.reserve(line.segment_texts.size());
    for (int index = 0; index < line.segment_texts.size(); ++index) {
      const auto& style = line.segment_styles.at(index);
      segments.push_back(QVariantMap{
          {QStringLiteral("text"), line.segment_texts.at(index)},
          {QStringLiteral("x"), total_inset + line.segment_x.at(index)},
          {QStringLiteral("width"), line.segment_width.at(index)},
          {QStringLiteral("color"), style.color.isEmpty() ? item.text_color : style.color},
          {QStringLiteral("fontWeight"), effective_rich_text_weight(style, item)},
          {QStringLiteral("italic"), effective_rich_text_italic(style, item)},
          {QStringLiteral("underline"), item.text_underline || !style.link.isEmpty()},
          {QStringLiteral("strikethrough"), item.text_strikethrough},
          {QStringLiteral("superscript"), style.superscript},
          {QStringLiteral("pointSizeScale"), style.superscript ? 0.72 : 1.0},
          {QStringLiteral("baselineShift"), style.superscript ? -item.text_point_size * 0.24 : 0.0},
          {QStringLiteral("emphasis"), style.emphasis},
          {QStringLiteral("link"), style.link},
      });
    }
    lines.push_back(QVariantMap{
        {QStringLiteral("text"), line.text},
        {QStringLiteral("x"), total_inset + line.x},
        {QStringLiteral("y"), total_inset + vertical_offset + line.y},
        {QStringLiteral("height"), line.height},
        {QStringLiteral("segments"), segments},
    });
  }
  return {{QStringLiteral("lines"), lines},
          {QStringLiteral("verticalOverflow"),
           layout.maximum_line_overflow ||
               layout.full_height > item.bounds.height() + 1.0}};
}

QVariantList CarouselDocumentController::textLayoutLines(
    const CanvasItem& item) const {
  return textLayoutPresentation(item, resolvedTextForItem(item))
      .value(QStringLiteral("lines"))
      .toList();
}

bool CarouselDocumentController::textVerticallyOverflows(
    const CanvasItem& item) const {
  auto resolved_item = item;
  const auto resolved_text = resolvedTextForItem(item);
  resolved_item.text_spans = remap_rich_text_spans(item.text, resolved_text, item.text_spans);
  resolved_item.text = resolved_text;
  const auto layout = layout_carousel_text(resolved_item, resolved_item.bounds.width());
  return layout.maximum_line_overflow || layout.full_height > item.bounds.height() + 1.0;
}

QSize CarouselDocumentController::probeVideoSize(const QString& file_path) const {
  const auto ffprobe = QStandardPaths::findExecutable(QStringLiteral("ffprobe"));
  if (ffprobe.isEmpty()) {
    return {};
  }

  QProcess process;
  process.start(
      ffprobe,
      {
          QStringLiteral("-v"),
          QStringLiteral("error"),
          QStringLiteral("-select_streams"),
          QStringLiteral("v:0"),
          QStringLiteral("-show_entries"),
          QStringLiteral("stream=width,height"),
          QStringLiteral("-of"),
          QStringLiteral("csv=p=0:s=x"),
          file_path,
      });
  if (!waitForExportProcess(&process, 3000)) {
    return {};
  }

  const auto parts = QString::fromUtf8(process.readAllStandardOutput()).trimmed().split('x');
  if (parts.size() != 2) {
    return {};
  }
  return {parts[0].toInt(), parts[1].toInt()};
}

double CarouselDocumentController::probeVideoDuration(const QString& file_path) const {
  const auto ffprobe = QStandardPaths::findExecutable(QStringLiteral("ffprobe"));
  if (ffprobe.isEmpty() || file_path.trimmed().isEmpty()) {
    return 0.0;
  }
  QProcess process;
  process.start(
      ffprobe,
      {QStringLiteral("-v"), QStringLiteral("error"),
       QStringLiteral("-show_entries"), QStringLiteral("format=duration"),
       QStringLiteral("-of"), QStringLiteral("default=noprint_wrappers=1:nokey=1"),
       file_path});
  if (!waitForExportProcess(&process, 3000)) {
    return 0.0;
  }
  bool ok = false;
  const auto duration = QString::fromUtf8(process.readAllStandardOutput()).trimmed().toDouble(&ok);
  return ok ? qMax(0.0, duration) : 0.0;
}

bool CarouselDocumentController::hasFreeformItemsOnSlide(int index) const {
  const auto rect = slideRectInDocument(index);
  for (const auto& item : items_) {
    if (item.hidden) {
      continue;
    }
    if (rect.intersects(item.bounds)) {
      return true;
    }
  }
  return false;
}

bool CarouselDocumentController::exportVideoSlide(
    const MediaItem& media,
    const QString& output_path,
    const QSize& target_size,
    int slide_index) const {
  const auto ffmpeg = QStandardPaths::findExecutable(QStringLiteral("ffmpeg"));
  if (ffmpeg.isEmpty()) {
    return false;
  }

  const auto source_size = probeVideoSize(media.file_path);
  if (!source_size.isValid()) {
    return false;
  }

  const double base_scale = media.fit_mode == FitMode::Contain
                                ? qMin(
                                      static_cast<double>(target_size.width()) / static_cast<double>(source_size.width()),
                                      static_cast<double>(target_size.height()) / static_cast<double>(source_size.height()))
                                : qMax(
                                      static_cast<double>(target_size.width()) / static_cast<double>(source_size.width()),
                                      static_cast<double>(target_size.height()) / static_cast<double>(source_size.height()));
  const int scaled_width = qMax(1, static_cast<int>(qRound(source_size.width() * base_scale * media.scale)));
  const int scaled_height = qMax(1, static_cast<int>(qRound(source_size.height() * base_scale * media.scale)));
  const int free_x = target_size.width() - scaled_width;
  const int free_y = target_size.height() - scaled_height;
  const auto resolved_offset_x = media.manual_crop
                                     ? media.offset_x
                                     : smart_crop_offset(media.focal_x, target_size.width(), scaled_width);
  const auto resolved_offset_y = media.manual_crop
                                     ? media.offset_y
                                     : smart_crop_offset(media.focal_y, target_size.height(), scaled_height);
  const int translate_x =
      static_cast<int>(qRound(static_cast<double>(free_x) * ((resolved_offset_x + 1.0) / 2.0)));
  const int translate_y =
      static_cast<int>(qRound(static_cast<double>(free_y) * ((resolved_offset_y + 1.0) / 2.0)));

  const auto base_filter = QStringLiteral(
                          "scale=%1:%2:flags=lanczos[fg];color=c=black:s=%3x%4[bg];"
                          "[bg][fg]overlay=%5:%6:format=auto:shortest=1,setsar=1")
                          .arg(scaled_width)
                          .arg(scaled_height)
                          .arg(target_size.width())
                          .arg(target_size.height())
                          .arg(translate_x)
                          .arg(translate_y);

  const auto source_duration = media.video_duration_seconds > 0.0
                                   ? media.video_duration_seconds
                                   : probeVideoDuration(media.file_path);
  const auto trim_in = qBound(0.0, media.video_trim_in_seconds, qMax(0.0, source_duration - 0.05));
  const auto trim_out = qBound(
      trim_in + 0.05,
      media.video_trim_out_seconds > trim_in ? media.video_trim_out_seconds : source_duration,
      qMax(trim_in + 0.05, source_duration));
  const auto trim_duration = qMax(0.05, trim_out - trim_in);
  QStringList arguments{QStringLiteral("-y")};
  if (trim_in > 0.0) {
    arguments << QStringLiteral("-ss") << QString::number(trim_in, 'f', 3);
  }
  arguments << QStringLiteral("-i") << media.file_path;
  QString overlay_path;
  if (hasFreeformItemsOnSlide(slide_index)) {
    overlay_path = QDir(previewsRoot()).filePath(
        QStringLiteral("video-overlay-%1-%2.png").arg(session_id_).arg(slide_index));
    QDir().mkpath(QFileInfo(overlay_path).absolutePath());
    QImageWriter overlay_writer(overlay_path, "png");
    if (!overlay_writer.write(renderSlideOverlayImage(slide_index, target_size))) {
      return false;
    }
    arguments << QStringLiteral("-loop") << QStringLiteral("1") << QStringLiteral("-i") << overlay_path;
    arguments << QStringLiteral("-filter_complex")
              << base_filter +
                     QStringLiteral(
                         "[base];[1:v]format=rgba[ov];[base][ov]overlay=0:0:format=auto:shortest=1[out]")
              << QStringLiteral("-map") << QStringLiteral("[out]") << QStringLiteral("-shortest");
  } else {
    arguments << QStringLiteral("-vf") << base_filter
              << QStringLiteral("-map") << QStringLiteral("0:v:0");
  }
  arguments << QStringLiteral("-t") << QString::number(trim_duration, 'f', 3);
  if (media.video_audio_policy == QStringLiteral("preserve")) {
    arguments << QStringLiteral("-map") << QStringLiteral("0:a?")
              << QStringLiteral("-c:a") << QStringLiteral("aac");
  } else {
    arguments << QStringLiteral("-an");
  }
  arguments << QStringLiteral("-c:v") << QStringLiteral("libx264")
            << QStringLiteral("-pix_fmt") << QStringLiteral("yuv420p") << output_path;
  QProcess process;
  process.start(ffmpeg, arguments);
  const bool succeeded = waitForExportProcess(&process, -1);
  if (!overlay_path.isEmpty()) {
    QFile::remove(overlay_path);
  }
  return succeeded;
}

QImage CarouselDocumentController::renderSlideBaseImage(int index, const QSize& size, bool preview) const {
  QImage canvas(size, QImage::Format_ARGB32_Premultiplied);
  canvas.setColorSpace(output_color_space_for_name(outputColorSpaceForSlide(index)));
  const auto* slide = slideAt(index);
  canvas.fill(Qt::transparent);
  QPainter painter(&canvas);
  painter.setRenderHint(QPainter::Antialiasing, true);
  painter.setRenderHint(QPainter::SmoothPixmapTransform, true);
  if (slide != nullptr && normalized_background_kind(slide->background_kind) == QStringLiteral("transparent")) {
    // Preserve alpha. The composer supplies its own checkerboard behind this preview.
  } else if (slide != nullptr && normalized_background_kind(slide->background_kind) != QStringLiteral("solid")) {
    const auto kind = normalized_background_kind(slide->background_kind);
    QLinearGradient gradient;
    if (kind == QStringLiteral("linear-horizontal")) {
      gradient = QLinearGradient(QPointF(0.0, 0.0), QPointF(static_cast<qreal>(size.width()), 0.0));
    } else {
      gradient = QLinearGradient(QPointF(0.0, 0.0), QPointF(0.0, static_cast<qreal>(size.height())));
    }
    gradient.setColorAt(0.0, QColor(slide->background_color));
    gradient.setColorAt(1.0, QColor(slide->background_secondary_color));
    painter.fillRect(canvas.rect(), QBrush(gradient));
  } else {
    painter.fillRect(
        canvas.rect(),
        QColor(slide != nullptr ? slide->background_color : QStringLiteral("#fbf7f1")));
  }

  if (const auto* group = groupForIndex(index)) {
    const QSize virtual_size = QSize(size.width() * group->span, size.height());
    const QPoint origin((index - group->start_index) * size.width(), 0);
    renderMediaIntoRect(&painter, QRect(QPoint(0, 0), size), group->media, virtual_size, origin, preview);

    if (preview && !group->edit_spread) {
      QPen guide_pen(QColor(QStringLiteral("#f0b35d")));
      guide_pen.setStyle(Qt::DashLine);
      guide_pen.setWidth(2);
      painter.setPen(guide_pen);
      painter.drawRect(canvas.rect().adjusted(2, 2, -2, -2));
      painter.setPen(QColor(QStringLiteral("#6e5a49")));
      painter.setFont(QFont(QStringLiteral("Menlo"), 14, QFont::DemiBold));
      painter.drawText(canvas.rect().adjusted(14, 14, -14, -14), Qt::AlignTop | Qt::AlignLeft,
                       QStringLiteral("%1 / %2").arg(index - group->start_index + 1).arg(group->span));
    }
    return canvas;
  }

  if (slide == nullptr) {
    return canvas;
  }

  if (slide->template_kind == SlideTemplate::SplitPair) {
    const QRect left_rect(0, 0, size.width() / 2, size.height());
    const QRect right_rect(left_rect.width(), 0, size.width() - left_rect.width(), size.height());
    renderMediaIntoRect(&painter, left_rect, slide->primary, left_rect.size(), QPoint(0, 0), preview);
    renderMediaIntoRect(&painter, right_rect, slide->secondary, right_rect.size(), QPoint(0, 0), preview);
    if (preview) {
      painter.setPen(QPen(QColor(QStringLiteral("#e8b35d")), 2));
      painter.drawLine(left_rect.right(), 0, left_rect.right(), size.height());
    }
    return canvas;
  }

  if (slide->template_kind == SlideTemplate::StackedTriptych) {
    const int top_height = size.height() / 3;
    const int middle_height = size.height() / 3;
    const QRect top_rect(0, 0, size.width(), top_height);
    const QRect middle_rect(0, top_rect.bottom() + 1, size.width(), middle_height);
    const QRect bottom_rect(0, middle_rect.bottom() + 1, size.width(), size.height() - top_height - middle_height);
    renderMediaIntoRect(&painter, top_rect, slide->primary, top_rect.size(), QPoint(0, 0), preview);
    renderMediaIntoRect(&painter, middle_rect, slide->secondary, middle_rect.size(), QPoint(0, 0), preview);
    renderMediaIntoRect(&painter, bottom_rect, slide->tertiary, bottom_rect.size(), QPoint(0, 0), preview);
    if (preview) {
      painter.setPen(QPen(QColor(QStringLiteral("#e8b35d")), 2));
      painter.drawLine(0, top_rect.bottom(), size.width(), top_rect.bottom());
      painter.drawLine(0, middle_rect.bottom(), size.width(), middle_rect.bottom());
    }
    return canvas;
  }

  renderMediaIntoRect(&painter, QRect(QPoint(0, 0), size), slide->primary, size, QPoint(0, 0), preview);
  return canvas;
}

QImage CarouselDocumentController::renderSlideImage(int index, const QSize& size, bool preview) const {
  if (exportCancellationRequested()) return {};
  auto canvas = renderSlideBaseImage(index, size, preview);
  QPainter painter(&canvas);
  painter.setRenderHint(QPainter::Antialiasing, true);
  painter.setRenderHint(QPainter::TextAntialiasing, true);
  painter.setRenderHint(QPainter::SmoothPixmapTransform, true);

  for (const auto& item : items_) {
    if (exportCancellationRequested()) return {};
    if (item.kind != ItemKind::Brush) {
      renderItemIntoSlide(&painter, item, index, size, preview);
    }
  }

  QImage brush_overlay(size, QImage::Format_ARGB32_Premultiplied);
  brush_overlay.fill(Qt::transparent);
  QPainter brush_painter(&brush_overlay);
  brush_painter.setRenderHint(QPainter::Antialiasing, true);
  for (const auto& item : items_) {
    if (exportCancellationRequested()) return {};
    if (item.kind == ItemKind::Brush) {
      renderBrushItem(&brush_painter, item, index, size);
    }
  }
  brush_painter.end();
  painter.drawImage(QPoint(0, 0), brush_overlay);
  canvas.setColorSpace(output_color_space_for_name(outputColorSpaceForSlide(index)));
  return canvas;
}

QImage CarouselDocumentController::renderSlideOverlayImage(int index, const QSize& size) const {
  if (exportCancellationRequested()) return {};
  QImage overlay(size, QImage::Format_ARGB32_Premultiplied);
  overlay.fill(Qt::transparent);
  QPainter painter(&overlay);
  painter.setRenderHint(QPainter::Antialiasing, true);
  painter.setRenderHint(QPainter::TextAntialiasing, true);
  painter.setRenderHint(QPainter::SmoothPixmapTransform, true);
  for (const auto& item : items_) {
    if (exportCancellationRequested()) return {};
    if (item.kind != ItemKind::Brush) {
      renderItemIntoSlide(&painter, item, index, size, false);
    }
  }
  for (const auto& item : items_) {
    if (exportCancellationRequested()) return {};
    if (item.kind == ItemKind::Brush) {
      renderBrushItem(&painter, item, index, size);
    }
  }
  painter.end();
  overlay.setColorSpace(output_color_space_for_name(outputColorSpaceForSlide(index)));
  return overlay;
}

QString CarouselDocumentController::outputColorSpaceForSlide(int index) const {
  Q_UNUSED(index);
  return export_color_space_;
}

QString CarouselDocumentController::exportBaseNameForSlide(int index) const {
  const auto* slide = slideAt(index);
  auto resolved = export_filename_pattern_;
  resolved.replace(QStringLiteral("{document}"), sanitized_filename_component(document_name_));
  resolved.replace(
      QStringLiteral("{board_number}"),
      QStringLiteral("%1").arg(index + 1, 2, 10, QLatin1Char('0')));
  resolved.replace(
      QStringLiteral("{board_role}"),
      sanitized_filename_component(slide != nullptr ? slide->board_role : QStringLiteral("content")));
  resolved.replace(QStringLiteral("{ratio}"), document_format_);
  resolved.replace(QStringLiteral("{version}"), QStringLiteral("v%1").arg(export_version_));
  resolved.replace(
      QStringLiteral("{date}"),
      QDate::currentDate().toString(QStringLiteral("yyyy-MM-dd")));
  return sanitized_filename_component(resolved);
}

QImage CarouselDocumentController::renderVideoPlaceholder(const MediaItem& media, const QSize& size) const {
  QImage canvas(size, QImage::Format_ARGB32_Premultiplied);
  canvas.fill(QColor(QStringLiteral("#0d1419")));
  QPainter painter(&canvas);
  painter.setRenderHint(QPainter::Antialiasing, true);

  QRect frame = canvas.rect().adjusted(size.width() / 10, size.height() / 5, -size.width() / 10, -size.height() / 5);
  painter.setPen(QPen(QColor(QStringLiteral("#69cad8")), 3));
  painter.drawRoundedRect(frame, 18, 18);
  const QPointF points[] = {
      QPointF(frame.center().x() - 36, frame.center().y() - 48),
      QPointF(frame.center().x() - 36, frame.center().y() + 48),
      QPointF(frame.center().x() + 54, frame.center().y()),
  };
  painter.setBrush(QColor(QStringLiteral("#69cad8")));
  painter.drawPolygon(points, 3);

  painter.setPen(QColor(QStringLiteral("#eef4f6")));
  painter.setFont(QFont(QStringLiteral("Avenir Next"), qMax(14, size.width() / 18), QFont::Medium));
  painter.drawText(
      canvas.rect().adjusted(24, size.height() - 148, -24, -24),
      Qt::AlignHCenter | Qt::TextWordWrap,
      media.display_label.isEmpty() ? QStringLiteral("Video") : media.display_label);
  painter.setPen(QColor(QStringLiteral("#8ea2ae")));
  painter.setFont(QFont(QStringLiteral("Menlo"), qMax(11, size.width() / 28)));
  painter.drawText(
      canvas.rect().adjusted(24, size.height() - 72, -24, -24),
      Qt::AlignHCenter,
      QStringLiteral("Video export uses ffmpeg"));
  return canvas;
}

bool CarouselDocumentController::decodeEditedImage(
    const MediaItem& media,
    QImage* image,
    bool preview,
    int max_edge) const {
  if (media.type != MediaType::Image) {
    return false;
  }
  if (media.file_path.trimmed().isEmpty()) {
    return false;
  }

  const QFileInfo source_info(media.file_path);
  const auto recipe_hash = QString::fromLatin1(
      QCryptographicHash::hash(media.adjustment_patch_json.toUtf8(), QCryptographicHash::Sha256).toHex());
  const auto cache_key = decoded_image_cache_key(source_info, preview ? max_edge : 0) +
                         QStringLiteral("|carousel-edit|") + recipe_hash +
                         QStringLiteral("|") + media.crop_source;
  if (find_decoded_image_cache_entry(cache_key, image)) {
    return true;
  }

  auto metadata = photo_editor::pipeline::DecodedImageMetadata{};
  auto decode_state = media.recipe_state;
  if (media.crop_source == QStringLiteral("original")) {
    decode_state.raw_input_transform_enabled = false;
  }
  if (!decode_source_image(
          media.file_path,
          image,
          preview ? max_edge : 0,
          decode_state,
          &metadata)) {
    return false;
  }

  if (image->isNull()) {
    return false;
  }

  if (media.crop_source != QStringLiteral("original")) {
    auto device_profile =
        std::optional<
            photo_editor::pipeline::AssetIdentifier>{};
    if (!media.recipe_state.export_icc_profile_asset
             .asset_id.trimmed().isEmpty()) {
      device_profile =
          photo_editor::pipeline::AssetIdentifier{
              media.recipe_state.export_icc_profile_asset
                  .asset_id.trimmed().toStdString(),
          };
    } else if (!media.recipe_state.export_icc_profile_asset
                    .payload_sha256.trimmed().isEmpty()) {
      device_profile =
          photo_editor::pipeline::AssetIdentifier{
              "sha256:" +
              media.recipe_state.export_icc_profile_asset
                  .payload_sha256.trimmed().toStdString(),
          };
    }
    const auto output_name =
        media.recipe_state.output_color_space
            .trimmed().toLower();
    const auto admission =
        RenderPlanStore::shared().admit(
            media.source_fingerprint.trimmed().isEmpty()
                ? QFileInfo(media.file_path)
                      .absoluteFilePath()
                : media.source_fingerprint,
            media.file_path,
            media.recipe_state,
            image->size(),
            photo_editor::pipeline::RenderPurpose::
                Carousel,
            output_name.contains(
                QStringLiteral("display p3"))
                ? photo_editor::pipeline::
                      DisplayRenderingTarget::
                          DisplayP3Simulation
                : photo_editor::pipeline::
                      DisplayRenderingTarget::
                          SrgbSimulation,
            device_profile,
            &metadata,
            recipe_hash);
    if (!admission.admitted ||
        !apply_color_adjustments(
            image,
            media.recipe_state,
            &metadata,
            &*admission.plan)) {
      return false;
    }
  } else {
    apply_output_color_space_transform(
        image, media.recipe_state.output_color_space);
  }
  if (media.crop_source == QStringLiteral("edit") &&
      (carousel_has_explicit_crop_rect(media.recipe_state) ||
       media.recipe_state.crop_preset != QStringLiteral("Original") ||
       !qFuzzyCompare(media.recipe_state.crop_zoom, 1.0))) {
    *image =
        image->copy(carousel_crop_rect_for_image(
            image->size(), media.recipe_state));
  }
  if (!image->isNull()) {
    insert_decoded_image_cache_entry(cache_key, *image);
  }
  return !image->isNull();
}

bool CarouselDocumentController::decodeEditedImage(
    const CanvasItem& item,
    QImage* image,
    bool preview,
    int max_edge) const {
  if (item.kind != ItemKind::Image) {
    return false;
  }

  MediaItem media;
  media.type = MediaType::Image;
  media.file_path = item.file_path;
  media.recipe_state = item.recipe_state;
  media.adjustment_patch_json = item.adjustment_patch_json;
  media.crop_source = item.media_crop_source;
  return decodeEditedImage(media, image, preview, max_edge);
}

void CarouselDocumentController::renderMediaIntoRect(
    QPainter* painter,
    const QRect& destination_rect,
    const MediaItem& media,
    const QSize& virtual_canvas_size,
    const QPoint& segment_origin,
    bool preview) const {
  painter->save();
  painter->setClipRect(destination_rect);

  if (media.type == MediaType::Empty || media.file_path.isEmpty()) {
    if (!preview) {
      painter->restore();
      return;
    }
    painter->setPen(QPen(QColor(QStringLiteral("#d4c4b4")), 2, Qt::DashLine));
    painter->drawRoundedRect(destination_rect.adjusted(8, 8, -8, -8), 16, 16);
    painter->setPen(QColor(QStringLiteral("#8f7e6d")));
    painter->setFont(QFont(QStringLiteral("Menlo"), qMax(10, destination_rect.width() / 28)));
    painter->drawText(destination_rect.adjusted(18, 18, -18, -18), Qt::AlignCenter | Qt::TextWordWrap,
                      QStringLiteral("Add media"));
    painter->restore();
    return;
  }

  if (media.type == MediaType::Video) {
    painter->fillRect(destination_rect, QColor(QStringLiteral("#fffdf8")));
    const auto placeholder = renderVideoPlaceholder(media, destination_rect.size());
    painter->drawImage(destination_rect.topLeft(), placeholder);
    painter->restore();
    return;
  }

  QImage source_image;
  if (!decodeEditedImage(media, &source_image, preview, kPreviewLongEdge * 2)) {
    painter->setPen(QColor(QStringLiteral("#a56a5e")));
    painter->drawText(destination_rect.adjusted(18, 18, -18, -18), Qt::AlignCenter | Qt::TextWordWrap,
                      QStringLiteral("Unable to read image"));
    painter->restore();
    return;
  }

  const auto selected_preview = preview && &media == currentEditableMedia();
  const auto preview_mode = selected_preview ? cutout_preview_mode_ : QStringLiteral("result");
  if (media.cutout_enabled) {
    if (preview_mode == QStringLiteral("black")) {
      painter->fillRect(destination_rect, Qt::black);
    } else if (preview_mode == QStringLiteral("white")) {
      painter->fillRect(destination_rect, Qt::white);
    }
    source_image = apply_subject_cutout(
        std::move(source_image),
        media.cutout_mask_data,
        media.cutout_mask_width,
        media.cutout_mask_height,
        media.cutout_feather,
        media.cutout_expand,
        media.cutout_edge_contrast,
        preview_mode);
  }

  const double base_scale = media.fit_mode == FitMode::Contain
                                ? qMin(
                                      static_cast<double>(virtual_canvas_size.width()) / static_cast<double>(source_image.width()),
                                      static_cast<double>(virtual_canvas_size.height()) / static_cast<double>(source_image.height()))
                                : qMax(
                                      static_cast<double>(virtual_canvas_size.width()) / static_cast<double>(source_image.width()),
                                      static_cast<double>(virtual_canvas_size.height()) / static_cast<double>(source_image.height()));
  const int scaled_width = qMax(1, static_cast<int>(qRound(source_image.width() * base_scale * media.scale)));
  const int scaled_height = qMax(1, static_cast<int>(qRound(source_image.height() * base_scale * media.scale)));
  const int free_x = virtual_canvas_size.width() - scaled_width;
  const int free_y = virtual_canvas_size.height() - scaled_height;
  const auto resolved_offset_x = media.manual_crop
                                     ? media.offset_x
                                     : smart_crop_offset(media.focal_x, virtual_canvas_size.width(), scaled_width);
  const auto resolved_offset_y = media.manual_crop
                                     ? media.offset_y
                                     : smart_crop_offset(media.focal_y, virtual_canvas_size.height(), scaled_height);
  const int position_x =
      static_cast<int>(qRound(static_cast<double>(free_x) * ((resolved_offset_x + 1.0) / 2.0)));
  const int position_y =
      static_cast<int>(qRound(static_cast<double>(free_y) * ((resolved_offset_y + 1.0) / 2.0)));

  const auto scaled_image =
      source_image.scaled(scaled_width, scaled_height, Qt::IgnoreAspectRatio, Qt::SmoothTransformation);
  painter->drawImage(
      destination_rect.left() + position_x - segment_origin.x(),
      destination_rect.top() + position_y - segment_origin.y(),
      scaled_image);
  painter->restore();
}

void CarouselDocumentController::renderItemIntoSlide(
    QPainter* painter,
    const CanvasItem& item,
    int slide_index,
    const QSize& slide_size,
    bool preview) const {
  if (item.hidden) {
    return;
  }
  const auto export_size = exportPixelSize();
  const auto scale_x = static_cast<double>(slide_size.width()) / static_cast<double>(export_size.width());
  const auto scale_y = static_cast<double>(slide_size.height()) / static_cast<double>(export_size.height());
  const auto slide_origin_x = static_cast<double>(slide_index * export_size.width());
  const QRectF frame_rect(
      (item.bounds.x() - slide_origin_x) * scale_x,
      item.bounds.y() * scale_y,
      item.bounds.width() * scale_x,
      item.bounds.height() * scale_y);

  if (!frame_rect.adjusted(-12.0, -12.0, 12.0, 12.0).intersects(QRectF(QPointF(0.0, 0.0), QSizeF(slide_size)))) {
    return;
  }

  painter->save();
  painter->translate(frame_rect.center());
  painter->rotate(item.rotation_degrees);
  painter->scale(item.flipped_horizontal ? -1.0 : 1.0, item.flipped_vertical ? -1.0 : 1.0);
  painter->setOpacity(clamp_layer_opacity(item.opacity));
  painter->setCompositionMode(composition_mode_for_blend_mode(item.blend_mode));
  const QRectF local_rect(-frame_rect.width() / 2.0, -frame_rect.height() / 2.0, frame_rect.width(), frame_rect.height());
  const auto radius_scale = (scale_x + scale_y) / 2.0;
  const auto local_radius = qBound(0.0, item.corner_radius * radius_scale, qMin(local_rect.width(), local_rect.height()) / 2.0);
  const auto media_ellipse_mask =
      (item.kind == ItemKind::Image || item.kind == ItemKind::Video) &&
      item.media_mask_shape == QStringLiteral("ellipse");
  auto shadow_color = QColor(item.shadow_color);
  if (item.shadow_opacity > 0.0 && shadow_color.isValid()) {
    shadow_color.setAlphaF(static_cast<float>(clamp_layer_opacity(item.shadow_opacity)));
    painter->setPen(Qt::NoPen);
    painter->setBrush(shadow_color);
    const QRectF shadow_rect =
        local_rect.translated(item.shadow_offset_x * scale_x, item.shadow_offset_y * scale_y);
    if (media_ellipse_mask) {
      painter->drawEllipse(shadow_rect);
    } else if (local_radius > 0.0) {
      painter->drawRoundedRect(shadow_rect, local_radius, local_radius);
    } else {
      painter->drawRect(shadow_rect);
    }
  }
  if (item.kind == ItemKind::Image) {
    renderPhotoItem(painter, item, local_rect, preview);
  } else if (item.kind == ItemKind::Video) {
    renderVideoItem(painter, item, local_rect);
  } else if (item.kind == ItemKind::Shape) {
    renderShapeItem(painter, item, local_rect);
  } else {
    renderTextItem(painter, item, local_rect);
  }
  const auto frame_width = qMax(0.0, item.frame_width) * ((scale_x + scale_y) / 2.0);
  const QColor frame_color(item.frame_color);
  if (frame_width > 0.0 && frame_color.isValid()) {
    QPen frame_pen(frame_color);
    frame_pen.setWidthF(frame_width);
    frame_pen.setJoinStyle(Qt::MiterJoin);
    painter->setBrush(Qt::NoBrush);
    painter->setPen(frame_pen);
    const auto inset = qMin(frame_width / 2.0, qMin(local_rect.width(), local_rect.height()) / 2.0);
    const auto outline_rect = local_rect.adjusted(inset, inset, -inset, -inset);
    const auto frame_radius = qMax(0.0, local_radius - inset);
    if (media_ellipse_mask) {
      painter->drawEllipse(outline_rect);
    } else if (frame_radius > 0.0) {
      painter->drawRoundedRect(outline_rect, frame_radius, frame_radius);
    } else {
      painter->drawRect(outline_rect);
    }
  }
  painter->restore();
}

void CarouselDocumentController::renderPhotoItem(
    QPainter* painter,
    const CanvasItem& item,
    const QRectF& frame_rect,
    bool preview) const {
  QImage source_image;
  if (!decodeEditedImage(item, &source_image, preview, kPreviewLongEdge * 3)) {
    painter->setPen(QColor(QStringLiteral("#a56a5e")));
    painter->drawText(frame_rect, Qt::AlignCenter | Qt::TextWordWrap, QStringLiteral("Unable to read image"));
    return;
  }

  const auto selected_preview = preview && item.id == selected_item_id_;
  const auto preview_mode = selected_preview ? cutout_preview_mode_ : QStringLiteral("result");
  if (item.cutout_enabled) {
    source_image = apply_subject_cutout(
        std::move(source_image),
        item.cutout_mask_data,
        item.cutout_mask_width,
        item.cutout_mask_height,
        item.cutout_feather,
        item.cutout_expand,
        item.cutout_edge_contrast,
        preview_mode);
  }

  painter->save();
  const auto radius_scale = qMin(
      frame_rect.width() / qMax(1.0, item.bounds.width()),
      frame_rect.height() / qMax(1.0, item.bounds.height()));
  const auto radius = qBound(0.0, item.corner_radius * radius_scale, qMin(frame_rect.width(), frame_rect.height()) / 2.0);
  if (item.media_mask_shape == QStringLiteral("ellipse")) {
    QPainterPath clip_path;
    clip_path.addEllipse(frame_rect);
    painter->setClipPath(clip_path);
  } else if (radius > 0.0) {
    QPainterPath clip_path;
    clip_path.addRoundedRect(frame_rect, radius, radius);
    painter->setClipPath(clip_path);
  } else {
    painter->setClipRect(frame_rect);
  }
  if (item.cutout_enabled && preview_mode == QStringLiteral("black")) {
    painter->fillRect(frame_rect, Qt::black);
  } else if (item.cutout_enabled && preview_mode == QStringLiteral("white")) {
    painter->fillRect(frame_rect, Qt::white);
  }
  const auto centered_draw_rect = media_draw_rect(
      QSizeF(source_image.size()),
      frame_rect,
      item.fit_mode,
      item.media_scale,
      0.0,
      0.0);
  const auto draw_rect = media_draw_rect(
      QSizeF(source_image.size()),
      frame_rect,
      item.fit_mode,
      item.media_scale,
      item.media_manual_crop
          ? item.media_offset_x
          : smart_crop_offset(item.media_focal_x, frame_rect.width(), centered_draw_rect.width()),
      item.media_manual_crop
          ? item.media_offset_y
          : smart_crop_offset(item.media_focal_y, frame_rect.height(), centered_draw_rect.height()));
  painter->drawImage(draw_rect, source_image);
  painter->restore();
}

void CarouselDocumentController::renderVideoItem(
    QPainter* painter,
    const CanvasItem& item,
    const QRectF& frame_rect) const {
  MediaItem media;
  media.type = MediaType::Video;
  media.file_path = item.file_path;
  media.display_label = item.display_label;

  painter->save();
  const auto radius_scale = qMin(
      frame_rect.width() / qMax(1.0, item.bounds.width()),
      frame_rect.height() / qMax(1.0, item.bounds.height()));
  const auto radius = qBound(0.0, item.corner_radius * radius_scale, qMin(frame_rect.width(), frame_rect.height()) / 2.0);
  if (item.media_mask_shape == QStringLiteral("ellipse")) {
    QPainterPath clip_path;
    clip_path.addEllipse(frame_rect);
    painter->setClipPath(clip_path);
  } else if (radius > 0.0) {
    QPainterPath clip_path;
    clip_path.addRoundedRect(frame_rect, radius, radius);
    painter->setClipPath(clip_path);
  } else {
    painter->setClipRect(frame_rect);
  }
  painter->fillRect(frame_rect, QColor(QStringLiteral("#0f1820")));
  const auto source_size = item.source_size.isValid() ? item.source_size : frame_rect.size();
  const auto centered_draw_rect = media_draw_rect(
      source_size,
      frame_rect,
      item.fit_mode,
      item.media_scale,
      0.0,
      0.0);
  const auto draw_rect = media_draw_rect(
      source_size,
      frame_rect,
      item.fit_mode,
      item.media_scale,
      item.media_manual_crop
          ? item.media_offset_x
          : smart_crop_offset(item.media_focal_x, frame_rect.width(), centered_draw_rect.width()),
      item.media_manual_crop
          ? item.media_offset_y
          : smart_crop_offset(item.media_focal_y, frame_rect.height(), centered_draw_rect.height()));
  const auto placeholder_size =
      draw_rect.size().toSize().expandedTo(QSize(1, 1));
  const auto placeholder = renderVideoPlaceholder(media, placeholder_size);
  painter->drawImage(draw_rect, placeholder);
  painter->restore();
}

void CarouselDocumentController::renderShapeItem(
    QPainter* painter,
    const CanvasItem& item,
    const QRectF& frame_rect) const {
  const QColor fill(item.fill_color);
  const QColor secondary_fill(item.fill_secondary_color);
  const QColor stroke(item.stroke_color);
  const auto stroke_width = qMax(0.0, item.stroke_width);
  QPen pen(stroke.isValid() ? stroke : QColor(QStringLiteral("#1e1a17")));
  pen.setWidthF(stroke_width);
  pen.setCapStyle(Qt::RoundCap);
  pen.setJoinStyle(Qt::RoundJoin);
  if (stroke_width > 0.0) {
    painter->setPen(pen);
  } else {
    painter->setPen(Qt::NoPen);
  }
  QBrush fill_brush = fill.isValid() ? QBrush(fill) : QBrush(Qt::NoBrush);
  if (fill.isValid() && secondary_fill.isValid() && item.fill_kind != QStringLiteral("solid")) {
    QLinearGradient gradient;
    if (item.fill_kind == QStringLiteral("linear-horizontal")) {
      gradient = QLinearGradient(frame_rect.topLeft(), frame_rect.topRight());
    } else {
      gradient = QLinearGradient(frame_rect.topLeft(), frame_rect.bottomLeft());
    }
    gradient.setColorAt(0.0, fill);
    gradient.setColorAt(1.0, secondary_fill);
    fill_brush = QBrush(gradient);
  }
  painter->setBrush(fill_brush);

  if (item.shape_kind == QStringLiteral("ellipse")) {
    painter->drawEllipse(frame_rect);
    return;
  }

  if (item.shape_kind == QStringLiteral("triangle") || item.shape_kind == QStringLiteral("diamond") ||
      item.shape_kind == QStringLiteral("hexagon") || item.shape_kind == QStringLiteral("star")) {
    QPainterPath path;
    if (item.shape_kind == QStringLiteral("triangle")) {
      path.moveTo(frame_rect.center().x(), frame_rect.top());
      path.lineTo(frame_rect.right(), frame_rect.bottom());
      path.lineTo(frame_rect.left(), frame_rect.bottom());
    } else if (item.shape_kind == QStringLiteral("diamond")) {
      path.moveTo(frame_rect.center().x(), frame_rect.top());
      path.lineTo(frame_rect.right(), frame_rect.center().y());
      path.lineTo(frame_rect.center().x(), frame_rect.bottom());
      path.lineTo(frame_rect.left(), frame_rect.center().y());
    } else {
      const int point_count = item.shape_kind == QStringLiteral("star") ? 10 : 6;
      constexpr double kPi = 3.14159265358979323846;
      for (int index = 0; index < point_count; ++index) {
        const auto angle = (-kPi / 2.0) + (2.0 * kPi * static_cast<double>(index) /
                                          static_cast<double>(point_count));
        const auto radius_scale = item.shape_kind == QStringLiteral("star") && index % 2 == 1 ? 0.43 : 1.0;
        const QPointF point(
            frame_rect.center().x() + qCos(angle) * frame_rect.width() * 0.5 * radius_scale,
            frame_rect.center().y() + qSin(angle) * frame_rect.height() * 0.5 * radius_scale);
        if (index == 0) {
          path.moveTo(point);
        } else {
          path.lineTo(point);
        }
      }
    }
    path.closeSubpath();
    painter->drawPath(path);
    return;
  }

  if (item.shape_kind == QStringLiteral("line") || item.shape_kind == QStringLiteral("arrow")) {
    const QPointF start(frame_rect.left(), frame_rect.center().y());
    const QPointF end(frame_rect.right(), frame_rect.center().y());
    painter->setBrush(Qt::NoBrush);
    painter->drawLine(start, end);
    if (item.shape_kind == QStringLiteral("arrow")) {
      const auto head = qBound(12.0, qMin(frame_rect.width(), frame_rect.height()) * 0.42, 96.0);
      QPainterPath arrow_head;
      arrow_head.moveTo(end);
      arrow_head.lineTo(end.x() - head, end.y() - head * 0.48);
      arrow_head.lineTo(end.x() - head, end.y() + head * 0.48);
      arrow_head.closeSubpath();
      painter->setBrush(stroke.isValid() ? stroke : QColor(QStringLiteral("#1e1a17")));
      painter->drawPath(arrow_head);
    }
    return;
  }

  const auto radius = qBound(0.0, item.corner_radius, qMin(frame_rect.width(), frame_rect.height()) / 2.0);
  painter->drawRoundedRect(frame_rect, radius, radius);
}

void CarouselDocumentController::renderTextItem(
    QPainter* painter,
    const CanvasItem& item,
    const QRectF& frame_rect) const {
  QFont font(font_family_for_text_family(item.text_font_family));
  const auto scale = frame_rect.height() / qMax(1.0, item.bounds.height());
  font.setPointSizeF(qMax(6.0, item.text_point_size * scale));
  font.setWeight(font_weight_for_text_weight(item.text_weight));
  font.setItalic(item.text_italic);
  font.setUnderline(item.text_underline);
  font.setStrikeOut(item.text_strikethrough);
  font.setLetterSpacing(QFont::AbsoluteSpacing, clamp_text_letter_spacing(item.text_letter_spacing) * scale);
  painter->setFont(font);
  const auto layout_lines = textLayoutLines(item);
  const auto line_flags = text_alignment_flags(item.text_horizontal_alignment, item.text_vertical_alignment) &
                          ~Qt::TextWordWrap;
  auto draw_lines = [&](const QPointF& offset, const QColor& forced_color = QColor()) {
    for (const auto& value : layout_lines) {
      const auto line = value.toMap();
      const auto segments = line.value(QStringLiteral("segments")).toList();
      if (!segments.isEmpty()) {
        for (const auto& segment_value : segments) {
          const auto segment = segment_value.toMap();
          auto segment_font = font;
          segment_font.setPointSizeF(
              qMax(6.0,
                   item.text_point_size * scale *
                       segment.value(QStringLiteral("pointSizeScale")).toDouble()));
          segment_font.setWeight(font_weight_for_text_weight(
              segment.value(QStringLiteral("fontWeight")).toString()));
          segment_font.setItalic(segment.value(QStringLiteral("italic")).toBool());
          segment_font.setUnderline(segment.value(QStringLiteral("underline")).toBool());
          segment_font.setStrikeOut(segment.value(QStringLiteral("strikethrough")).toBool());
          painter->setFont(segment_font);
          painter->setPen(
              forced_color.isValid()
                  ? forced_color
                  : QColor(segment.value(QStringLiteral("color")).toString()));
          const QRectF segment_rect(
              frame_rect.left() +
                  segment.value(QStringLiteral("x")).toDouble() * scale + offset.x(),
              frame_rect.top() +
                  (line.value(QStringLiteral("y")).toDouble() +
                   segment.value(QStringLiteral("baselineShift")).toDouble()) *
                      scale +
                  offset.y(),
              qMax(1.0, segment.value(QStringLiteral("width")).toDouble() * scale + 2.0),
              line.value(QStringLiteral("height")).toDouble() * scale);
          const auto vertical_alignment =
              item.text_vertical_alignment == QStringLiteral("top")
                  ? static_cast<int>(Qt::AlignTop)
                  : item.text_vertical_alignment == QStringLiteral("bottom")
                        ? static_cast<int>(Qt::AlignBottom)
                        : static_cast<int>(Qt::AlignVCenter);
          painter->drawText(
              segment_rect,
              static_cast<int>(Qt::AlignLeft) | vertical_alignment,
              segment.value(QStringLiteral("text")).toString());
        }
        continue;
      }
      painter->setFont(font);
      painter->setPen(forced_color.isValid() ? forced_color : QColor(item.text_color));
      const QRectF line_rect(
          frame_rect.left() + line.value(QStringLiteral("x")).toDouble() * scale + offset.x(),
          frame_rect.top() + line.value(QStringLiteral("y")).toDouble() * scale + offset.y(),
          qMax(0.0, frame_rect.width() -
                        (line.value(QStringLiteral("x")).toDouble() +
                         qMax(0.0, item.text_padding + item.text_inset)) * scale),
          line.value(QStringLiteral("height")).toDouble() * scale);
      painter->drawText(line_rect, line_flags, line.value(QStringLiteral("text")).toString());
    }
  };
  auto background_color = QColor(item.text_background_color);
  if (item.text_background_opacity > 0.0 && background_color.isValid()) {
    background_color.setAlphaF(static_cast<float>(clamp_layer_opacity(item.text_background_opacity)));
    painter->save();
    painter->setPen(Qt::NoPen);
    painter->setBrush(background_color);
    const auto radius = qBound(
        0.0,
        item.text_background_radius * scale,
        qMin(frame_rect.width(), frame_rect.height()) / 2.0);
    painter->drawRoundedRect(frame_rect, radius, radius);
    painter->restore();
  }
  const auto stroke_width = qMax(0.0, item.text_stroke_width * scale);
  const QColor stroke_color(item.text_stroke_color);
  if (stroke_width > 0.0 && stroke_color.isValid()) {
    painter->save();
    painter->setPen(stroke_color);
    const auto radius = qCeil(stroke_width);
    painter->setClipRect(frame_rect);
    for (int y = -radius; y <= radius; ++y) {
      for (int x = -radius; x <= radius; ++x) {
        if (x == 0 && y == 0) {
          continue;
        }
        if ((x * x) + (y * y) > radius * radius) {
          continue;
        }
        draw_lines(QPointF(x, y), stroke_color);
      }
    }
    painter->restore();
  }
  painter->save();
  painter->setClipRect(frame_rect);
  draw_lines(QPointF());
  painter->restore();
}

void CarouselDocumentController::renderBrushItem(
    QPainter* painter,
    const CanvasItem& item,
    int slide_index,
    const QSize& slide_size) const {
  if (painter == nullptr || item.hidden || item.brush_points.size() < 2 ||
      !slideRectInDocument(slide_index).intersects(item.bounds)) {
    return;
  }
  const auto document_slide = slideRectInDocument(slide_index);
  const auto scale_x = static_cast<double>(slide_size.width()) / qMax(1.0, document_slide.width());
  const auto scale_y = static_cast<double>(slide_size.height()) / qMax(1.0, document_slide.height());
  const auto source_width = qMax(1.0, item.brush_source_size.width());
  const auto source_height = qMax(1.0, item.brush_source_size.height());
  const auto item_scale_x = item.bounds.width() / source_width;
  const auto item_scale_y = item.bounds.height() / source_height;

  auto mapped_point = [&](const QPointF& point) {
    QPointF document_point(item.bounds.left() + point.x() * item_scale_x,
                           item.bounds.top() + point.y() * item_scale_y);
    if (!qFuzzyIsNull(item.rotation_degrees)) {
      constexpr double kPi = 3.14159265358979323846;
      const auto angle = item.rotation_degrees * kPi / 180.0;
      const auto delta = document_point - item.bounds.center();
      document_point = item.bounds.center() +
                       QPointF(delta.x() * qCos(angle) - delta.y() * qSin(angle),
                               delta.x() * qSin(angle) + delta.y() * qCos(angle));
    }
    return QPointF((document_point.x() - document_slide.left()) * scale_x,
                   (document_point.y() - document_slide.top()) * scale_y);
  };
  QPainterPath path;
  path.moveTo(mapped_point(item.brush_points.constFirst()));
  for (int index = 1; index < item.brush_points.size(); ++index) {
    path.lineTo(mapped_point(item.brush_points.at(index)));
  }

  painter->save();
  painter->setCompositionMode(item.brush_eraser ? QPainter::CompositionMode_DestinationOut
                                                : QPainter::CompositionMode_SourceOver);
  QColor color(item.brush_color);
  color.setAlphaF(static_cast<float>(item.brush_style == QStringLiteral("highlighter")
                                         ? qMin(0.42, item.opacity)
                                         : item.opacity));
  const auto width = qMax(1.0, item.brush_width * (scale_x + scale_y) * 0.5);
  if (item.brush_eraser) {
    painter->setOpacity(item.opacity);
    QPainterPathStroker stroker;
    stroker.setWidth(width);
    stroker.setCapStyle(Qt::RoundCap);
    stroker.setJoinStyle(Qt::RoundJoin);
    painter->fillPath(stroker.createStroke(path), QColor(Qt::black));
    painter->restore();
    return;
  }
  if (item.brush_style == QStringLiteral("glow") && !item.brush_eraser) {
    auto glow_color = color;
    glow_color.setAlphaF(static_cast<float>(item.opacity * 0.22));
    QPen glow_pen(glow_color, width * 2.8, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin);
    painter->setPen(glow_pen);
    painter->drawPath(path);
  }
  QPen pen(color,
           width,
           Qt::SolidLine,
           Qt::RoundCap,
           Qt::RoundJoin);
  painter->setPen(pen);
  painter->drawPath(path);
  painter->restore();
}

void CarouselDocumentController::adjustItemsForFormatChange(const QSize& old_slide_size, const QSize& new_slide_size) {
  if (!old_slide_size.isValid() || !new_slide_size.isValid() || items_.isEmpty()) {
    return;
  }

  const auto old_width = static_cast<double>(old_slide_size.width() * slideCount());
  const auto new_width = static_cast<double>(new_slide_size.width() * slideCount());
  const auto scale_x = new_width / qMax(1.0, old_width);
  const auto scale_y = static_cast<double>(new_slide_size.height()) / qMax(1.0, static_cast<double>(old_slide_size.height()));

  for (auto& item : items_) {
    item.bounds = QRectF(
        item.bounds.x() * scale_x,
        item.bounds.y() * scale_y,
        item.bounds.width() * scale_x,
        item.bounds.height() * scale_y);
    if (item.kind == ItemKind::Text) {
      item.text_point_size *= scale_y;
      const auto center = item.bounds.center();
      item.bounds.setHeight(measuredTextHeight(item));
      item.bounds.moveCenter(center);
    }
  }
}

void CarouselDocumentController::adjustItemsForSlidesShifted(int start_index, int delta_slides) {
  if (delta_slides == 0) {
    return;
  }
  const auto slide_width = exportPixelSize().width();
  const auto threshold = static_cast<double>(start_index * slide_width);
  for (auto& item : items_) {
    if (item.bounds.center().x() >= threshold) {
      const auto delta_x = static_cast<double>(delta_slides * slide_width);
      item.bounds.translate(delta_x, 0.0);
      if (!item.constraint_stack_id.isEmpty()) {
        item.constraint_stack_anchor_x += delta_x;
      }
    }
  }
}

void CarouselDocumentController::adjustItemsForSlideSwap(int first_index, int second_index) {
  if (first_index == second_index) {
    return;
  }

  const auto slide_width = exportPixelSize().width();
  const auto delta = static_cast<double>((second_index - first_index) * slide_width);
  for (auto& item : items_) {
    const auto item_slide = slideIndexForItem(item);
    if (item_slide == first_index) {
      item.bounds.translate(delta, 0.0);
      if (!item.constraint_stack_id.isEmpty()) {
        item.constraint_stack_anchor_x += delta;
      }
    } else if (item_slide == second_index) {
      item.bounds.translate(-delta, 0.0);
      if (!item.constraint_stack_id.isEmpty()) {
        item.constraint_stack_anchor_x -= delta;
      }
    }
  }
}

void CarouselDocumentController::adjustItemsForBlockMove(int start_index, int span, int destination_index) {
  if (span <= 0 || start_index == destination_index) {
    return;
  }

  const auto slide_width = exportPixelSize().width();
  if (destination_index < start_index) {
    const auto displaced_index = destination_index;
    for (auto& item : items_) {
      const auto item_slide = slideIndexForItem(item);
      if (item_slide >= start_index && item_slide < start_index + span) {
        item.bounds.translate(-static_cast<double>(slide_width), 0.0);
      } else if (item_slide == displaced_index) {
        item.bounds.translate(static_cast<double>(slide_width * span), 0.0);
      }
    }
    return;
  }

  const auto displaced_index = start_index + span;
  for (auto& item : items_) {
    const auto item_slide = slideIndexForItem(item);
    if (item_slide >= start_index && item_slide < start_index + span) {
      item.bounds.translate(static_cast<double>(slide_width), 0.0);
    } else if (item_slide == displaced_index) {
      item.bounds.translate(-static_cast<double>(slide_width * span), 0.0);
    }
  }
}

void CarouselDocumentController::normalizeBoardSections() {
  QSet<QString> known_ids;
  for (qsizetype index = board_sections_.size(); index > 0; --index) {
    auto& section = board_sections_[index - 1];
    section.id = section.id.trimmed();
    section.name = normalized_board_name(section.name);
    if (section.id.isEmpty() || section.name.isEmpty() || known_ids.contains(section.id)) {
      board_sections_.removeAt(index - 1);
      continue;
    }
    known_ids.insert(section.id);
  }
  for (auto& slide : slides_) {
    if (!slide.section_id.isEmpty() && !known_ids.contains(slide.section_id)) {
      slide.section_id.clear();
    }
  }
  QSet<QString> seen_sections;
  QString previous_section_id;
  for (auto& slide : slides_) {
    if (slide.section_id.isEmpty()) {
      previous_section_id.clear();
      continue;
    }
    if (slide.section_id != previous_section_id && seen_sections.contains(slide.section_id)) {
      slide.section_id.clear();
      previous_section_id.clear();
      continue;
    }
    seen_sections.insert(slide.section_id);
    previous_section_id = slide.section_id;
  }
  QSet<QString> used_ids;
  for (const auto& slide : slides_) {
    if (!slide.section_id.isEmpty()) {
      used_ids.insert(slide.section_id);
    }
  }
  for (qsizetype index = board_sections_.size(); index > 0; --index) {
    if (!used_ids.contains(board_sections_.at(index - 1).id)) {
      board_sections_.removeAt(index - 1);
    }
  }
}

void CarouselDocumentController::normalizeRepeatedElementLinks() {
  QSet<QString> known_ids;
  for (qsizetype index = repeated_element_links_.size(); index > 0; --index) {
    auto& link = repeated_element_links_[index - 1];
    link.id = link.id.trimmed();
    link.name = normalized_board_name(link.name);
    if (link.id.isEmpty() || link.name.isEmpty() || known_ids.contains(link.id)) {
      repeated_element_links_.removeAt(index - 1);
      continue;
    }
    known_ids.insert(link.id);
  }
  for (qsizetype index = repeated_element_links_.size(); index > 0; --index) {
    const auto link_id = repeated_element_links_.at(index - 1).id;
    const auto prefix = link_id + QStringLiteral(":");
    QSet<int> boards;
    for (const auto& item : items_) {
      if (item.component_link_id.startsWith(prefix)) {
        boards.insert(slideIndexForItem(item));
      }
    }
    if (boards.size() >= 2) {
      continue;
    }
    for (auto& item : items_) {
      if (item.component_link_id.startsWith(prefix)) {
        item.component_link_id.clear();
      }
    }
    repeated_element_links_.removeAt(index - 1);
  }
}

bool CarouselDocumentController::editBoardHasUnlockedPhotoTextLayer(
    const Slide& slide, const QString& layer_id) const {
  const auto normalized_layer_id = layer_id.trimmed();
  if (normalized_layer_id.isEmpty() || slide.edit_board_id.trimmed().isEmpty() ||
      slide.primary.type != MediaType::Image || slide.primary.adjustment_patch_json.isEmpty()) {
    return false;
  }
  const auto decoded = parse_adjustment_patch_json(slide.primary.adjustment_patch_json);
  if (!decoded.ok() || decoded.scope != AdjustmentPatchScope::AssetBound) return false;
  for (const auto& value : decoded.state->layers) {
    const auto layer = value.toMap();
    if (layer.value(QStringLiteral("id")).toString().trimmed() == normalized_layer_id &&
        layer.value(QStringLiteral("kind")).toString() == QStringLiteral("text")) {
      return !layer.value(QStringLiteral("locked")).toBool();
    }
  }
  return false;
}

int CarouselDocumentController::editBoardIndexForId(const QString& board_id) const {
  const auto normalized_board_id = board_id.trimmed();
  if (normalized_board_id.isEmpty()) return -1;
  for (int index = 0; index < slides_.size(); ++index) {
    if (slides_.at(index).edit_board_id == normalized_board_id) return index;
  }
  return -1;
}

void CarouselDocumentController::normalizePhotoTextLinks() {
  QSet<QString> known_ids;
  for (qsizetype index = photo_text_links_.size(); index > 0; --index) {
    auto& link = photo_text_links_[index - 1];
    link.id = link.id.trimmed();
    link.name = normalized_board_name(link.name);
    link.layer_id = link.layer_id.trimmed();
    if (link.id.isEmpty() || link.name.isEmpty() || link.layer_id.isEmpty() ||
        known_ids.contains(link.id)) {
      photo_text_links_.removeAt(index - 1);
      continue;
    }
    known_ids.insert(link.id);
    QStringList valid_board_ids;
    for (const auto& board_id : link.board_ids) {
      const auto board_index = editBoardIndexForId(board_id);
      if (board_index < 0 || groupForIndex(board_index) != nullptr ||
          slides_.at(board_index).primary.type != MediaType::Image) {
        continue;
      }
      const auto decoded = parse_adjustment_patch_json(
          slides_.at(board_index).primary.adjustment_patch_json);
      if (!decoded.ok() || decoded.scope != AdjustmentPatchScope::AssetBound) continue;
      const auto has_text_layer = std::any_of(
          decoded.state->layers.cbegin(), decoded.state->layers.cend(),
          [&link](const QVariant& value) {
            const auto layer = value.toMap();
            return layer.value(QStringLiteral("id")).toString().trimmed() == link.layer_id &&
                layer.value(QStringLiteral("kind")).toString() == QStringLiteral("text");
          });
      if (has_text_layer && !valid_board_ids.contains(board_id)) valid_board_ids.push_back(board_id);
    }
    link.board_ids = valid_board_ids;
    if (link.board_ids.size() < 2) photo_text_links_.removeAt(index - 1);
  }
}

bool CarouselDocumentController::prepareLinkedPhotoTextSync(
    const QString& source_board_id,
    const QString& before_adjustment_patch,
    const QString& after_adjustment_patch,
    QVector<QPair<int, QString>>* peer_patches,
    QString* error) const {
  if (peer_patches == nullptr) return false;
  peer_patches->clear();
  if (error != nullptr) error->clear();
  const auto before = parse_adjustment_patch_json(before_adjustment_patch);
  const auto after = parse_adjustment_patch_json(after_adjustment_patch);
  if (!before.ok() || !after.ok() ||
      before.scope != AdjustmentPatchScope::AssetBound ||
      after.scope != AdjustmentPatchScope::AssetBound) {
    if (error != nullptr) *error = QStringLiteral("The linked photo text recipe is invalid.");
    return false;
  }

  QHash<QString, QVariantMap> before_text_layers;
  for (const auto& value : before.state->layers) {
    const auto layer = value.toMap();
    const auto layer_id = layer.value(QStringLiteral("id")).toString().trimmed();
    if (!layer_id.isEmpty() && layer.value(QStringLiteral("kind")).toString() == QStringLiteral("text") &&
        !layer.value(QStringLiteral("locked")).toBool()) {
      before_text_layers.insert(layer_id, layer);
    }
  }
  QHash<QString, QString> changed_text;
  for (const auto& value : after.state->layers) {
    const auto layer = value.toMap();
    const auto layer_id = layer.value(QStringLiteral("id")).toString().trimmed();
    if (layer_id.isEmpty() || layer.value(QStringLiteral("kind")).toString() != QStringLiteral("text") ||
        layer.value(QStringLiteral("locked")).toBool() || !before_text_layers.contains(layer_id)) {
      continue;
    }
    const auto next_text = layer.value(QStringLiteral("text")).toString();
    if (before_text_layers.value(layer_id).value(QStringLiteral("text")).toString() != next_text) {
      changed_text.insert(layer_id, next_text);
    }
  }
  if (changed_text.isEmpty()) return true;

  QHash<int, EditRecipeState> peer_states;
  QHash<int, QStringList> peer_groups;
  QHash<int, bool> peer_changed;
  for (const auto& link : photo_text_links_) {
    if (!link.board_ids.contains(source_board_id) || !changed_text.contains(link.layer_id)) continue;
    const auto next_text = changed_text.value(link.layer_id);
    for (const auto& board_id : link.board_ids) {
      if (board_id == source_board_id) continue;
      const auto board_index = editBoardIndexForId(board_id);
      const auto board_number = board_index >= 0 ? board_index + 1 : 0;
      if (board_index < 0 || groupForIndex(board_index) != nullptr ||
          slides_.at(board_index).primary.type != MediaType::Image) {
        if (error != nullptr) *error = QStringLiteral("Shared text could not reach linked board %1.").arg(board_number);
        return false;
      }
      if (!peer_states.contains(board_index)) {
        const auto decoded = parse_adjustment_patch_json(
            slides_.at(board_index).primary.adjustment_patch_json);
        if (!decoded.ok() || decoded.scope != AdjustmentPatchScope::AssetBound) {
          if (error != nullptr) *error = QStringLiteral("The photo recipe on linked board %1 is invalid.").arg(board_number);
          return false;
        }
        peer_states.insert(board_index, *decoded.state);
        peer_groups.insert(board_index, decoded.groups);
        peer_changed.insert(board_index, false);
      }
      auto state = peer_states.value(board_index);
      bool found_layer = false;
      for (qsizetype layer_index = 0; layer_index < state.layers.size(); ++layer_index) {
        auto layer = state.layers.at(layer_index).toMap();
        if (layer.value(QStringLiteral("id")).toString().trimmed() != link.layer_id ||
            layer.value(QStringLiteral("kind")).toString() != QStringLiteral("text")) {
          continue;
        }
        found_layer = true;
        if (layer.value(QStringLiteral("text")).toString() == next_text) break;
        if (layer.value(QStringLiteral("locked")).toBool()) {
          if (error != nullptr) *error = QStringLiteral("Unlock the matching text on board %1 before updating shared text.").arg(board_number);
          return false;
        }
        layer.insert(QStringLiteral("text"), next_text);
        if (layer.contains(QStringLiteral("textTypography")) &&
            !photo_editor::desktop::fit_photo_point_text(&layer)) {
          if (error != nullptr) *error = QStringLiteral("Shared text could not fit the style on board %1.").arg(board_number);
          return false;
        }
        state.layers[layer_index] = layer;
        peer_states.insert(board_index, state);
        peer_changed[board_index] = true;
        break;
      }
      if (!found_layer) {
        if (error != nullptr) *error = QStringLiteral("The matching text layer is missing from board %1.").arg(board_number);
        return false;
      }
    }
  }

  auto board_indexes = peer_states.keys();
  std::sort(board_indexes.begin(), board_indexes.end());
  for (const auto board_index : board_indexes) {
    if (!peer_changed.value(board_index)) continue;
    const auto patch = serialize_adjustment_patch_json(
        peer_states.value(board_index), peer_groups.value(board_index),
        AdjustmentPatchScope::AssetBound);
    const auto validated = parse_adjustment_patch_json(patch);
    if (patch.isEmpty() || !validated.ok() ||
        validated.scope != AdjustmentPatchScope::AssetBound) {
      if (error != nullptr) *error = QStringLiteral("The updated text recipe for board %1 could not be saved.").arg(board_index + 1);
      peer_patches->clear();
      return false;
    }
    peer_patches->push_back(qMakePair(board_index, patch));
  }
  return true;
}

void CarouselDocumentController::captureRepeatedElementSyncSources() {
  pending_repeated_element_sync_source_ids_.clear();
  for (const auto& item_id : selected_item_ids_) {
    const auto index = indexOfItem(item_id);
    if (index < 0 ||
        repeatedElementLinkIdForComponent(items_.at(index).component_link_id).isEmpty()) {
      continue;
    }
    pending_repeated_element_sync_source_ids_.push_back(item_id);
  }
}

void CarouselDocumentController::synchronizePendingRepeatedElements() {
  if (pending_repeated_element_sync_source_ids_.isEmpty()) {
    return;
  }
  const auto source_ids = pending_repeated_element_sync_source_ids_;
  const auto slide_width = exportPixelSize().width();
  QStringList target_constraint_stacks_to_reflow;
  for (const auto& source_id : source_ids) {
    const auto source_index = indexOfItem(source_id);
    if (source_index < 0) {
      continue;
    }
    const auto source = items_.at(source_index);
    if (repeatedElementLinkIdForComponent(source.component_link_id).isEmpty()) {
      continue;
    }
    const auto source_board = slideIndexForItem(source);
    for (int index = 0; index < items_.size(); ++index) {
      if (index == source_index || items_.at(index).component_link_id != source.component_link_id) {
        continue;
      }
      const auto target_id = items_.at(index).id;
      const auto target_group_id = items_.at(index).object_group_id;
      const auto target_component_id = items_.at(index).component_link_id;
      const auto target_constraint_stack_id = items_.at(index).constraint_stack_id;
      const auto target_board = slideIndexForItem(items_.at(index));
      const auto board_delta_x =
          static_cast<double>((target_board - source_board) * slide_width);
      auto synchronized = source;
      synchronized.id = target_id;
      synchronized.object_group_id = target_group_id;
      synchronized.component_link_id = target_component_id;
      synchronized.constraint_stack_id = target_constraint_stack_id;
      synchronized.constraint_stack_order = target_constraint_stack_id.isEmpty()
                                                ? -1
                                                : source.constraint_stack_order;
      synchronized.constraint_stack_anchor_x =
          source.constraint_stack_anchor_x + board_delta_x;
      synchronized.bounds.translate(board_delta_x, 0.0);
      synchronized.preview_source.clear();
      synchronized.preview_source_size = {};
      items_[index] = std::move(synchronized);
      if (!target_constraint_stack_id.isEmpty() &&
          !target_constraint_stacks_to_reflow.contains(target_constraint_stack_id)) {
        target_constraint_stacks_to_reflow.push_back(target_constraint_stack_id);
      }
    }
  }
  for (const auto& stack_id : target_constraint_stacks_to_reflow) {
    relayoutConstraintStack(stack_id);
  }
  if (!history_transaction_active_) {
    pending_repeated_element_sync_source_ids_.clear();
  }
}

void CarouselDocumentController::moveSlideBlock(
    int start_index,
    int span,
    int destination_index) {
  if (span <= 0 || start_index < 0 || start_index + span > slides_.size()) {
    return;
  }
  const auto bounded_destination = qBound(
      0, destination_index, static_cast<int>(slides_.size()) - span);
  if (bounded_destination == start_index) {
    return;
  }

  QVector<int> order;
  order.reserve(slides_.size());
  for (int index = 0; index < slides_.size(); ++index) {
    if (index < start_index || index >= start_index + span) {
      order.push_back(index);
    }
  }
  QVector<int> block;
  block.reserve(span);
  for (int index = start_index; index < start_index + span; ++index) {
    block.push_back(index);
  }
  const auto insertion_index = qBound(0, bounded_destination, static_cast<int>(order.size()));
  for (int index = 0; index < block.size(); ++index) {
    order.insert(insertion_index + index, block.at(index));
  }

  QVector<int> old_to_new(slides_.size(), -1);
  QVector<Slide> reordered_slides;
  reordered_slides.reserve(slides_.size());
  for (int new_index = 0; new_index < order.size(); ++new_index) {
    const auto old_index = order.at(new_index);
    old_to_new[old_index] = new_index;
    reordered_slides.push_back(slides_.at(old_index));
  }
  const auto slide_width = exportPixelSize().width();
  for (auto& item : items_) {
    const auto old_index = slideIndexForItem(item);
    if (old_index >= 0 && old_index < old_to_new.size() && old_to_new.at(old_index) >= 0) {
      item.bounds.translate(
          static_cast<double>((old_to_new.at(old_index) - old_index) * slide_width), 0.0);
    }
  }
  if (current_index_ >= 0 && current_index_ < old_to_new.size()) {
    current_index_ = old_to_new.at(current_index_);
  }
  for (auto& selected_index : selected_slide_indices_) {
    if (selected_index >= 0 && selected_index < old_to_new.size()) {
      selected_index = old_to_new.at(selected_index);
    }
  }
  std::sort(selected_slide_indices_.begin(), selected_slide_indices_.end());
  slides_ = std::move(reordered_slides);
  rebuildGroupIndices();
  normalizeBoardSections();
}

void CarouselDocumentController::pushUndoState(const QString& label, bool coalesce) {
  if (restoring_history_) {
    return;
  }
  if (!history_transaction_active_) {
    captureRepeatedElementSyncSources();
  }
  if (history_transaction_active_) {
    return;
  }
  markDocumentDirty();
  const auto normalized_label = label.trimmed().isEmpty() ? QStringLiteral("Edit") : label.trimmed();
  if (coalesce && history_coalesce_timer_->isActive() && history_coalesce_label_ == normalized_label) {
    history_coalesce_timer_->start();
    return;
  }
  history_coalesce_timer_->stop();
  history_coalesce_label_.clear();
  appendUndoEntry({captureDocumentSnapshot(), normalized_label});
  if (coalesce) {
    history_coalesce_label_ = normalized_label;
    history_coalesce_timer_->start();
  }
  redo_stack_.clear();
  emit historyChanged();
}

void CarouselDocumentController::appendUndoEntry(HistoryEntry entry) {
  while (undo_stack_.size() >= kHistoryLimit) {
    undo_stack_.removeFirst();
  }
  undo_stack_.push_back(std::move(entry));
}

void CarouselDocumentController::restoreHistoryEntry(
    const HistoryEntry& entry,
    const QString& status_prefix) {
  restoring_history_ = true;
  preview_debounce_timer_->stop();
  const bool restored = loadDocumentObject(snapshotDocumentObject(*entry.document));
  if (restored) {
    selected_slide_indices_.clear();
    for (const auto index : entry.document->selected_slide_indices) {
      if (index >= 0 && index < slides_.size() &&
          !selected_slide_indices_.contains(index)) {
        selected_slide_indices_.push_back(index);
      }
    }
    if (selected_slide_indices_.isEmpty()) {
      selected_slide_indices_.push_back(current_index_);
    }
    std::sort(selected_slide_indices_.begin(), selected_slide_indices_.end());
    // Loading the persisted snapshot clears every derived preview URL, including
    // boards outside the selection. Rebuild them through the coalesced worker.
    refreshPreviews();
    emit documentFormatChanged();
    emitCanvasStateChanged(true);
    setStatus(QStringLiteral("%1 %2.").arg(status_prefix, entry.label.toLower()));
  }
  restoring_history_ = false;
  emit historyChanged();
}

void CarouselDocumentController::clearHistory() {
  history_coalesce_timer_->stop();
  history_coalesce_label_.clear();
  history_transaction_active_ = false;
  history_transaction_start_ = {};
  history_transaction_label_.clear();
  pending_repeated_element_sync_source_ids_.clear();
  undo_stack_.clear();
  redo_stack_.clear();
  emit historyChanged();
}

void CarouselDocumentController::emitItemGeometryChanged(bool slides_changed) {
  ++autosave_revision_;
  invalidatePreviewRefresh(false);
  synchronizePendingRepeatedElements();
  emit itemsChanged();
  emit selectionChanged();
  if (slides_changed) {
    emit slidesChanged();
  }
}

void CarouselDocumentController::ensureCurrentIndexValid() {
  current_index_ = qBound(0, current_index_, qMax(0, static_cast<int>(slides_.size()) - 1));
  if (selected_slide_indices_.isEmpty()) {
    selected_slide_indices_ = {current_index_};
  }
  normalizeForCurrentTemplate();
}

void CarouselDocumentController::invalidatePreviewRefresh(bool reset_document) {
  ++preview_request_revision_;
  if (preview_task_state_) preview_task_state_->cancelled.store(true, std::memory_order_relaxed);
  if (reset_document) {
    pending_preview_boards_.clear();
    pending_preview_items_.clear();
    preview_file_owners_.clear();
    if (preview_debounce_timer_) preview_debounce_timer_->stop();
  }
}

void CarouselDocumentController::queuePreviewRefresh(
    const QVector<int>& boards, const QSet<QString>& items) {
  for (const auto board : boards) {
    if (board >= 0 && board < slides_.size()) pending_preview_boards_.insert(board);
  }
  pending_preview_items_.unite(items);
  invalidatePreviewRefresh(false);
  preview_debounce_timer_->stop();
  // Capture after the caller has finished its mutation and signal emission.
  QTimer::singleShot(0, this, &CarouselDocumentController::startPendingPreviewRefresh);
}

void CarouselDocumentController::startPendingPreviewRefresh() {
  if (preview_worker_active_ || preview_debounce_timer_->isActive() ||
      (pending_preview_boards_.isEmpty() && pending_preview_items_.isEmpty())) return;
  auto boards = pending_preview_boards_.values();
  std::sort(boards.begin(), boards.end());
  // Current board first; the remaining dirty boards follow in stable order.
  if (boards.removeOne(current_index_)) boards.prepend(current_index_);
  const auto item_ids = pending_preview_items_;
  const auto revision = preview_request_revision_;
  const auto snapshot = captureExportSnapshot();
  const auto retained_files = preview_file_owners_;
  const auto cache_root = previewsRoot();
  preview_task_state_ = std::make_shared<ExportTaskState>();
  const auto state = preview_task_state_;
  preview_worker_active_ = true;
  preview_watcher_->setFuture(QtConcurrent::run(&previewThreadPool(),
      [snapshot, retained_files, boards, item_ids, revision, state, cache_root] {
    Q_UNUSED(retained_files);
    PreviewResult result;
    result.revision = revision;
    if (state->cancelled.load(std::memory_order_relaxed)) return result;
    QDir().mkpath(cache_root);
    QTemporaryDir directory(QDir(cache_root).filePath(QStringLiteral("render-XXXXXX")));
    if (!directory.isValid()) {
      result.diagnostics.insert(QStringLiteral("error"), QStringLiteral("Preview cache directory could not be created."));
      return result;
    }
    result.files = std::make_shared<PreviewFiles>();
    result.files->directory = directory.path();
    directory.setAutoRemove(false);
    CarouselDocumentController renderer(*snapshot);
    renderer.preview_output_directory_ = result.files->directory;
    renderer.preview_revision_ = 1; // The directory gives each publication a unique URL.
    renderer.preview_request_revision_ = revision;
    renderer.export_task_state_ = state;
    renderer.beginPreviewDiagnostics(QStringLiteral("async-dirty-content"), boards);
    for (auto& item : renderer.items_) {
      if (!item_ids.contains(item.id)) continue;
      if (state->cancelled.load(std::memory_order_relaxed)) return result;
      renderer.refreshItemPreview(&item);
      result.items.insert(item.id, {item.preview_source, item.preview_source_size});
    }
    for (const auto board : boards) {
      if (state->cancelled.load(std::memory_order_relaxed)) return result;
      if (board < 0 || board >= renderer.slides_.size()) continue;
      renderer.slides_[board].preview_source.clear();
      renderer.refreshPreviewAt(board);
      result.boards.insert(board, renderer.slides_.at(board).preview_source);
    }
    renderer.finishPreviewDiagnostics();
    result.diagnostics = renderer.preview_diagnostics_;
    return result;
  }));
}

void CarouselDocumentController::finishPreviewRefresh() {
  auto result = preview_watcher_->future().takeResult();
  preview_worker_active_ = false;
  preview_task_state_.reset();
  if (result.revision != preview_request_revision_) {
    ++stale_preview_requests_dropped_;
    startPendingPreviewRefresh();
    return;
  }
  pending_preview_boards_.clear();
  pending_preview_items_.clear();
  QSet<QString> live_keys;
  for (int index = 0; index < slides_.size(); ++index) live_keys.insert(QStringLiteral("board:%1").arg(index));
  for (const auto& item : items_) live_keys.insert(QStringLiteral("item:") + item.id);
  for (auto it = preview_file_owners_.begin(); it != preview_file_owners_.end();) {
    if (!live_keys.contains(it.key())) it = preview_file_owners_.erase(it);
    else ++it;
  }
  const auto retain_file = [&result](const QString& source) {
    auto owner = std::make_shared<PreviewFiles>();
    owner->file = QUrl(source).toLocalFile();
    owner->parent = result.files;
    return owner;
  };
  for (auto it = result.boards.cbegin(); it != result.boards.cend(); ++it) {
    if (auto* slide = slideAt(it.key()); slide && !it.value().isEmpty()) {
      slide->preview_source = it.value();
      preview_file_owners_.insert(QStringLiteral("board:%1").arg(it.key()), retain_file(it.value()));
    }
  }
  for (auto& item : items_) {
    const auto it = result.items.constFind(item.id);
    if (it == result.items.cend()) continue;
    if (item.preview_source != it->first) {
      const auto key = QStringLiteral("item:") + item.id;
      if (it->first.isEmpty()) preview_file_owners_.remove(key);
      else preview_file_owners_.insert(key, retain_file(it->first));
    }
    item.preview_source = it->first;
    item.preview_source_size = it->second;
  }
  ++preview_revision_;
  preview_diagnostics_ = std::move(result.diagnostics);
  preview_diagnostics_.insert(QStringLiteral("revision"), preview_revision_);
  preview_diagnostics_.insert(QStringLiteral("requestRevision"), static_cast<qulonglong>(preview_request_revision_));
  preview_diagnostics_.insert(QStringLiteral("staleRequestsDropped"), stale_preview_requests_dropped_);
  emit previewDiagnosticsChanged();
  emit slidesChanged();
  emit itemsChanged();
  emit selectionChanged();
}

void CarouselDocumentController::refreshPreviews() {
  if (!export_worker_context_) {
    QVector<int> boards;
    QSet<QString> items;
    for (int index = 0; index < slides_.size(); ++index) boards.push_back(index);
    for (const auto& item : items_) items.insert(item.id);
    queuePreviewRefresh(boards, items);
    return;
  }
  QDir().mkpath(previewsRoot());
  QVector<int> board_indices;
  board_indices.reserve(slides_.size());
  for (int index = 0; index < slides_.size(); ++index) {
    board_indices.push_back(index);
  }
  beginPreviewDiagnostics(QStringLiteral("full-document"), board_indices);
  ++preview_revision_;
  for (auto& item : items_) {
    refreshItemPreview(&item);
  }
  for (int index = 0; index < slides_.size(); ++index) {
    refreshPreviewAt(index);
  }
  finishPreviewDiagnostics();
}

void CarouselDocumentController::refreshPreviewAt(int index) {
  if (!export_worker_context_) {
    queuePreviewRefresh({index}, {});
    return;
  }
  if (index < 0 || index >= slides_.size()) {
    return;
  }

  QDir().mkpath(previewsRoot());
  QElapsedTimer layout_timer;
  layout_timer.start();
  const auto preview_size = exportPixelSize().scaled(kPreviewLongEdge, kPreviewLongEdge, Qt::KeepAspectRatio);
  preview_diagnostics_.insert(
      QStringLiteral("layoutMs"),
      preview_diagnostics_.value(QStringLiteral("layoutMs")).toDouble() + layout_timer.nsecsElapsed() / 1000000.0);
  QElapsedTimer render_timer;
  render_timer.start();
  const auto rendered = renderSlideBaseImage(index, preview_size, true);
  preview_diagnostics_.insert(
      QStringLiteral("renderMs"),
      preview_diagnostics_.value(QStringLiteral("renderMs")).toDouble() + render_timer.nsecsElapsed() / 1000000.0);
  QElapsedTimer publish_timer;
  publish_timer.start();
  writePreviewForSlide(index, rendered);
  preview_diagnostics_.insert(
      QStringLiteral("publishMs"),
      preview_diagnostics_.value(QStringLiteral("publishMs")).toDouble() + publish_timer.nsecsElapsed() / 1000000.0);
  preview_diagnostics_.insert(
      QStringLiteral("boardsRendered"),
      preview_diagnostics_.value(QStringLiteral("boardsRendered")).toInt() + 1);
}

void CarouselDocumentController::refreshItemPreview(CanvasItem* item) {
  if (item == nullptr) {
    return;
  }
  if (item->kind != ItemKind::Image || item->adjustment_patch_json.trimmed().isEmpty()) {
    item->preview_source.clear();
    item->preview_source_size = {};
    return;
  }
  if (!item->preview_source.isEmpty() && item->preview_source_size.isValid() &&
      QFileInfo::exists(QUrl(item->preview_source).toLocalFile())) {
    return;
  }

  item->preview_source.clear();
  item->preview_source_size = {};

  QImage preview;
  QElapsedTimer decode_timer;
  decode_timer.start();
  if (!decodeEditedImage(*item, &preview, true, kPreviewLongEdge) || preview.isNull()) {
    return;
  }
  preview_diagnostics_.insert(
      QStringLiteral("decodeMs"),
      preview_diagnostics_.value(QStringLiteral("decodeMs")).toDouble() + decode_timer.nsecsElapsed() / 1000000.0);
  preview_diagnostics_.insert(
      QStringLiteral("itemsDecoded"),
      preview_diagnostics_.value(QStringLiteral("itemsDecoded")).toInt() + 1);

  const auto path = previewPathForItem(item->id);
  QImageWriter writer(path, "png");
  if (!writer.write(preview)) {
    return;
  }
  item->preview_source = versionedLocalFile(path, preview_revision_);
  item->preview_source_size = QSizeF(preview.size());
}

void CarouselDocumentController::refreshCurrentSelectionPreviews() {
  QSet<int> affected_boards;
  QSet<QString> affected_item_ids;
  const auto add_intersected_boards = [this, &affected_boards](const CanvasItem& item) {
    for (int index = 0; index < slides_.size(); ++index) {
      if (slideRectInDocument(index).intersects(item.bounds)) {
        affected_boards.insert(index);
      }
    }
  };
  for (const auto& item_id : selected_item_ids_) {
    const auto item_index = indexOfItem(item_id);
    if (item_index >= 0) {
      affected_item_ids.insert(item_id);
      add_intersected_boards(items_.at(item_index));
      if (!repeatedElementLinkIdForComponent(items_.at(item_index).component_link_id).isEmpty()) {
        const auto component_id = items_.at(item_index).component_link_id;
        for (const auto& linked_item : items_) {
          if (linked_item.component_link_id == component_id) {
            affected_item_ids.insert(linked_item.id);
            add_intersected_boards(linked_item);
          }
        }
      }
    }
  }
  ++preview_revision_;
  if (const auto* group = groupForIndex(current_index_)) {
    for (int index = group->start_index; index < group->start_index + group->span; ++index) {
      affected_boards.insert(index);
    }
  } else if (affected_boards.isEmpty()) {
    affected_boards.insert(current_index_);
  }

  auto ordered_boards = affected_boards.values();
  std::sort(ordered_boards.begin(), ordered_boards.end());
  if (!export_worker_context_) {
    queuePreviewRefresh(ordered_boards, affected_item_ids);
    return;
  }
  QDir().mkpath(previewsRoot());
  beginPreviewDiagnostics(QStringLiteral("selected-content"), ordered_boards);
  for (const auto& item_id : affected_item_ids) {
    const auto item_index = indexOfItem(item_id);
    if (item_index >= 0) {
      refreshItemPreview(&items_[item_index]);
    }
  }
  for (const auto board_index : ordered_boards) {
    refreshPreviewAt(board_index);
  }
  finishPreviewDiagnostics();
}

void CarouselDocumentController::beginPreviewDiagnostics(
    const QString& reason,
    const QVector<int>& board_indices) {
  QVariantList invalidated;
  invalidated.reserve(board_indices.size());
  for (const auto index : board_indices) {
    invalidated.push_back(index);
  }
  preview_diagnostics_ = QVariantMap{
      {QStringLiteral("revision"), preview_revision_ + 1},
      {QStringLiteral("reason"), reason},
      {QStringLiteral("invalidatedBoardIndices"), invalidated},
      {QStringLiteral("boardsRendered"), 0},
      {QStringLiteral("itemsDecoded"), 0},
      {QStringLiteral("decodeMs"), 0.0},
      {QStringLiteral("layoutMs"), 0.0},
      {QStringLiteral("renderMs"), 0.0},
      {QStringLiteral("publishMs"), 0.0},
      {QStringLiteral("requestRevision"), static_cast<qulonglong>(preview_request_revision_)},
      {QStringLiteral("staleRequestsDropped"), stale_preview_requests_dropped_},
  };
  preview_diagnostics_active_ = true;
}

void CarouselDocumentController::finishPreviewDiagnostics() {
  const auto cache = decoded_image_cache_snapshot();
  preview_diagnostics_.insert(QStringLiteral("revision"), preview_revision_);
  preview_diagnostics_.insert(QStringLiteral("requestRevision"), static_cast<qulonglong>(preview_request_revision_));
  preview_diagnostics_.insert(QStringLiteral("staleRequestsDropped"), stale_preview_requests_dropped_);
  preview_diagnostics_.insert(QStringLiteral("cacheEntries"), cache.entries);
  preview_diagnostics_.insert(QStringLiteral("cacheBytes"), cache.bytes);
  preview_diagnostics_.insert(QStringLiteral("cacheBudgetBytes"), decoded_image_cache_budget_bytes());
  preview_diagnostics_active_ = false;
  emit previewDiagnosticsChanged();
}

QStringList CarouselDocumentController::normalizedSelectedItemIds(const QStringList& item_ids) const {
  QStringList normalized_ids;
  normalized_ids.reserve(item_ids.size());
  for (const auto& item_id : item_ids) {
    const auto normalized_id = item_id.trimmed();
    if (normalized_id.isEmpty() || indexOfItem(normalized_id) < 0 || normalized_ids.contains(normalized_id)) {
      continue;
    }
    normalized_ids.push_back(normalized_id);
  }
  return normalized_ids;
}

QVector<int> CarouselDocumentController::selectedItemIndexes(bool primary_slide_only, bool unlocked_only) const {
  QVector<int> indexes;
  indexes.reserve(selected_item_ids_.size());
  const auto selection_slide = currentSelectionSlideIndex();
  for (int index = 0; index < items_.size(); ++index) {
    const auto& item = items_.at(index);
    if (!selected_item_ids_.contains(item.id)) {
      continue;
    }
    if (primary_slide_only && selection_slide >= 0 && slideIndexForItem(item) != selection_slide) {
      continue;
    }
    if (unlocked_only && item.locked) {
      continue;
    }
    indexes.push_back(index);
  }
  return indexes;
}

QStringList CarouselDocumentController::itemIdsForObjectGroup(const QString& group_id) const {
  QStringList item_ids;
  const auto normalized_group_id = group_id.trimmed();
  if (normalized_group_id.isEmpty()) {
    return item_ids;
  }
  for (const auto& item : items_) {
    if (item.object_group_id == normalized_group_id) {
      item_ids.push_back(item.id);
    }
  }
  return item_ids;
}

QVector<int> CarouselDocumentController::constraintStackItemIndexes(
    const QString& stack_id) const {
  QVector<int> indexes;
  const auto normalized_stack_id = stack_id.trimmed();
  if (normalized_stack_id.isEmpty()) {
    return indexes;
  }
  for (int index = 0; index < items_.size(); ++index) {
    if (items_.at(index).constraint_stack_id == normalized_stack_id) {
      indexes.push_back(index);
    }
  }
  std::sort(indexes.begin(), indexes.end(), [this](int left, int right) {
    const auto left_order = items_.at(left).constraint_stack_order;
    const auto right_order = items_.at(right).constraint_stack_order;
    return left_order == right_order ? items_.at(left).id < items_.at(right).id
                                     : left_order < right_order;
  });
  return indexes;
}

QRectF CarouselDocumentController::constraintStackBounds(const QString& stack_id) const {
  const auto indexes = constraintStackItemIndexes(stack_id);
  if (indexes.isEmpty()) {
    return {};
  }
  QRectF content_bounds;
  for (const auto index : indexes) {
    content_bounds = content_bounds.isNull()
                         ? items_.at(index).bounds
                         : content_bounds.united(items_.at(index).bounds);
  }
  const auto padding = qBound(
      0.0, items_.at(indexes.constFirst()).constraint_stack_padding, 240.0);
  return content_bounds.adjusted(-padding, -padding, padding, padding);
}

bool CarouselDocumentController::relayoutConstraintStack(const QString& stack_id) {
  const auto indexes = constraintStackItemIndexes(stack_id);
  if (indexes.size() < 2) {
    return false;
  }
  if (std::any_of(indexes.cbegin(), indexes.cend(), [this](int index) {
        return items_.at(index).locked;
      })) {
    return false;
  }
  const auto& configuration = items_.at(indexes.constFirst());
  const auto horizontal = configuration.constraint_stack_axis == QStringLiteral("horizontal");
  const auto padding = qBound(0.0, configuration.constraint_stack_padding, 240.0);
  const auto gap = qBound(0.0, configuration.constraint_stack_gap, 240.0);
  const auto content_x = configuration.constraint_stack_anchor_x + padding;
  const auto content_y = configuration.constraint_stack_anchor_y + padding;
  auto cursor = horizontal ? content_x : content_y;
  bool changed = false;
  for (const auto index : indexes) {
    auto& item = items_[index];
    const QPointF next_top_left(
        horizontal ? cursor : content_x,
        horizontal ? content_y : cursor);
    if (item.bounds.topLeft() != next_top_left) {
      item.bounds.moveTopLeft(next_top_left);
      changed = true;
    }
    cursor += (horizontal ? item.bounds.width() : item.bounds.height()) + gap;
  }
  return changed;
}

void CarouselDocumentController::relayoutConstraintStackForItem(const QString& item_id) {
  const auto item_index = indexOfItem(item_id);
  if (item_index < 0 || items_.at(item_index).constraint_stack_id.isEmpty()) {
    return;
  }
  relayoutConstraintStack(items_.at(item_index).constraint_stack_id);
}

void CarouselDocumentController::normalizeConstraintStacks() {
  QHash<QString, QVector<int>> stack_indexes;
  for (int index = 0; index < items_.size(); ++index) {
    const auto stack_id = items_.at(index).constraint_stack_id.trimmed();
    if (!stack_id.isEmpty()) {
      stack_indexes[stack_id].push_back(index);
    }
  }
  for (auto iterator = stack_indexes.begin(); iterator != stack_indexes.end(); ++iterator) {
    auto indexes = iterator.value();
    if (indexes.size() < 2) {
      auto& item = items_[indexes.constFirst()];
      item.constraint_stack_id.clear();
      item.constraint_stack_order = -1;
      continue;
    }
    std::sort(indexes.begin(), indexes.end(), [this](int left, int right) {
      const auto left_order = items_.at(left).constraint_stack_order;
      const auto right_order = items_.at(right).constraint_stack_order;
      return left_order == right_order ? items_.at(left).id < items_.at(right).id
                                       : left_order < right_order;
    });
    const auto axis = items_.at(indexes.constFirst()).constraint_stack_axis ==
                              QStringLiteral("horizontal")
                          ? QStringLiteral("horizontal")
                          : QStringLiteral("vertical");
    const auto padding = qBound(
        0.0, items_.at(indexes.constFirst()).constraint_stack_padding, 240.0);
    const auto gap = qBound(
        0.0, items_.at(indexes.constFirst()).constraint_stack_gap, 240.0);
    const auto anchor_x = items_.at(indexes.constFirst()).constraint_stack_anchor_x;
    const auto anchor_y = items_.at(indexes.constFirst()).constraint_stack_anchor_y;
    for (int order = 0; order < indexes.size(); ++order) {
      auto& item = items_[indexes.at(order)];
      item.constraint_stack_order = order;
      item.constraint_stack_axis = axis;
      item.constraint_stack_padding = padding;
      item.constraint_stack_gap = gap;
      item.constraint_stack_anchor_x = anchor_x;
      item.constraint_stack_anchor_y = anchor_y;
    }
  }
}

QRectF CarouselDocumentController::selectedItemsBounds(bool unlocked_only) const {
  const auto indexes = selectedItemIndexes(false, unlocked_only);
  QRectF bounds;
  bool has_bounds = false;
  for (const auto index : indexes) {
    if (!has_bounds) {
      bounds = items_.at(index).bounds;
      has_bounds = true;
    } else {
      bounds = bounds.united(items_.at(index).bounds);
    }
  }
  return bounds;
}

void CarouselDocumentController::normalizeSelection() {
  setSelectedItemIds(selected_item_ids_, selected_item_id_);
}

void CarouselDocumentController::loadDesignLibrary() {
  user_templates_.clear();
  brand_kits_.clear();
  layout_recipes_.clear();
  favorite_template_ids_.clear();
  recent_template_ids_.clear();
  favorite_font_families_.clear();
  recent_font_families_.clear();
  custom_dictionary_words_.clear();
  const auto library = migrate_design_library(load_carousel_design_library());
  design_library_passthrough_ = library;
  for (const auto& value : library.value(QStringLiteral("templates")).toArray()) {
    if (value.isObject() && !value.toObject().value(QStringLiteral("templateId")).toString().isEmpty()) {
      user_templates_.push_back(value.toObject());
    }
  }
  for (const auto& value : library.value(QStringLiteral("brandKits")).toArray()) {
    if (value.isObject() && !value.toObject().value(QStringLiteral("brandId")).toString().isEmpty()) {
      brand_kits_.push_back(value.toObject());
    }
  }
  for (const auto& value : library.value(QStringLiteral("layoutRecipes")).toArray()) {
    if (!value.isObject()) {
      continue;
    }
    auto stored = value.toObject();
    if (stored.value(QStringLiteral("recipeId")).toString().isEmpty() ||
        !stored.value(QStringLiteral("layoutSettings")).isObject() ||
        !stored.value(QStringLiteral("boardTokens")).isObject()) {
      continue;
    }
    stored.insert(
        QStringLiteral("layoutSettings"),
        QJsonObject::fromVariantMap(normalized_layout_settings(
            stored.value(QStringLiteral("layoutSettings")).toObject().toVariantMap())));
    stored.insert(QStringLiteral("contentPolicy"), QStringLiteral("layout-only"));
    layout_recipes_.push_back(std::move(stored));
  }
  for (const auto& value : library.value(QStringLiteral("favoriteTemplateIds")).toArray()) {
    const auto template_id = value.toString().trimmed();
    if (templateLibraryIdExists(template_id) && !favorite_template_ids_.contains(template_id)) {
      favorite_template_ids_.push_back(template_id);
    }
  }
  for (const auto& value : library.value(QStringLiteral("recentTemplateIds")).toArray()) {
    const auto template_id = value.toString().trimmed();
    if (templateLibraryIdExists(template_id) && !recent_template_ids_.contains(template_id) &&
        recent_template_ids_.size() < 12) {
      recent_template_ids_.push_back(template_id);
    }
  }
  const auto installed_fonts = QFontDatabase::families();
  for (const auto& value : library.value(QStringLiteral("favoriteFontFamilies")).toArray()) {
    const auto family = normalized_text_font_family(value.toString());
    if (text_font_family_available(family, installed_fonts) &&
        !favorite_font_families_.contains(family, Qt::CaseInsensitive)) {
      favorite_font_families_.push_back(family);
    }
  }
  for (const auto& value : library.value(QStringLiteral("recentFontFamilies")).toArray()) {
    const auto family = normalized_text_font_family(value.toString());
    if (text_font_family_available(family, installed_fonts) &&
        !recent_font_families_.contains(family, Qt::CaseInsensitive) &&
        recent_font_families_.size() < 12) {
      recent_font_families_.push_back(family);
    }
  }
  for (const auto& value : library.value(QStringLiteral("customDictionaryWords")).toArray()) {
    const auto word = value.toString().trimmed().toLower();
    if (!word.isEmpty() && !custom_dictionary_words_.contains(word, Qt::CaseInsensitive)) {
      custom_dictionary_words_.push_back(word);
    }
  }
  favorite_font_families_.sort(Qt::CaseInsensitive);
  custom_dictionary_words_.sort(Qt::CaseInsensitive);
}

bool CarouselDocumentController::saveDesignLibrary() const {
  QJsonArray templates;
  for (const auto& stored : user_templates_) {
    templates.push_back(stored);
  }
  QJsonArray brand_kits;
  for (const auto& stored : brand_kits_) {
    brand_kits.push_back(stored);
  }
  QJsonArray layout_recipes;
  for (const auto& stored : layout_recipes_) {
    layout_recipes.push_back(stored);
  }
  QJsonObject library;
  library.insert(QStringLiteral("version"), kCarouselDesignLibrarySchemaVersion);
  library.insert(QStringLiteral("templates"), templates);
  library.insert(QStringLiteral("brandKits"), brand_kits);
  library.insert(QStringLiteral("layoutRecipes"), layout_recipes);
  library.insert(QStringLiteral("favoriteTemplateIds"), QJsonArray::fromStringList(favorite_template_ids_));
  library.insert(QStringLiteral("recentTemplateIds"), QJsonArray::fromStringList(recent_template_ids_));
  library.insert(QStringLiteral("favoriteFontFamilies"), QJsonArray::fromStringList(favorite_font_families_));
  library.insert(QStringLiteral("recentFontFamilies"), QJsonArray::fromStringList(recent_font_families_));
  library.insert(QStringLiteral("customDictionaryWords"), QJsonArray::fromStringList(custom_dictionary_words_));
  return save_carousel_design_library(
      merge_preserving_unknown_fields(design_library_passthrough_, library).toObject());
}

bool CarouselDocumentController::templateLibraryIdExists(const QString& template_id) const {
  if (template_id.isEmpty()) {
    return false;
  }
  for (const auto& value : sequenceTemplates()) {
    if (value.toMap().value(QStringLiteral("templateId")).toString() == template_id) {
      return true;
    }
  }
  return userTemplateById(template_id) != nullptr;
}

void CarouselDocumentController::recordRecentTemplateUse(const QString& template_id) {
  const auto normalized = template_id.trimmed();
  if (!templateLibraryIdExists(normalized)) {
    return;
  }
  recent_template_ids_.removeAll(normalized);
  recent_template_ids_.prepend(normalized);
  while (recent_template_ids_.size() > 12) {
    recent_template_ids_.removeLast();
  }
  saveDesignLibrary();
  emit designLibraryChanged();
}

QJsonObject* CarouselDocumentController::userTemplateById(const QString& template_id) {
  const auto normalized = template_id.trimmed();
  for (auto& stored : user_templates_) {
    if (stored.value(QStringLiteral("templateId")).toString() == normalized) {
      return &stored;
    }
  }
  return nullptr;
}

const QJsonObject* CarouselDocumentController::userTemplateById(const QString& template_id) const {
  const auto normalized = template_id.trimmed();
  for (const auto& stored : user_templates_) {
    if (stored.value(QStringLiteral("templateId")).toString() == normalized) {
      return &stored;
    }
  }
  return nullptr;
}

const QJsonObject* CarouselDocumentController::brandKitById(const QString& brand_id) const {
  const auto normalized = brand_id.trimmed();
  for (const auto& stored : brand_kits_) {
    if (stored.value(QStringLiteral("brandId")).toString() == normalized) {
      return &stored;
    }
  }
  return nullptr;
}

void CarouselDocumentController::emitCanvasStateChanged(bool slides_changed) {
  invalidatePreviewRefresh(false);
  synchronizePendingRepeatedElements();
  updateDocumentDirty();
  scheduleAutosave();
  if (!slides_changed && currentItem() != nullptr && !restoring_history_) {
    ++preview_request_revision_;
    if (preview_debounce_timer_->isActive()) {
      ++stale_preview_requests_dropped_;
    }
    preview_debounce_timer_->start();
  }
  emit itemsChanged();
  emit selectionChanged();
  emit brandLintChanged();
  emit preflightChanged();
  emit exportSettingsChanged();
  if (slides_changed) {
    emit slidesChanged();
  }
}

void CarouselDocumentController::markDocumentDirty() {
  ++autosave_revision_;
  if (!has_active_carousel_ || (document_dirty_ && save_state_ == QStringLiteral("Unsaved"))) {
    scheduleAutosave();
    return;
  }
  document_dirty_ = true;
  save_state_ = QStringLiteral("Unsaved");
  save_error_.clear();
  emit documentStateChanged();
  scheduleAutosave();
}

void CarouselDocumentController::rememberSavedContent() {
  saved_content_values_ = captureDocumentSnapshot();
  saved_content_snapshot_ = snapshotDocumentObject(*saved_content_values_);
  saved_content_snapshot_.remove(QStringLiteral("currentIndex"));
  saved_content_snapshot_.remove(QStringLiteral("activeSlot"));
  saved_content_snapshot_.remove(QStringLiteral("selectedItemId"));
  saved_content_snapshot_.remove(QStringLiteral("selectedItemIds"));
}

void CarouselDocumentController::updateDocumentDirty() {
  ++autosave_revision_;
  if (!has_active_carousel_) {
    return;
  }
  const bool next_dirty = !saved_content_values_ || !documentSnapshotsEqual(
      *saved_content_values_, *captureDocumentSnapshot(), true, &saved_content_snapshot_);
  const auto next_state = next_dirty ? QStringLiteral("Unsaved") : QStringLiteral("Saved");
  if (document_dirty_ == next_dirty && save_state_ == next_state && save_error_.isEmpty()) {
    return;
  }
  document_dirty_ = next_dirty;
  save_state_ = next_state;
  save_error_.clear();
  emit documentStateChanged();
}

void CarouselDocumentController::setSaveState(const QString& state, const QString& error) {
  const auto normalized_state = state.trimmed().isEmpty() ? QStringLiteral("Unsaved") : state.trimmed();
  if (save_state_ == normalized_state && save_error_ == error) {
    return;
  }
  save_state_ = normalized_state;
  save_error_ = error;
  emit documentStateChanged();
}

void CarouselDocumentController::setSelectedItemIds(
    const QStringList& item_ids,
    const QString& primary_item_id) {
  auto normalized_ids = normalizedSelectedItemIds(item_ids);
  auto normalized_primary = primary_item_id.trimmed();
  if (!normalized_primary.isEmpty() && !normalized_ids.contains(normalized_primary) &&
      indexOfItem(normalized_primary) >= 0) {
    normalized_ids.push_back(normalized_primary);
  }

  if (normalized_ids.isEmpty()) {
    if (!selected_item_ids_.isEmpty()) {
      clearSelectionBatchOperationPreview();
      clearRepeatGridPreview();
    }
    selected_item_id_.clear();
    selected_item_ids_.clear();
    return;
  }

  if (normalized_primary.isEmpty() || !normalized_ids.contains(normalized_primary)) {
    normalized_primary = normalized_ids.back();
  } else {
    normalized_ids.removeAll(normalized_primary);
    normalized_ids.push_back(normalized_primary);
  }

  if (selected_item_id_ != normalized_primary || selected_item_ids_ != normalized_ids) {
    clearSelectionBatchOperationPreview();
    clearRepeatGridPreview();
  }
  selected_item_id_ = normalized_primary;
  selected_item_ids_ = normalized_ids;
}

void CarouselDocumentController::setSelectedItemId(const QString& item_id) {
  setSelectedItemIds(item_id.trimmed().isEmpty() ? QStringList{} : QStringList{item_id}, item_id);
}

void CarouselDocumentController::setStatus(const QString& status) {
  const auto normalized = status.trimmed();
  const auto lower = normalized.toLower();
  const bool success_message = lower.startsWith(QStringLiteral("saved ")) ||
                               lower.startsWith(QStringLiteral("autosaved ")) ||
                               lower.startsWith(QStringLiteral("exported ")) ||
                               lower.startsWith(QStringLiteral("relinked ")) ||
                               lower.startsWith(QStringLiteral("substituted ")) ||
                               lower.startsWith(QStringLiteral("opened ")) ||
                               lower.startsWith(QStringLiteral("loaded ")) ||
                               lower.startsWith(QStringLiteral("added ")) ||
                               lower.startsWith(QStringLiteral("applied ")) ||
                               lower.startsWith(QStringLiteral("removed ")) ||
                               lower.startsWith(QStringLiteral("discarded ")) ||
                               lower.startsWith(QStringLiteral("resolved ")) ||
                               lower.startsWith(QStringLiteral("focused ")) ||
                               lower.startsWith(QStringLiteral("inspecting ")) ||
                               lower.startsWith(QStringLiteral("resized ")) ||
                               lower.startsWith(QStringLiteral("fit "));
  const bool failure_message = !success_message &&
                               (lower.contains(QStringLiteral("failed")) ||
                                lower.contains(QStringLiteral("unable")) ||
                                lower.contains(QStringLiteral("unavailable")) ||
                                lower.contains(QStringLiteral("missing")) ||
                                lower.contains(QStringLiteral("invalid")) ||
                                lower.contains(QStringLiteral("blocked")) ||
                                lower.contains(QStringLiteral("unsupported")) ||
                                lower.contains(QStringLiteral("not a supported")) ||
                                lower.contains(QStringLiteral("ambiguous")) ||
                                lower.contains(QStringLiteral("mismatch")) ||
                                lower.contains(QStringLiteral("does not fit")) ||
                                lower.contains(QStringLiteral("no verified")));
  if (failure_message && !normalized.isEmpty()) {
    QString category = QStringLiteral("details");
    QString action_key = QStringLiteral("inspect");
    QString action_label = QStringLiteral("Inspect");
    if (lower.contains(QStringLiteral("font"))) {
      category = QStringLiteral("font");
      action_key = QStringLiteral("resolve-fonts");
      action_label = QStringLiteral("Resolve Fonts");
    } else if (save_state_ == QStringLiteral("Save failed") ||
               lower.contains(QStringLiteral("save")) ||
               lower.contains(QStringLiteral("document helper"))) {
      category = QStringLiteral("save");
      action_key = QStringLiteral("retry-save");
      action_label = QStringLiteral("Retry Save");
    } else if (lower.contains(QStringLiteral("relink")) ||
               lower.contains(QStringLiteral("media")) ||
               lower.contains(QStringLiteral("image")) ||
               lower.contains(QStringLiteral("video")) ||
               lower.contains(QStringLiteral("image file")) ||
               lower.contains(QStringLiteral("video file"))) {
      category = QStringLiteral("media");
      action_key = QStringLiteral("relink-media");
      action_label = QStringLiteral("Relink Media");
    } else if (lower.contains(QStringLiteral("export"))) {
      category = QStringLiteral("export");
      action_key = QStringLiteral("open-export");
      action_label = QStringLiteral("Open Export");
    }
    bool duplicate = false;
    for (const auto& value : status_notices_) {
      if (value.toMap().value(QStringLiteral("message")).toString() == normalized) {
        duplicate = true;
        break;
      }
    }
    if (!duplicate) {
      while (status_notices_.size() >= 24) {
        status_notices_.removeFirst();
      }
      status_notices_.push_back(QVariantMap{
          {QStringLiteral("noticeId"), next_status_notice_id_++},
          {QStringLiteral("category"), category},
          {QStringLiteral("severity"), lower.contains(QStringLiteral("blocked")) ||
                                                 lower.contains(QStringLiteral("failed")) ||
                                                 lower.contains(QStringLiteral("unable"))
                                             ? QStringLiteral("error")
                                             : QStringLiteral("warning")},
          {QStringLiteral("message"), normalized},
          {QStringLiteral("actionKey"), action_key},
          {QStringLiteral("actionLabel"), action_label},
          {QStringLiteral("createdAt"), QDateTime::currentDateTime().toString(Qt::ISODate)},
      });
      emit statusNoticesChanged();
    }
  }
  if (status_ == status) {
    return;
  }
  status_ = status;
  emit statusChanged();
}

void CarouselDocumentController::dismissStatusNotice(int notice_id) {
  for (qsizetype index = status_notices_.size(); index > 0; --index) {
    if (status_notices_.at(index - 1).toMap().value(QStringLiteral("noticeId")).toInt() == notice_id) {
      status_notices_.removeAt(index - 1);
      emit statusNoticesChanged();
      return;
    }
  }
}

void CarouselDocumentController::clearStatusNotices() {
  if (status_notices_.isEmpty()) {
    return;
  }
  status_notices_.clear();
  emit statusNoticesChanged();
}

void CarouselDocumentController::setExportBusy(bool export_busy) {
  if (export_busy_ == export_busy) {
    return;
  }
  export_busy_ = export_busy;
  emit exportBusyChanged();
}

void CarouselDocumentController::assignImageToCurrentSlot(
    const QString& file_path,
    const QString& display_label,
    const QString& adjustment_patch_json,
    const QString& slot_name) {
  const auto normalized = normalized_path(file_path);
  if (!isImageFile(normalized)) {
    setStatus(QStringLiteral("That file is not a supported image format."));
    return;
  }

  const auto source_identity = source_file_identity(normalized);
  const auto canonical_adjustment_patch_json =
      adjustment_patch_json.trimmed().isEmpty()
          ? QString{}
          : canonical_asset_bound_adjustment_patch_json(
                adjustment_patch_json);
  if (!adjustment_patch_json.trimmed().isEmpty() &&
      canonical_adjustment_patch_json.isEmpty()) {
    setStatus(QStringLiteral("The selected photo adjustments are invalid."));
    return;
  }
  const auto recipe_state = recipeStateFromAdjustmentPayload(
      canonical_adjustment_patch_json);
  MediaItem media{
      .type = MediaType::Image,
      .file_path = normalized,
      .display_label = displayNameForPath(normalized, display_label),
      .adjustment_patch_json =
          canonical_adjustment_patch_json,
      .recipe_state = recipe_state,
      .fit_mode = FitMode::Cover,
      .scale = 1.0,
      .offset_x = 0.0,
      .offset_y = 0.0,
      .source_file_size = source_identity.file_size,
      .source_modified_ms = source_identity.modified_ms,
      .source_pixel_size = source_identity.pixel_size,
      .source_fingerprint = source_identity.fingerprint,
  };

  pushUndoState(QStringLiteral("Add media"));

  if (currentSelectionIsLinked()) {
    if (auto* group = groupForIndex(current_index_)) {
      group->media = media;
      refreshCurrentSelectionPreviews();
      emitCanvasStateChanged(true);
      setStatus(QStringLiteral("Updated the linked spread source image."));
    }
    return;
  }

  auto* slide = slideAt(current_index_);
  if (slide == nullptr) {
    return;
  }

  if (slot_name == QStringLiteral("secondary") && slide->template_kind == SlideTemplate::Single) {
    slide->template_kind = SlideTemplate::SplitPair;
  }
  if (slot_name == QStringLiteral("tertiary") && slide->template_kind != SlideTemplate::StackedTriptych) {
    slide->template_kind = SlideTemplate::StackedTriptych;
  }

  if (slot_name == QStringLiteral("secondary") &&
      (slide->template_kind == SlideTemplate::SplitPair || slide->template_kind == SlideTemplate::StackedTriptych)) {
    slide->secondary = media;
    active_slot_ = QStringLiteral("secondary");
    setStatus(slide->template_kind == SlideTemplate::SplitPair
                  ? QStringLiteral("Added an image to the secondary half.")
                  : QStringLiteral("Added an image to the middle slot."));
  } else if (slot_name == QStringLiteral("tertiary") &&
             slide->template_kind == SlideTemplate::StackedTriptych) {
    slide->tertiary = media;
    active_slot_ = QStringLiteral("tertiary");
    setStatus(QStringLiteral("Added an image to the bottom slot."));
  } else {
    if (slide->template_kind == SlideTemplate::Single) {
      slide->secondary = MediaItem{};
      slide->tertiary = MediaItem{};
    }
    slide->primary = media;
    active_slot_ = QStringLiteral("primary");
    setStatus(QStringLiteral("Added an image to the current slot."));
  }

  refreshCurrentSelectionPreviews();
  emitCanvasStateChanged(true);
}

void CarouselDocumentController::removeGroupAtIndex(int index, bool keep_current_media) {
  const auto* group = groupForIndex(index);
  if (group == nullptr) {
    return;
  }

  const auto group_copy = *group;
  clearGroupIndices(group_copy);
  for (qsizetype group_index = groups_.size(); group_index > 0; --group_index) {
    if (groups_[group_index - 1].id == group_copy.id) {
      groups_.removeAt(group_index - 1);
    }
  }

  const auto removed_slides = qMax(0, group_copy.span - 1);
  if (removed_slides > 0) {
    const auto slide_width = exportPixelSize().width();
    const auto removed_left = static_cast<double>((group_copy.start_index + 1) * slide_width);
    const auto removed_right = removed_left + static_cast<double>(removed_slides * slide_width);
    for (qsizetype item_index = items_.size(); item_index > 0; --item_index) {
      auto& item = items_[item_index - 1];
      const auto center_x = item.bounds.center().x();
      if (center_x >= removed_left && center_x < removed_right) {
        items_.removeAt(item_index - 1);
        continue;
      }
      if (center_x >= removed_right) {
        item.bounds.translate(-static_cast<double>(slide_width * removed_slides), 0.0);
      }
    }
  }

  current_index_ = group_copy.start_index;
  normalizeSelection();
  if (group_copy.span > 1) {
    slides_.remove(group_copy.start_index + 1, group_copy.span - 1);
  }

  auto* slide = slideAt(current_index_);
  if (slide != nullptr) {
    slide->linked_group_id.clear();
    slide->template_kind = SlideTemplate::Single;
    slide->secondary = MediaItem{};
    slide->tertiary = MediaItem{};
    if (keep_current_media) {
      slide->primary = group_copy.media;
    }
  }

  rebuildGroupIndices();
  normalizeBoardSections();
  ensureCurrentIndexValid();
}

void CarouselDocumentController::clearGroupIndices(const LinkedGroup& group) {
  for (int index = group.start_index; index < group.start_index + group.span && index < slides_.size(); ++index) {
    if (auto* slide = slideAt(index)) {
      slide->linked_group_id.clear();
    }
  }
}

void CarouselDocumentController::rebuildGroupIndices() {
  for (qsizetype group_index = groups_.size(); group_index > 0; --group_index) {
    auto& group = groups_[group_index - 1];
    int first_index = -1;
    int span = 0;
    for (int slide_index = 0; slide_index < slides_.size(); ++slide_index) {
      if (slides_[slide_index].linked_group_id == group.id) {
        if (first_index < 0) {
          first_index = slide_index;
        }
        ++span;
      }
    }

    if (first_index < 0 || span == 0) {
      groups_.removeAt(group_index - 1);
      continue;
    }

    group.start_index = first_index;
    group.span = span;
  }
}

bool CarouselDocumentController::ensureCapacityForGroup(int start_index, int span) {
  const int additional_slides = qMax(0, span - 1);
  if (static_cast<int>(slides_.size()) + additional_slides > kMaxSlides) {
    return false;
  }

  for (int offset = 0; offset < additional_slides; ++offset) {
    slides_.insert(start_index + 1 + offset, Slide{});
  }
  adjustItemsForSlidesShifted(start_index + 1, additional_slides);
  rebuildGroupIndices();
  return true;
}

void CarouselDocumentController::normalizeForCurrentTemplate() {
  const auto* slide = slideAt(current_index_);
  if (slide == nullptr || slide->template_kind == SlideTemplate::Single) {
    active_slot_ = QStringLiteral("primary");
    return;
  }
  if (slide->template_kind == SlideTemplate::SplitPair && active_slot_ == QStringLiteral("tertiary")) {
    active_slot_ = QStringLiteral("primary");
  }
}

void CarouselDocumentController::writePreviewForSlide(int index, const QImage& image) {
  const auto path = previewPathForSlide(index);
  QImageWriter writer(path, "png");
  if (!writer.write(image)) return;
  if (auto* slide = slideAt(index)) {
    slide->preview_source = versionedLocalFile(path, preview_revision_);
  }
}

